window.songs=[{"order":1,"id":"01-la-journee-est-finie","title":"La Journée est finie","titleZh":"这一天结束了","lines":[{"id":"les-miserables-1980-01-001","lineIndex":1,"speaker":"Trois ouvrières","original":"La journée est finie quatorze heures à la peine","ipa":"/la ʒuʁne ɛ fini katɔʁz œʁz a la pɛn/","zh":"一天结束了，苦工干了十四小时。","en":"The day is over: fourteen hours of toil.","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-01-002","lineIndex":2,"speaker":"Trois ouvrières","original":"Le nez sur l'établi quatorze heures à la chaîne","ipa":"/lə ne syʁ letabli katɔʁz œʁz a la ʃɛn/","zh":"伏在工作台上，流水线干了十四小时。","en":"Bent over the workbench, fourteen hours on the line.","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-01-003","lineIndex":3,"speaker":"Trois ouvrières","original":"C'est fini, ça recommence","ipa":"/sɛ fini sa ʁəkɔmɑ̃s/","zh":"结束了，又得重新开始。","en":"It's over; it starts all over again.","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-01-004","lineIndex":4,"speaker":"Trois ouvrières","original":"Dans la vie, nous les femmes, on a la chance","ipa":"/dɑ̃ la vi nu le fam ɔ̃n a la ʃɑ̃s/","zh":"这世上，我们女人倒真有“福气”。","en":"In life, we women are so “lucky.”","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-01-005","lineIndex":5,"speaker":"Trois ouvrières","original":"D'avoir un deuxième patron à la maison","ipa":"/davwaʁ œ̃ døzjɛm patʁɔ̃ a la mɛzɔ̃/","zh":"在家里还得伺候第二个老板","en":"To have a second boss at home","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-01-006","lineIndex":6,"speaker":"Trois ouvrières","original":"Que l'on sert en silence","ipa":"/kə lɔ̃ sɛʁ ɑ̃ silɑ̃s/","zh":"还得默默侍候。","en":"whom we serve in silence.","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-01-007","lineIndex":7,"speaker":"Hommes","original":"La journée est finie, bien finie la journée","ipa":"/la ʒuʁne ɛ fini bjɛ̃ fini la ʒuʁne/","zh":"一天终于结束了。","en":"The day is over—well and truly over.","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-01-008","lineIndex":8,"speaker":"Hommes","original":"On a bien mérité le pot de l'amitié","ipa":"/ɔ̃n a bjɛ̃ meʁite lə po də lamitje/","zh":"我们当然配得上一杯友情酒。","en":"We have earned a friendly drink.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-01-009","lineIndex":9,"speaker":"Hommes","original":"Le dernier que l'on se jette","ipa":"/lə dɛʁnje kə lɔ̃ sə ʒɛt/","zh":"临别前共饮的最后一杯","en":"the last one we share","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-01-010","lineIndex":10,"speaker":"Hommes","original":"Attendant que la soupe soit enfin prête","ipa":"/atɑ̃dɑ̃ kə la sup swa ɑ̃fɛ̃ pʁɛt/","zh":"等汤终于煮好","en":"waiting for the soup to finally be ready","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-01-011","lineIndex":11,"speaker":"Hommes","original":"Et d'aller dormir enfin jusqu'à demain","ipa":"/e dale dɔʁmiʁ ɑ̃fɛ̃ ʒyska dəmɛ̃/","zh":"再睡上一觉直到明天","en":"then finally going to sleep until tomorrow","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-01-012","lineIndex":12,"speaker":"Hommes","original":"Sans demander son reste","ipa":"/sɑ̃ dəmɑ̃de sɔ̃ ʁɛst/","zh":"不再奢求更多。","en":"without asking for anything more.","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-01-013","lineIndex":13,"speaker":"Tous","original":"Aime ce que tu as quand t'as pas ce que t'aimes","ipa":"/ɛm sə kə ty a kɑ̃ ta pa sə kə tɛm/","zh":"没有心中所爱时，就爱眼前所有。","en":"Love what you have when you don't have what you love","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-01-014","lineIndex":14,"speaker":"Tous","original":"Quand t'as pas ce que t'aimes, aime ce que tu as","ipa":"/kɑ̃ ta pa sə kə tɛm ɛm sə kə ty a/","zh":"没有心中所爱，就珍惜手中所有。","en":"When you don't have what you love, love what you have","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-01-015","lineIndex":15,"speaker":"Tous","original":"Et nous autres comme on n'a rien","ipa":"/e nuz otʁ kɔm ɔ̃ na ʁjɛ̃/","zh":"而我们这些人，什么都没有","en":"And as for us, we have nothing","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-01-016","lineIndex":16,"speaker":"Tous","original":"Ni le superflu ni le nécessaire","ipa":"/ni lə sypɛʁfly ni lə nesɛsɛʁ/","zh":"既没有奢侈品，也没有必需品。","en":"neither luxuries nor necessities.","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-01-017","lineIndex":17,"speaker":"Tous","original":"On ne peut que s'aimer bien","ipa":"/ɔ̃ nə pø kə sɛme bjɛ̃/","zh":"我们只能彼此相亲相爱","en":"We can only care for one another","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-01-018","lineIndex":18,"speaker":"Tous","original":"Pour mettre un peu d'azur dans notre enfer","ipa":"/puʁ mɛtʁ œ̃ pø dazyʁ dɑ̃ notʁ ɑ̃fɛʁ/","zh":"为我们的地狱添上一点蓝色","en":"To put a little azure in our hell","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-01-019","lineIndex":19,"speaker":"Tous","original":"Et pouvoir encore sourire, continuer à vivre","ipa":"/e puvwaʁ ɑ̃kɔʁ suʁiʁ kɔ̃tinye a vivʁ/","zh":"并且依然能够微笑，继续生活","en":"And still be able to smile, to continue living","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-01-020","lineIndex":20,"speaker":"Femmes","original":"S'il n'est pas trop crevé, si j'ai encore la force","ipa":"/sil nɛ pa tʁo kʁəve si ʒe ɑ̃kɔʁ la fɔʁs/","zh":"只要他没累垮、我还有力气","en":"If he is not too exhausted and I still have the strength","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-01-021","lineIndex":21,"speaker":"Femmes","original":"Nous on se fait du bien quand les enfants s'endorment","ipa":"/nuz ɔ̃ sə fɛ dy bjɛ̃ kɑ̃ lez ɑ̃fɑ̃ sɑ̃dɔʁm/","zh":"等孩子睡着，我们便相互温存。","en":"we comfort one another when the children fall asleep.","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-01-022","lineIndex":22,"speaker":"Femmes","original":"Entre nous et les bourgeois c'est avec la mort, ma foi","ipa":"/ɑ̃tʁ nuz e le buʁʒwa sɛ avɛk la mɔʁ ma fwa/","zh":"依我看，我们和资产者之间，只有死亡才平等","en":"Between us and the bourgeoisie, by my faith, death is the only equalizer","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-01-023","lineIndex":23,"speaker":"Femmes","original":"Le seul moment où y a pas de différence","ipa":"/lə sœl momɑ̃ u i a pa sə difeʁɑ̃s/","zh":"那是唯一没有差别的时刻。","en":"the only moment when there is no difference.","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-01-024","lineIndex":24,"speaker":"Femmes","original":"Et voilà nos vacances","ipa":"/e vwala no vakɑ̃s/","zh":"这就是我们的“假期”。","en":"And that is our vacation.","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-01-025","lineIndex":25,"speaker":"Femmes","original":"T'as vu? Le contremaître avait l'air contrarié","ipa":"/ta vy lə kɔ̃tʁəmɛtʁ avɛ lɛʁ kɔ̃tʁaʁje/","zh":"你看到了吗？工头看上去很沮丧","en":"Did you see? The foreman looked upset","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-01-026","lineIndex":26,"speaker":"Femmes","original":"C'est la faute à la Louise qui l'a laissé tomber","ipa":"/sɛ la fot a la lwiz ki la lɛse tɔ̃be/","zh":"都怪露易丝，没让他得逞。","en":"It's Louise's fault; she let him down.","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-01-027","lineIndex":27,"speaker":"Femmes","original":"Si le patron savait qu'il nous fait des avances","ipa":"/si lə patʁɔ̃ savɛ kil nu fɛ dez avɑ̃s/","zh":"如果老板知道他对我们动手动脚","en":"If the boss knew he was making unwanted advances toward us","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-01-028","lineIndex":28,"speaker":"Femmes","original":"Il perdrait de sa morgue et de sa suffisance","ipa":"/il pɛʁdʁɛ də sa mɔʁɡ e də sa syfizɑ̃s/","zh":"他就会失去他的傲慢和自负","en":"He would lose his arrogance and his self-importance","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-01-029","lineIndex":29,"speaker":"Femmes","original":"Le bon Monsieur Madeleine, qui ne permet pas qu'on se joue de la morale","ipa":"/lə bɔ̃ məsjø madlɛn ki nə pɛʁmɛ pa kɔ̃ sə ʒu də la moʁal/","zh":"善良的马德兰先生，不容人拿道德开玩笑。","en":"The good Monsieur Madeleine does not allow anyone to make a mockery of morality.","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-01-030","lineIndex":30,"speaker":"Femmes","original":"Et il le prendrait très mal","ipa":"/e il lə pʁɑ̃dʁɛ tʁɛ mal/","zh":"他一定会暴跳如雷。","en":"And he would take it very badly.","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-01-031","lineIndex":31,"speaker":"Tous","original":"Aime ce que tu as quand t'as pas ce que t'aimes","ipa":"/ɛm sə kə ty a kɑ̃ ta pa sə kə tɛm/","zh":"当你没有你所爱的东西时，爱你所拥有的","en":"Love what you have when you don't have what you love","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-01-032","lineIndex":32,"speaker":"Tous","original":"Quand t'as pas ce que t'aimes, aime ce que tu as","ipa":"/kɑ̃ ta pa sə kə tɛm ɛm sə kə ty a/","zh":"当你没有你所爱的东西时，爱你所拥有的","en":"When you don't have what you love, love what you have","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-01-033","lineIndex":33,"speaker":"Tous","original":"Et nous autres comme on n'a rien","ipa":"/e nuz otʁ kɔm ɔ̃ na ʁjɛ̃/","zh":"而我们这些人什么也没有","en":"And as for us, we have nothing","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-01-034","lineIndex":34,"speaker":"Tous","original":"Ni le superflu ni le nécessaire","ipa":"/ni lə sypɛʁfly ni lə nesɛsɛʁ/","zh":"既没有奢侈品，也没有必需品","en":"neither luxuries nor necessities","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-01-035","lineIndex":35,"speaker":"Tous","original":"On ne peut que s'aimer bien","ipa":"/ɔ̃ nə pø kə sɛme bjɛ̃/","zh":"只能彼此相亲相爱","en":"we can only care for one another","note":"","sourceLineIndex":35},{"id":"les-miserables-1980-01-036","lineIndex":36,"speaker":"Tous","original":"Pour mettre un peu d'azur dans notre enfer","ipa":"/puʁ mɛtʁ œ̃ pø dazyʁ dɑ̃ notʁ ɑ̃fɛʁ/","zh":"为我们的地狱添上一点蓝色","en":"To put a little azure in our hell","note":"","sourceLineIndex":36},{"id":"les-miserables-1980-01-037","lineIndex":37,"speaker":"Tous","original":"Et pouvoir encore sourire, continuer à vivre","ipa":"/e puvwaʁ ɑ̃kɔʁ suʁiʁ kɔ̃tinye a vivʁ/","zh":"并且依然能够微笑，继续生活","en":"And still be able to smile, to continue living","note":"","sourceLineIndex":37},{"id":"les-miserables-1980-01-038","lineIndex":38,"speaker":"Une Mégère","original":"Est-ce ton amoureux qui t'écrit en cachette?","ipa":"/ɛs tɔ̃n amuʁø ki tekʁit ɑ̃ kaʃɛt/","zh":"是你的爱人偷偷给你写信吗？","en":"Is it your lover who writes to you in secret?","note":"","sourceLineIndex":38},{"id":"les-miserables-1980-01-039","lineIndex":39,"speaker":"Une Mégère","original":"Fantine, fais-nous voir ce qui est dans cette lettre","ipa":"/fɑ̃tin fɛnu vwaʁ sə ki ɛ dɑ̃ sɛt lɛtʁ/","zh":"芳汀，让我们看看这封信里写了什么","en":"Fantine, let us see what is in this letter","note":"","sourceLineIndex":39},{"id":"les-miserables-1980-01-040","lineIndex":40,"speaker":"Une Mégère","original":"Envoyez quinze francs, malade votre enfant","ipa":"/ɑ̃vwaje kɛ̃z fʁɑ̃ malad votʁ ɑ̃fɑ̃/","zh":"寄十五法郎，你的孩子生病了","en":"Send fifteen francs, sick your child","note":"","sourceLineIndex":40},{"id":"les-miserables-1980-01-041","lineIndex":41,"speaker":"Une Mégère","original":"Risque la mort sous peu vite, il faut la sauver","ipa":"/ʁisk la mɔʁ su pø vit il fo la sove/","zh":"很快就会有死亡危险，我们必须救她","en":"Risk of death soon, we must save her","note":"","sourceLineIndex":41},{"id":"les-miserables-1980-01-042","lineIndex":42,"speaker":"Une Mégère","original":"C'est signé Thénardier","ipa":"/sɛ sinje tenaʁdje/","zh":"上面有泰纳第签名","en":"It's signed Thénardier","note":"","sourceLineIndex":42},{"id":"les-miserables-1980-01-043","lineIndex":43,"speaker":"Fantine","original":"Rendez-moi ma lettre, ravalez votre haine","ipa":"/ʁɑ̃demwa ma lɛtʁ ʁavale votʁ ɛn/","zh":"把信还给我，收回你们的恶意。","en":"Give me back my letter; swallow your spite.","note":"","sourceLineIndex":43},{"id":"les-miserables-1980-01-044","lineIndex":44,"speaker":"Fantine","original":"Pensez à vos misères, et laissez-moi la mienne","ipa":"/pɑ̃sez a vo mizɛʁ e lɛsemwa la mjɛn/","zh":"管好你们自己的苦难，把我的留给我。","en":"Think of your own miseries, and leave me mine.","note":"","sourceLineIndex":44},{"id":"les-miserables-1980-01-045","lineIndex":45,"speaker":"Fantine","original":"Allez rentrez vite, vos maîtres vous attendent","ipa":"/ale ʁɑ̃tʁe vit vo mɛtʁ vuz atɑ̃d/","zh":"快点回家，你的主人在等你","en":"Go home quickly, your masters are waiting for you","note":"","sourceLineIndex":45},{"id":"les-miserables-1980-01-046","lineIndex":46,"speaker":"Fantine","original":"Oh, pardon vos maris, vous qui en avez un qui partage votre vie","ipa":"/ɔ paʁdɔ̃ vo maʁi vu ki ɑ̃n avez œ̃ ki paʁtaʒ votʁ vi/","zh":"哦，抱歉啊，各位有丈夫、有人与你们共度人生的女士。","en":"Oh, pardon me, you whose husbands share your lives.","note":"","sourceLineIndex":46},{"id":"les-miserables-1980-01-047","lineIndex":47,"speaker":"Valjean","original":"Séparez-vous, je vous l'ordonne","ipa":"/sepaʁevu ʒə vu lɔʁdɔn/","zh":"分开吧，我命令你","en":"Separate yourselves, I order you","note":"","sourceLineIndex":47},{"id":"les-miserables-1980-01-048","lineIndex":48,"speaker":"Valjean","original":"Je ne conduis pas un troupeau","ipa":"/ʒə nə kɔ̃dɥi paz œ̃ tʁupo/","zh":"我带的不是一群牲口。","en":"I do not lead a herd.","note":"","sourceLineIndex":48},{"id":"les-miserables-1980-01-049","lineIndex":49,"speaker":"Valjean","original":"C'est une usine que je mène","ipa":"/sɛt yn yzin kə ʒə mɛn/","zh":"这是我经营的工厂","en":"It's a factory that I run","note":"","sourceLineIndex":49},{"id":"les-miserables-1980-01-050","lineIndex":50,"speaker":"Valjean","original":"Avant de vous prendre aux cheveux","ipa":"/avɑ̃ də vu pʁɑ̃dʁ o ʃəvø/","zh":"在你们扯头发之前","en":"before you start pulling each other's hair","note":"","sourceLineIndex":50},{"id":"les-miserables-1980-01-051","lineIndex":51,"speaker":"Valjean","original":"Et quel que soit le différend","ipa":"/e kɛl kə swa lə difeʁɑ̃/","zh":"无论有什么争议","en":"And whatever the dispute","note":"","sourceLineIndex":51},{"id":"les-miserables-1980-01-052","lineIndex":52,"speaker":"Valjean","original":"Dont vous allez me faire l'aveu","ipa":"/dɔ̃ vuz ale mə fɛʁ lavø/","zh":"你们来向我坦白的","en":"which you are about to confess to me","note":"","sourceLineIndex":52},{"id":"les-miserables-1980-01-053","lineIndex":53,"speaker":"Valjean","original":"Sachez rester dignes quand même","ipa":"/saʃe ʁɛste dinj kɑ̃ mɛm/","zh":"也请保持尊严。","en":"please remain dignified.","note":"","sourceLineIndex":53},{"id":"les-miserables-1980-01-054","lineIndex":54,"speaker":"Valjean","original":"Et maintenant qu'on me révèle","ipa":"/e mɛ̃tnɑ̃ kɔ̃ mə ʁevɛl/","zh":"那么现在，谁来告诉我","en":"And now, let someone tell me","note":"","sourceLineIndex":54},{"id":"les-miserables-1980-01-055","lineIndex":55,"speaker":"Valjean","original":"Les raisons de cette querelle","ipa":"/le ʁɛzɔ̃ də sɛt kʁɛl/","zh":"这次争吵的原因","en":"The reasons for this quarrel","note":"","sourceLineIndex":55},{"id":"les-miserables-1980-01-056","lineIndex":56,"speaker":"Deux Femmes","original":"Bravo, mademoiselle, on la croyait sérieuse","ipa":"/bʁavo madmwazɛl ɔ̃ la kʁwajɛ seʁjøz/","zh":"好啊，小姐，我们原以为她挺正经。","en":"Well done, miss; we thought she was respectable.","note":"","sourceLineIndex":56},{"id":"les-miserables-1980-01-057","lineIndex":57,"speaker":"Deux Femmes","original":"Mais elle était la nuit tout autant travailleuse","ipa":"/mɛz ɛl etɛ la nɥi tut otɑ̃ tʁavajøz/","zh":"可原来她夜里也一样“勤快”。","en":"But at night she was just as “hardworking.”","note":"","sourceLineIndex":57},{"id":"les-miserables-1980-01-058","lineIndex":58,"speaker":"Deux Femmes","original":"La Fantine est fille-mère","ipa":"/la fɑ̃tin ɛ fijmɛʁ/","zh":"芳汀未婚生子。","en":"Fantine is an unmarried mother.","note":"","sourceLineIndex":58},{"id":"les-miserables-1980-01-059","lineIndex":59,"speaker":"Deux Femmes","original":"Mais malheur à celle qui trop tôt gaspille","ipa":"/mɛ malœʁ a sɛl ki tʁo to ɡaspij/","zh":"但不幸的是，她很快就浪费了","en":"But woe to the one who wastes too soon","note":"","sourceLineIndex":59},{"id":"les-miserables-1980-01-060","lineIndex":60,"speaker":"Deux Femmes","original":"La vertu, seule fortune des pauvres filles","ipa":"/la vɛʁty sœl fɔʁtyn de povʁ fij/","zh":"美德，可怜女孩唯一的财富","en":"Virtue, the only fortune of poor girls","note":"","sourceLineIndex":60},{"id":"les-miserables-1980-01-061","lineIndex":61,"speaker":"Deux Femmes","original":"Tant pis, tant pis pour elle","ipa":"/tɑ̃pi tɑ̃pi puʁ ɛl/","zh":"那她可就倒霉了。","en":"Too bad for her, too bad.","note":"","sourceLineIndex":61},{"id":"les-miserables-1980-01-062","lineIndex":62,"speaker":"Tous","original":"Bravo, mademoiselle, on te voit à l'église","ipa":"/bʁavo madmwazɛl ɔ̃ tə vwa a leɡliz/","zh":"好啊，小姐，我们在教堂见过你","en":"Well done, miss; we see you in church","note":"","sourceLineIndex":62},{"id":"les-miserables-1980-01-063","lineIndex":63,"speaker":"Tous","original":"Mais c'est pour d'autres messes que tu ôtes ta chemise","ipa":"/mɛ sɛ puʁ dotʁ mɛs kə ty ot ta ʃəmiz/","zh":"可你脱下衬衫，是为了参加别的“弥撒”。","en":"but you take off your blouse for other “masses.”","note":"","sourceLineIndex":63},{"id":"les-miserables-1980-01-064","lineIndex":64,"speaker":"Tous","original":"Et bien sûr elle va nous dire","ipa":"/e bjɛ̃ syʁ ɛl va nu diʁ/","zh":"当然她会告诉我们","en":"And of course she's going to tell us","note":"","sourceLineIndex":64},{"id":"les-miserables-1980-01-065","lineIndex":65,"speaker":"Tous","original":"Que de lui elle était très amoureuse","ipa":"/kə də lɥi ɛl etɛ tʁɛz amuʁøz/","zh":"她非常爱他","en":"That she was very in love with him","note":"","sourceLineIndex":65},{"id":"les-miserables-1980-01-066","lineIndex":66,"speaker":"Tous","original":"Mais Jésus, gare au serpent","ipa":"/mɛ ʒezy ɡaʁ o sɛʁpɑ̃/","zh":"但是天啊，小心那条蛇","en":"But Jesus, beware of the snake","note":"","sourceLineIndex":66},{"id":"les-miserables-1980-01-067","lineIndex":67,"speaker":"Tous","original":"Sa piqûre est parfois venimeuse","ipa":"/sa pikyʁ ɛ paʁfwa vənimøz/","zh":"它的刺有时是有毒的","en":"Her sting is sometimes venomous","note":"","sourceLineIndex":67},{"id":"les-miserables-1980-01-068","lineIndex":68,"speaker":"Tous","original":"Et les hommes c'est tout pareil malheur à qui leur cède","ipa":"/e lez ɔm sɛ tu paʁɛj malœʁ a ki lœʁ sɛd/","zh":"男人也一样；向他们让步的人可要遭殃。","en":"Men are just the same; woe to anyone who yields to them.","note":"","sourceLineIndex":68},{"id":"les-miserables-1980-01-069","lineIndex":69,"speaker":"Tous","original":"Bravo, mademoiselle, on n'a que ce qu'on sème","ipa":"/bʁavo madmwazɛl ɔ̃ na kə sə kɔ̃ sɛm/","zh":"好啊，小姐，种什么得什么。","en":"Well done, miss; you reap what you sow.","note":"","sourceLineIndex":69},{"id":"les-miserables-1980-01-070","lineIndex":70,"speaker":"Tous","original":"Cette sainte nitouche y a touché quand même!","ipa":"/sɛt sɛ̃t nituʃ i a tuʃe kɑ̃ mɛm/","zh":"这个装清纯的，到底也没守住身子！","en":"This prim little hypocrite has done it after all!","note":"","sourceLineIndex":70},{"id":"les-miserables-1980-01-071","lineIndex":71,"speaker":"Valjean","original":"Je ne veux pas d'histoire de cette sorte","ipa":"/ʒə nə vø pa distwaʁ də sɛt sɔʁt/","zh":"我不想要这样的故事","en":"I don't want a story like that","note":"","sourceLineIndex":71},{"id":"les-miserables-1980-01-072","lineIndex":72,"speaker":"Valjean","original":"Voilà cinquante francs je vous mets à la porte!","ipa":"/vwala sɛ̃kɑ̃t fʁɑ̃ ʒə vu mɛz a la pɔʁt/","zh":"这是五十法郎，我会把你扔出去！","en":"Here's fifty francs, I'll throw you out!","note":"","sourceLineIndex":72}],"sourceOrder":1,"displayOrder":1},{"order":2,"id":"02-l-air-de-la-misere","title":"L'Air de la Misère","titleZh":"苦难之歌","lines":[{"id":"les-miserables-1980-02-001","lineIndex":1,"speaker":"Fantine","original":"J'avais de si jolis défauts","ipa":"/ʒavɛ də si ʒoli defo/","zh":"我也曾有过这样可爱的缺点。","en":"I once had such pretty flaws.","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-02-002","lineIndex":2,"speaker":"Fantine","original":"J'étais rêveuse, j'étais coquette","ipa":"/ʒetɛ ʁɛvøz ʒetɛ kokɛt/","zh":"我爱做梦，也爱打扮。","en":"I was dreamy; I liked to dress up.","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-02-003","lineIndex":3,"speaker":"Fantine","original":"Un peu naïve, mais pas trop","ipa":"/œ̃ pø naiv mɛ pa tʁo/","zh":"有点天真，却不至于傻。","en":"A little naive, but not too much so.","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-02-004","lineIndex":4,"speaker":"Fantine","original":"Pour ne jamais perdre la tête","ipa":"/puʁ nə ʒamɛ pɛʁdʁ la tɛt/","zh":"却从不昏头。","en":"Never losing my head.","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-02-005","lineIndex":5,"speaker":"Fantine","original":"Et je me faisais fête","ipa":"/e ʒə mə fəzɛ fɛt/","zh":"一声鸟鸣、一天新开始","en":"I found joy","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-02-006","lineIndex":6,"speaker":"Fantine","original":"D'un chant d'oiseau, d'un jour nouveau","ipa":"/dœ̃ ʃɑ̃ dwazo dœ̃ ʒuʁ nuvo/","zh":"都能让我欢喜。","en":"in a bird's song, in a new day.","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-02-007","lineIndex":7,"speaker":"Fantine","original":"Je n'ai plus qu'une robe grise","ipa":"/ʒə ne ply kyn ʁɔb ɡʁiz/","zh":"我只剩一件灰裙子","en":"All I have left is a gray dress","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-02-008","lineIndex":8,"speaker":"Fantine","original":"Qui sert aussi de couverture","ipa":"/ki sɛʁ osi də kuvɛʁtyʁ/","zh":"还得兼作被子。","en":"which also serves as a blanket.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-02-009","lineIndex":9,"speaker":"Fantine","original":"Quand le vent glacé de l'hiver","ipa":"/kɑ̃ lə vɑ̃ ɡlase də livɛʁ/","zh":"每当冬日的寒风","en":"When the icy winter wind","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-02-010","lineIndex":10,"speaker":"Fantine","original":"Tourne la nuit dans ma masure","ipa":"/tuʁn la nɥi dɑ̃ ma mazyʁ/","zh":"夜里在我的破屋中盘旋。","en":"swirls at night through my hovel.","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-02-011","lineIndex":11,"speaker":"Fantine","original":"Et plus beaucoup d'honneur","ipa":"/e ply boku dɔnœʁ/","zh":"心底的荣誉与尊严","en":"And little honor remains","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-02-012","lineIndex":12,"speaker":"Fantine","original":"De dignité au fond du cœur","ipa":"/də diɲite o fɔ̃ dy kœʁ/","zh":"也所剩无几。","en":"little dignity deep in my heart.","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-02-013","lineIndex":13,"speaker":"Fantine","original":"La misère n'est mère de personne","ipa":"/la mizɛʁ nɛ mɛʁ də pɛʁsɔn/","zh":"苦难不是任何人的母亲","en":"Misery is nobody's mother","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-02-014","lineIndex":14,"speaker":"Fantine","original":"La misère est pourtant soeur des hommes","ipa":"/la mizɛʁ ɛ puʁtɑ̃ sœʁ dez ɔm/","zh":"可苦难却是人类的姐妹","en":"Yet misery is mankind's sister","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-02-015","lineIndex":15,"speaker":"Fantine","original":"Mais personne sur terre n'en veut pour fille","ipa":"/mɛ pɛʁsɔn syʁ tɛʁ nɑ̃ vø puʁ fij/","zh":"世上却没有人愿认她作女儿。","en":"but no one on earth wants her for a daughter.","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-02-016","lineIndex":16,"speaker":"Fantine","original":"Comme bâtarde née dans un cachot de la Bastille","ipa":"/kɔm bataʁd ne dɑ̃z œ̃ kaʃo də la bastij/","zh":"仿佛生在巴士底地牢里的私生女。","en":"like a bastard daughter born in a Bastille dungeon.","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-02-017","lineIndex":17,"speaker":"Fantine","original":"La misère enfante la détresse","ipa":"/la mizɛʁ ɑ̃fɑ̃t la detʁɛs/","zh":"苦难孕育困厄","en":"Misery gives birth to distress","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-02-018","lineIndex":18,"speaker":"Fantine","original":"Bien des vices et toutes les faiblesses","ipa":"/bjɛ̃ de visz e tut le fɛblɛs/","zh":"连同许多恶习和所有软弱。","en":"to many vices and every weakness.","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-02-019","lineIndex":19,"speaker":"Fantine","original":"La misère lâche la bête en l'homme","ipa":"/la mizɛʁ laʃ la bɛt ɑ̃ lɔm/","zh":"苦难会放出人心中的野兽","en":"Misery unleashes the beast in man","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-02-020","lineIndex":20,"speaker":"Fantine","original":"Et la mésange alors en chienne errante se transforme","ipa":"/e la mezɑ̃ʒ alɔʁ ɑ̃ ʃjɛn ɛʁɑ̃t sə tʁɑ̃sfɔʁm/","zh":"山雀也会变成流浪的母狗。","en":"and a titmouse turns into a stray bitch.","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-02-021","lineIndex":21,"speaker":"Fantine","original":"Il faut qu'on se sente survivre","ipa":"/il fo kɔ̃ sə sɑ̃t syʁvivʁ/","zh":"人得在自己带到世上的孩子身上","en":"We must feel that we survive","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-02-022","lineIndex":22,"speaker":"Fantine","original":"Dans un enfant qu'on a fait vivre","ipa":"/dɑ̃z œ̃n ɑ̃fɑ̃ kɔ̃n a fɛ vivʁ/","zh":"感到自己还在活着；","en":"in a child we brought to life","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-02-023","lineIndex":23,"speaker":"Fantine","original":"Et qu'en sa source d'innocence","ipa":"/e kɑ̃ sa suʁs dinosɑ̃s/","zh":"还要把绝望","en":"and in that child's wellspring of innocence","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-02-024","lineIndex":24,"speaker":"Fantine","original":"On noie notre désespérance","ipa":"/ɔ̃ nwa notʁ dezɛspeʁɑ̃s/","zh":"淹没在她天真的泉源里","en":"drown our despair","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-02-025","lineIndex":25,"speaker":"Fantine","original":"Pour ne pas mettre fin","ipa":"/puʁ nə pa mɛtʁ fɛ̃/","zh":"才不至于结束","en":"so as not to put an end","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-02-026","lineIndex":26,"speaker":"Fantine","original":"À cette vie sans lendemain","ipa":"/a sɛt vi sɑ̃ lɑ̃dmɛ̃/","zh":"这没有明日的生活。","en":"to this life without tomorrow.","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-02-027","lineIndex":27,"speaker":"Fantine","original":"La misère n'est mère de personne","ipa":"/la mizɛʁ nɛ mɛʁ də pɛʁsɔn/","zh":"贫穷不是任何人的母亲","en":"Poverty is the mother of no one","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-02-028","lineIndex":28,"speaker":"Fantine","original":"La misère est pourtant soeur des hommes","ipa":"/la mizɛʁ ɛ puʁtɑ̃ sœʁ dez ɔm/","zh":"苦难却是人类的姐妹","en":"Yet misery is mankind's sister","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-02-029","lineIndex":29,"speaker":"Fantine","original":"Mais personne sur terre n'en veut pour fille","ipa":"/mɛ pɛʁsɔn syʁ tɛʁ nɑ̃ vø puʁ fij/","zh":"世上却没有人愿认她作女儿","en":"but no one on earth wants her for a daughter","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-02-030","lineIndex":30,"speaker":"Fantine","original":"Comme bâtarde née dans un cachot de la Bastille","ipa":"/kɔm bataʁd ne dɑ̃z œ̃ kaʃo də la bastij/","zh":"仿佛生在巴士底地牢里的私生女。","en":"like a bastard daughter born in a Bastille dungeon.","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-02-031","lineIndex":31,"speaker":"Fantine","original":"La misère enfante la détresse","ipa":"/la mizɛʁ ɑ̃fɑ̃t la detʁɛs/","zh":"苦难孕育困厄","en":"Misery gives birth to distress","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-02-032","lineIndex":32,"speaker":"Fantine","original":"Bien des vices et toutes les faiblesses","ipa":"/bjɛ̃ de visz e tut le fɛblɛs/","zh":"连同许多恶习和所有软弱。","en":"to many vices and every weakness.","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-02-033","lineIndex":33,"speaker":"Fantine","original":"La misère lâche la bête en l'homme","ipa":"/la mizɛʁ laʃ la bɛt ɑ̃ lɔm/","zh":"苦难会放出人心中的野兽","en":"Misery unleashes the beast in man","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-02-034","lineIndex":34,"speaker":"Fantine","original":"Et la mésange alors en chienne errante se transforme","ipa":"/e la mezɑ̃ʒ alɔʁ ɑ̃ ʃjɛn ɛʁɑ̃t sə tʁɑ̃sfɔʁm/","zh":"山雀也会变成流浪的母狗。","en":"and a titmouse turns into a stray bitch.","note":"","sourceLineIndex":34}],"sourceOrder":2,"displayOrder":2},{"order":3,"id":"03-les-beaux-cheveux-que-voila","title":"Les beaux Cheveux que voilà","titleZh":"美丽的头发","lines":[{"id":"les-miserables-1980-03-001","lineIndex":1,"speaker":"L'acheteuse de cheveux","original":"Les beaux cheveux, les longs cheveux que voilà","ipa":"/le bo ʃəvø le lɔ̃ ʃəvø kə vwala/","zh":"头发好漂亮，头发这么长","en":"Beautiful hair, such long hair","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-03-002","lineIndex":2,"speaker":"L'acheteuse de cheveux","original":"Les beaux cheveux, les beaux cheveux que tu as","ipa":"/le bo ʃəvø le bo ʃəvø kə ty a/","zh":"你这头美丽的长发，真叫人羡慕。","en":"The beautiful hair, the beautiful hair that you have","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-03-003","lineIndex":3,"speaker":"L'acheteuse de cheveux","original":"Tu me les vends?","ipa":"/ty mə le vɑ̃/","zh":"你把它们卖给我吗？","en":"Are you selling them to me?","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-03-004","lineIndex":4,"speaker":"Fantine","original":"Laissez-moi, allez-vous-en!","ipa":"/lɛsemwa alevuzɑ̃/","zh":"离开我，走开！","en":"Leave me, go away!","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-03-005","lineIndex":5,"speaker":"L'acheteuse de cheveux","original":"Réfléchis bien, je peux t'en donner dix francs","ipa":"/ʁefleʃi bjɛ̃ ʒə pø tɑ̃ dɔne di fʁɑ̃/","zh":"仔细想想，我可以给你十法郎","en":"Think carefully, I can give you ten francs","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-03-006","lineIndex":6,"speaker":"L'acheteuse de cheveux","original":"Réfléchis bien!","ipa":"/ʁefleʃi bjɛ̃/","zh":"仔细想想！","en":"Think carefully!","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-03-007","lineIndex":7,"speaker":"Fantine","original":"Ma pauvre tête!","ipa":"/ma povʁ tɛt/","zh":"我可怜的头！","en":"My poor head!","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-03-008","lineIndex":8,"speaker":"L'acheteuse de cheveux","original":"Réfléchis bien!","ipa":"/ʁefleʃi bjɛ̃/","zh":"仔细想想！","en":"Think carefully!","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-03-009","lineIndex":9,"speaker":"Fantine","original":"C'est pour Cosette","ipa":"/sɛ puʁ kozɛt/","zh":"这是为了珂赛特","en":"It's for Cosette","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-03-010","lineIndex":10,"speaker":"Fantine","original":"Dix francs déjà que j'enverrai pour la soigner","ipa":"/di fʁɑ̃ deʒa kə ʒɑ̃vɛʁe puʁ la swanje/","zh":"这十法郎，我立刻寄去给她治病。","en":"Ten francs already that I will send to take care of her","note":"","sourceLineIndex":10}],"sourceOrder":3,"displayOrder":3},{"order":4,"id":"04-j-avais-reve-d-une-autre-vie","title":"J'avais rêvé d'une autre vie","titleZh":"我梦想着另一种生活","lines":[{"id":"les-miserables-1980-04-001","lineIndex":1,"speaker":"Fantine","original":"J'avais rêvé d'une autre vie","ipa":"/ʒavɛ ʁɛve dyn otʁ vi/","zh":"我梦想着另一种生活","en":"I dreamed of another life","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-04-002","lineIndex":2,"speaker":"Fantine","original":"Mais la vie a tué mes rêves","ipa":"/mɛ la vi a tye me ʁɛv/","zh":"但生活扼杀了我的梦想","en":"But life killed my dreams","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-04-003","lineIndex":3,"speaker":"Fantine","original":"Comme on étouffe les derniers cris","ipa":"/kɔm ɔ̃n etuf le dɛʁnje kʁi/","zh":"像人捂灭","en":"As one stifles the last cries","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-04-004","lineIndex":4,"speaker":"Fantine","original":"D'un animal que l'on achève","ipa":"/dœ̃n animal kə lɔ̃n aʃɛv/","zh":"一头濒死动物最后的哀叫。","en":"of an animal being put to death.","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-04-005","lineIndex":5,"speaker":"Fantine","original":"J'avais rêvé d'un cœur si grand","ipa":"/ʒavɛ ʁɛve dœ̃ kœʁ si ɡʁɑ̃/","zh":"我曾梦想有一颗足够宽广的心","en":"I dreamed of a heart so great","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-04-006","lineIndex":6,"speaker":"Fantine","original":"Que le mien puisse y trouver place","ipa":"/kə lə mjɛ̃ pɥis i tʁuve plas/","zh":"能容下我的心。","en":"that mine could find a place within it.","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-04-007","lineIndex":7,"speaker":"Fantine","original":"Mais mon premier prince charmant","ipa":"/mɛ mɔ̃ pʁəmje pʁɛ̃s ʃaʁmɑ̃/","zh":"但我的第一个白马王子","en":"But my first prince charming","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-04-008","lineIndex":8,"speaker":"Fantine","original":"Fut l'assassin de mon enfance","ipa":"/fy lasasɛ̃ də mɔ̃n ɑ̃fɑ̃s/","zh":"是杀害我童年的凶手","en":"Was the murderer of my childhood","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-04-009","lineIndex":9,"speaker":"Fantine","original":"J'ai payé de toutes mes larmes","ipa":"/ʒe pɛje də tut me laʁm/","zh":"我用我所有的泪水付出了代价","en":"I paid with all my tears","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-04-010","lineIndex":10,"speaker":"Fantine","original":"La rançon d'un petit bonheur","ipa":"/la ʁɑ̃sɔ̃ dœ̃ pəti bɔnœʁ/","zh":"一点点幸福的代价","en":"The ransom of a little happiness","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-04-011","lineIndex":11,"speaker":"Fantine","original":"À une société qui désarme","ipa":"/a yn sosjete ki dezaʁm/","zh":"我把代价付给了这样一个社会：它缴了","en":"To a society that disarms","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-04-012","lineIndex":12,"speaker":"Fantine","original":"La victime, et pas le voleur","ipa":"/la viktim e pa lə volœʁ/","zh":"受害者的械，却不约束掠夺者。","en":"the victim, not the thief.","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-04-013","lineIndex":13,"speaker":"Fantine","original":"J'avais rêvé d'un seul amour","ipa":"/ʒavɛ ʁɛve dœ̃ sœl amuʁ/","zh":"我梦想有一份爱","en":"I had dreamed of only one love","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-04-014","lineIndex":14,"speaker":"Fantine","original":"Durant jusqu'à la fin du monde","ipa":"/dyʁɑ̃ ʒyska la fɛ̃ dy mɔ̃d/","zh":"持续到世界末日","en":"Lasting until the end of the world","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-04-015","lineIndex":15,"speaker":"Fantine","original":"Dont on ne fait jamais le tour","ipa":"/dɔ̃t ɔ̃ nə fɛ ʒamɛ lə tuʁ/","zh":"无边无际，永远走不到尽头","en":"whose full extent one never reaches","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-04-016","lineIndex":16,"speaker":"Fantine","original":"Aussi vrai que la terre est ronde","ipa":"/osi vʁɛ kə la tɛʁ ɛ ʁɔ̃d/","zh":"如同大地是圆的一样真实。","en":"As true as the earth is round","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-04-017","lineIndex":17,"speaker":"Fantine","original":"J'avais rêvé d'une autre vie","ipa":"/ʒavɛ ʁɛve dyn otʁ vi/","zh":"我梦想着另一种生活","en":"I dreamed of another life","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-04-018","lineIndex":18,"speaker":"Fantine","original":"Mais la vie a tué mes rêves","ipa":"/mɛ la vi a tye me ʁɛv/","zh":"但生活扼杀了我的梦想","en":"But life killed my dreams","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-04-019","lineIndex":19,"speaker":"Fantine","original":"À peine commencée, elle finit","ipa":"/a pɛn kɔmɑ̃se ɛl fini/","zh":"刚刚开始，就结束了","en":"Barely begun, it ends","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-04-020","lineIndex":20,"speaker":"Fantine","original":"Comme un court printemps qui s'achève","ipa":"/kɔm œ̃ kuʁ pʁɛ̃tɑ̃ ki saʃɛv/","zh":"就像短暂的春天结束了","en":"Like a short spring which ends","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-04-021","lineIndex":21,"speaker":"Fantine","original":"J'avais rêvé d'une autre vie","ipa":"/ʒavɛ ʁɛve dyn otʁ vi/","zh":"我梦想着另一种生活","en":"I dreamed of another life","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-04-022","lineIndex":22,"speaker":"Fantine","original":"Mais la vie a tué mes rêves","ipa":"/mɛ la vi a tye me ʁɛv/","zh":"但生活扼杀了我的梦想","en":"But life killed my dreams","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-04-023","lineIndex":23,"speaker":"Fantine","original":"À peine commencée, elle finit","ipa":"/a pɛn kɔmɑ̃se ɛl fini/","zh":"刚刚开始，就结束了","en":"Barely begun, it ends","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-04-024","lineIndex":24,"speaker":"Fantine","original":"Comme un court printemps qui s'achève","ipa":"/kɔm œ̃ kuʁ pʁɛ̃tɑ̃ ki saʃɛv/","zh":"就像短暂的春天结束了","en":"Like a short spring which ends","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-04-025","lineIndex":25,"speaker":"Fantine","original":"La nuit, la nuit, je sombre en mon corps","ipa":"/la nɥi la nɥi ʒə sɔ̃bʁ ɑ̃ mɔ̃ kɔʁ/","zh":"夜复一夜，我沉沦在自己的肉身里","en":"Night after night, I sink into my body","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-04-026","lineIndex":26,"speaker":"Fantine","original":"Et je m'abandonne à des sinistres corps à corps","ipa":"/e ʒə mabɑ̃dɔn a de sinistʁ kɔʁ a kɔʁ/","zh":"任由自己落入阴森的肉体交易。","en":"and abandon myself to grim encounters of body against body.","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-04-027","lineIndex":27,"speaker":"Fantine","original":"La nuit, la nuit, pour deux pièces d'or","ipa":"/la nɥi la nɥi puʁ dø pjɛs dɔʁ/","zh":"夜复一夜，只为两枚金币","en":"Night after night, for two pieces of gold","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-04-028","lineIndex":28,"speaker":"Fantine","original":"Quand ils font jaillir en moi leur pitoyable effort","ipa":"/kɑ̃t il fɔ̃ ʒajiʁ ɑ̃ mwa lœʁ pitwajabl efɔʁ/","zh":"当他们在我身上宣泄那点可怜的欲望","en":"when they spend their pitiful effort on me","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-04-029","lineIndex":29,"speaker":"Fantine","original":"Ils ne savent pas qu'ils font l'amour avec la mort!","ipa":"/il nə sav pa kil fɔ̃ lamuʁ avɛk la mɔʁ/","zh":"他们不知道，自己是在与死亡交媾！","en":"they do not know they are making love with death!","note":"","sourceLineIndex":29}],"sourceOrder":4,"displayOrder":4},{"order":5,"id":"05-dites-moi-ce-qu-il-se-passe","title":"Dites-moi ce qu'il se passe","titleZh":"告诉我发生了什么","lines":[{"id":"les-miserables-1980-05-001","lineIndex":1,"speaker":"Javert","original":"Dites-moi ce qu'il se passe","ipa":"/ditmwa sə kil sə pas/","zh":"告诉我发生了什么事","en":"Tell me what's going on","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-05-002","lineIndex":2,"speaker":"Javert","original":"Qui est mort, qui a tué","ipa":"/ki ɛ mɔʁ ki a tye/","zh":"谁死了，谁杀的？","en":"Who died, who killed?","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-05-003","lineIndex":3,"speaker":"Javert","original":"Où je passe le crime trépasse","ipa":"/u ʒə pas lə kʁim tʁepas/","zh":"我走到哪里，罪恶就在那里断气。","en":"Where I pass, crime dies.","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-05-004","lineIndex":4,"speaker":"Javert","original":"L'ordre est en sécurité","ipa":"/lɔʁdʁ ɛt ɑ̃ sekyʁite/","zh":"秩序安然无恙。","en":"Order is safe.","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-05-005","lineIndex":5,"speaker":"Javert","original":"Que chacun prenne bien garde","ipa":"/kə ʃakœ̃ pʁɛn bjɛ̃ ɡaʁd/","zh":"人人都给我小心点。","en":"Let everyone take care.","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-05-006","lineIndex":6,"speaker":"Javert","original":"J'arrive toujours à mes fins","ipa":"/ʒaʁiv tuʒuʁz a me fɛ̃/","zh":"我总能实现我的目标","en":"I always achieve my goals","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-05-007","lineIndex":7,"speaker":"Javert","original":"Je décore ceux qui mouchardent","ipa":"/ʒə dekɔʁ sø ki muʃaʁd/","zh":"我会嘉奖告密的人","en":"I decorate those who inform","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-05-008","lineIndex":8,"speaker":"Javert","original":"Par devoir de citoyen","ipa":"/paʁ dəvwaʁ də sitwajɛ̃/","zh":"因为他们尽了公民义务。","en":"for doing their civic duty.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-05-009","lineIndex":9,"speaker":"Un badaud","original":"Inspecteur, c'est cette fille","ipa":"/ɛ̃spɛktœʁ sɛ sɛt fij/","zh":"督察，就是那个女孩","en":"Inspector, it's that girl","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-05-010","lineIndex":10,"speaker":"Un badaud","original":"Qui a frappé le bourgeois","ipa":"/ki a fʁape lə buʁʒwa/","zh":"她打了那位先生","en":"who struck the gentleman","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-05-011","lineIndex":11,"speaker":"Un badaud","original":"Pour un compliment, ma foi","ipa":"/puʁ œ̃ kɔ̃plimɑ̃ ma fwa/","zh":"就为了一句恭维话，天哪。","en":"over a compliment, by my faith.","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-05-012","lineIndex":12,"speaker":"Javert","original":"Qu'on emmène cette roulure","ipa":"/kɔ̃n ɑ̃mɛn sɛt ʁulyʁ/","zh":"把这个“荡妇”带走","en":"Take this “whore” away","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-05-013","lineIndex":13,"speaker":"Javert","original":"Et qu'on la jette en prison","ipa":"/e kɔ̃ la ʒɛt ɑ̃ pʁizɔ̃/","zh":"并将她投入监狱","en":"And throw her in prison","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-05-014","lineIndex":14,"speaker":"Javert","original":"Qu'elle s'y fasse une droiture","ipa":"/kɛl si fas yn dʁwatyʁ/","zh":"让她在里面学会规矩","en":"Let her become righteous","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-05-015","lineIndex":15,"speaker":"Javert","original":"Et retrouve sa raison!","ipa":"/e ʁətʁuv sa ʁɛzɔ̃/","zh":"并且恢复理智！","en":"And find her reason!","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-05-016","lineIndex":16,"speaker":"Fantine","original":"Inspecteur, faites-moi grâce","ipa":"/ɛ̃spɛktœʁ fɛtmwa ɡʁas/","zh":"督察请原谅我","en":"Inspector, give me mercy","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-05-017","lineIndex":17,"speaker":"Fantine","original":"Je regrette ce que j'ai fait","ipa":"/ʒə ʁəɡʁɛt sə kə ʒe fɛ/","zh":"我对我所做的事感到后悔","en":"I regret what I did","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-05-018","lineIndex":18,"speaker":"Fantine","original":"Ma petite fille est malade","ipa":"/ma pətit fij ɛ malad/","zh":"我的小女儿病了","en":"My little daughter is sick","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-05-019","lineIndex":19,"speaker":"Fantine","original":"Laissez-moi la liberté","ipa":"/lɛsemwa la libɛʁte/","zh":"给我自由","en":"Leave me free","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-05-020","lineIndex":20,"speaker":"Tous","original":"Qu'on emmène cette roulure","ipa":"/kɔ̃n ɑ̃mɛn sɛt ʁulyʁ/","zh":"把这个“荡妇”带走","en":"Take this “whore” away","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-05-021","lineIndex":21,"speaker":"Tous","original":"Et qu'on la jette en prison","ipa":"/e kɔ̃ la ʒɛt ɑ̃ pʁizɔ̃/","zh":"并将她投入监狱","en":"And throw her in prison","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-05-022","lineIndex":22,"speaker":"Tous","original":"Qu'elle s'y fasse une droiture","ipa":"/kɛl si fas yn dʁwatyʁ/","zh":"让她在里面学会规矩","en":"Let her become righteous","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-05-023","lineIndex":23,"speaker":"Tous","original":"Et retrouve sa raison!","ipa":"/e ʁətʁuv sa ʁɛzɔ̃/","zh":"并且恢复理智！","en":"And find her reason!","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-05-024","lineIndex":24,"speaker":"Fantine","original":"Inspecteur, je suis malade","ipa":"/ɛ̃spɛktœʁ ʒə sɥi malad/","zh":"督察，我病了","en":"Inspector, I am sick","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-05-025","lineIndex":25,"speaker":"Fantine","original":"Parfois je crache le sang","ipa":"/paʁfwa ʒə kʁaʃ lə sɑ̃/","zh":"有时我会咳血。","en":"Sometimes I cough up blood.","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-05-026","lineIndex":26,"speaker":"Javert","original":"Si tu crois que je vais croire","ipa":"/si ty kʁwa kə ʒə vɛ kʁwaʁ/","zh":"你若以为我会相信","en":"If you think I'll believe","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-05-027","lineIndex":27,"speaker":"Javert","original":"Tous ces pauvres arguments","ipa":"/tu se povʁz aʁɡymɑ̃/","zh":"所有这些糟糕的论点","en":"All these poor arguments","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-05-028","lineIndex":28,"speaker":"Javert","original":"Quand on veut rester honnête","ipa":"/kɑ̃t ɔ̃ vø ʁɛste ɔnɛt/","zh":"当我们想要保持诚实时","en":"When you want to stay honest","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-05-029","lineIndex":29,"speaker":"Javert","original":"Il y a toujours un moyen","ipa":"/il i a tuʒuʁz œ̃ mwajɛ̃/","zh":"总有办法的","en":"There's always a way","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-05-030","lineIndex":30,"speaker":"Javert","original":"On fait fonctionner sa tête","ipa":"/ɔ̃ fɛ fɔ̃ksjɔne sa tɛt/","zh":"就该动动脑子","en":"you use your head","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-05-031","lineIndex":31,"speaker":"Javert","original":"Ou on travaille de ses mains","ipa":"/u ɔ̃ tʁavaj də se mɛ̃/","zh":"或者我们用手工作","en":"Or you work with your hands","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-05-032","lineIndex":32,"speaker":"Javert","original":"C'est moins sûr, c'est plus dur","ipa":"/sɛ mwɛ̃ syʁ sɛ ply dyʁ/","zh":"走正道不那么稳当，也更辛苦","en":"It's less sure, it's harder","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-05-033","lineIndex":33,"speaker":"Javert","original":"Quand on va au droit chemin","ipa":"/kɑ̃t ɔ̃ va o dʁwa ʃəmɛ̃/","zh":"可这才是正直之人的路。","en":"When we go the straight and narrow","note":"","sourceLineIndex":33}],"sourceOrder":5,"displayOrder":5},{"order":6,"id":"06-fantine-et-monsieur-madeleine","title":"Fantine et Monsieur Madeleine","titleZh":"芳汀和玛德琳先生","lines":[{"id":"les-miserables-1980-06-001","lineIndex":1,"speaker":"Valjean","original":"Juste un instant, s'il vous plaît","ipa":"/ʒyst œ̃n ɛ̃stɑ̃ sil vu plɛ/","zh":"请稍等一下","en":"Just a moment, please","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-06-002","lineIndex":2,"speaker":"Valjean","original":"Qu'on mette cette femme en liberté","ipa":"/kɔ̃ mɛt sɛt fam ɑ̃ libɛʁte/","zh":"让我们释放这个女人","en":"Let us set this woman free","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-06-003","lineIndex":3,"speaker":"Javert","original":"Mais, Monsieur le Maire!","ipa":"/mɛ məsjø lə mɛʁ/","zh":"但是，市长先生！","en":"But, Mr. Mayor!","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-06-004","lineIndex":4,"speaker":"Valjean","original":"Je crois qu'elle n'a rien fait de mal","ipa":"/ʒə kʁwa kɛl na ʁjɛ̃ fɛ də mal/","zh":"我不认为她做错了什么","en":"I don't think she did anything wrong","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-06-005","lineIndex":5,"speaker":"Valjean","original":"Transportez-la à l'hôpital","ipa":"/tʁɑ̃spɔʁtela a lopital/","zh":"带她去医院","en":"Take her to the hospital","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-06-006","lineIndex":6,"speaker":"Javert","original":"Mais, Monsieur le Maire!","ipa":"/mɛ məsjø lə mɛʁ/","zh":"但是，市长先生！","en":"But, Mr. Mayor!","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-06-007","lineIndex":7,"speaker":"Fantine","original":"Est-ce possible?","ipa":"/ɛs pɔsibl/","zh":"这可能吗？","en":"Is this possible?","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-06-008","lineIndex":8,"speaker":"Monsieur Madeleine","original":"Allez","ipa":"/ale/","zh":"来吧","en":"Come on","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-06-009","lineIndex":9,"speaker":"Fantine","original":"Mon Dieu!","ipa":"/mɔ̃ djø/","zh":"天哪！","en":"My God!","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-06-010","lineIndex":10,"speaker":"Valjean","original":"Dépêchez-vous un peu!","ipa":"/depɛʃevuz œ̃ pø/","zh":"快点！","en":"Hurry up!","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-06-011","lineIndex":11,"speaker":"Valjean","original":"J'enverrai chercher votre fillette","ipa":"/ʒɑ̃vɛʁe ʃɛʁʃe votʁ fijɛt/","zh":"我会派人去接你的小女儿","en":"I will send for your little girl","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-06-012","lineIndex":12,"speaker":"Valjean","original":"Déchargée du fardeau de vos dettes","ipa":"/deʃaʁʒe dy faʁdo də vo dɛt/","zh":"也会替你卸下债务的重担。","en":"Freed from the burden of your debts","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-06-013","lineIndex":13,"speaker":"Valjean","original":"Vous pourrez être à nouveau heureuse","ipa":"/vu puʁez ɛtʁ a nuvo øʁøz/","zh":"你就能重新拥有幸福","en":"You will be able to be happy again","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-06-014","lineIndex":14,"speaker":"Valjean","original":"Vous qui n'avez pour Dieu pas cessé","ipa":"/vu ki nave puʁ djø pa sɛse/","zh":"你一直虔诚地","en":"You who have not stopped for God","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-06-015","lineIndex":15,"speaker":"Valjean","original":"D'être vertueuse","ipa":"/dɛtʁ vɛʁtyøz/","zh":"守着自己的品德。","en":"To be virtuous","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-06-016","lineIndex":16,"speaker":"Fantine (Contre-chant)","original":"Ah, c'est donc toi, Monsieur le Maire","ipa":"/a sɛ dɔ̃k twa məsjø lə mɛʁ/","zh":"啊，原来是你，市长先生","en":"Ah, so it is you, Mr. Mayor","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-06-017","lineIndex":17,"speaker":"Fantine (Contre-chant)","original":"J'ai mal entendu","ipa":"/ʒe mal ɑ̃tɑ̃dy/","zh":"我听错了","en":"I misheard","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-06-018","lineIndex":18,"speaker":"Fantine (Contre-chant)","original":"Il m'a chassée de l'atelier","ipa":"/il ma ʃase də latəlje/","zh":"他把我踢出了车间","en":"He chased me out of the workshop","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-06-019","lineIndex":19,"speaker":"Fantine (Contre-chant)","original":"Il m'a chassée","ipa":"/il ma ʃase/","zh":"他赶走了我","en":"He chased me","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-06-020","lineIndex":20,"speaker":"Fantine (Contre-chant)","original":"Pour des ragots de bénitier","ipa":"/puʁ de ʁaɡo də benitje/","zh":"只因为那些教堂门口的闲话。","en":"For gossip","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-06-021","lineIndex":21,"speaker":"Fantine (Contre-chant)","original":"Gredin de maire","ipa":"/ɡʁədɛ̃ də mɛʁ/","zh":"这个恶棍市长","en":"Scoundrel mayor","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-06-022","lineIndex":22,"speaker":"Fantine (Contre-chant)","original":"L'auteur de mes misères","ipa":"/lotœʁ də me mizɛʁ/","zh":"正是我苦难的始作俑者。","en":"The author of my miseries","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-06-023","lineIndex":23,"speaker":"Fantine","original":"Êtes-vous un ange ou un démon?","ipa":"/ɛtvuz œ̃n ɑ̃ʒ u œ̃ demɔ̃/","zh":"你是天使还是恶魔？","en":"Are you an angel or a demon?","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-06-024","lineIndex":24,"speaker":"Fantine","original":"J'aime mieux mourir qu'avoir encore de faux espoirs","ipa":"/ʒɛm mjø muʁiʁ kavwaʁ ɑ̃kɔʁ də foz ɛspwaʁ/","zh":"我宁愿死，也不愿抱有虚假的希望","en":"I would rather die than still have false hopes","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-06-025","lineIndex":25,"speaker":"Fantine","original":"S'il le faut, mieux vaut encore déchoir","ipa":"/sil lə fo mjø vot ɑ̃kɔʁ deʃwaʁ/","zh":"真要如此，宁可再一次坠落。","en":"If necessary, it is better to fail again","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-06-026","lineIndex":26,"speaker":"Fantine","original":"A ce point je n'sens plus rien","ipa":"/a sə pwɛ̃ ʒə nsɑ̃ ply ʁjɛ̃/","zh":"此时我已经没有任何感觉","en":"At this point I no longer feel anything","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-06-027","lineIndex":27,"speaker":"Valjean","original":"Comment ai-je pu?","ipa":"/kɔmɑ̃ ɛʒ py/","zh":"我怎么能？","en":"How could I?","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-06-028","lineIndex":28,"speaker":"Valjean","original":"Mon Dieu si j'avais su","ipa":"/mɔ̃ djø si ʒavɛ sy/","zh":"天哪，如果我早知道","en":"My God if I had known","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-06-029","lineIndex":29,"speaker":"Valjean","original":"Tout le mal que j'ai fait!","ipa":"/tu lə mal kə ʒe fɛ/","zh":"我竟造成了这么多伤害！","en":"All the evil I have done!","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-06-030","lineIndex":30,"speaker":"Fantine","original":"La misère enfante la détresse","ipa":"/la mizɛʁ ɑ̃fɑ̃t la detʁɛs/","zh":"苦难孕育困厄","en":"Misery gives birth to distress","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-06-031","lineIndex":31,"speaker":"Fantine","original":"Bien des vices et toutes les faiblesses","ipa":"/bjɛ̃ de visz e tut le fɛblɛs/","zh":"连同许多恶习和所有软弱","en":"to many vices and every weakness","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-06-032","lineIndex":32,"speaker":"Fantine","original":"La misère lâche la bête en l'homme","ipa":"/la mizɛʁ laʃ la bɛt ɑ̃ lɔm/","zh":"苦难会放出人心中的野兽","en":"Misery unleashes the beast in man","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-06-033","lineIndex":33,"speaker":"Fantine","original":"Et la mésange alors en chienne errante se transforme","ipa":"/e la mezɑ̃ʒ alɔʁ ɑ̃ ʃjɛn ɛʁɑ̃t sə tʁɑ̃sfɔʁm/","zh":"山雀也会变成流浪的母狗。","en":"and a titmouse turns into a stray bitch.","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-06-034","lineIndex":34,"speaker":"Valjean","original":"Qu'il soit fait ainsi que je l'ordonne!","ipa":"/kil swa fɛt ɛ̃si kə ʒə lɔʁdɔn/","zh":"就按照我的命令去做吧！","en":"Let it be done as I command!","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-06-035","lineIndex":35,"speaker":"Javert","original":"Mais, Monsieur le Maire!","ipa":"/mɛ məsjø lə mɛʁ/","zh":"但是，市长先生！","en":"But, Mr. Mayor!","note":"","sourceLineIndex":35},{"id":"les-miserables-1980-06-036","lineIndex":36,"speaker":"Valjean","original":"Je ne veux voir personne","ipa":"/ʒə nə vø vwaʁ pɛʁsɔn/","zh":"我不想见任何人","en":"I don't want to see anyone","note":"","sourceLineIndex":36}],"sourceOrder":6,"displayOrder":6},{"order":7,"id":"07-mon-prince-est-en-chemin","title":"Mon prince est en chemin","titleZh":"我的王子正在路上","lines":[{"id":"les-miserables-1980-07-001","lineIndex":1,"speaker":"Cosette","original":"Ils vont venir bientôt, et je n'ai pas fini","ipa":"/il vɔ̃ vəniʁ bjɛ̃to e ʒə ne pa fini/","zh":"他们很快就会来，我却还没干完。","en":"They'll be here soon, and I haven't finished.","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-07-002","lineIndex":2,"speaker":"Cosette","original":"De laver, de brosser, de cirer le parquet","ipa":"/də lave də bʁɔse də siʁe lə paʁkɛ/","zh":"清洗、刷洗、打蜡镶木地板","en":"Washing, brushing, waxing the floor","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-07-003","lineIndex":3,"speaker":"Cosette","original":"Et puis sans un répit j'irai servir aussi","ipa":"/e pɥi sɑ̃z œ̃ ʁepi ʒiʁe sɛʁviʁ osi/","zh":"然后我还得不停歇地去伺候人。","en":"Then, without a break, I will go and serve as well.","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-07-004","lineIndex":4,"speaker":"Cosette","original":"Pourtant, elle me battra quand même","ipa":"/puʁtɑ̃ ɛl mə batʁa kɑ̃ mɛm/","zh":"可她还是会打我。","en":"Yet she will beat me anyway.","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-07-005","lineIndex":5,"speaker":"Cosette","original":"Je sais mais j'ai pris l'habitude","ipa":"/ʒə sɛ mɛ ʒe pʁi labityd/","zh":"我知道，但我已经习惯了","en":"I know but I got used to it","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-07-006","lineIndex":6,"speaker":"Cosette","original":"Et ça me fait moins mal que ma solitude","ipa":"/e sa mə fɛ mwɛ̃ mal kə ma solityd/","zh":"它对我的伤害远小于我的孤独","en":"And it hurts me less than my loneliness","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-07-007","lineIndex":7,"speaker":"Cosette","original":"Mon prince est en chemin déjà","ipa":"/mɔ̃ pʁɛ̃s ɛt ɑ̃ ʃəmɛ̃ deʒa/","zh":"我的王子已经上路了","en":"My prince is already on his way","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-07-008","lineIndex":8,"speaker":"Cosette","original":"Je ne sais pas comme il sera","ipa":"/ʒə nə sɛ pa kɔm il səʁa/","zh":"我不知道他会是什么模样","en":"I don't know what he will be like","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-07-009","lineIndex":9,"speaker":"Cosette","original":"Mais je sais qu'il viendra demain","ipa":"/mɛ ʒə sɛ kil vjɛ̃dʁa dəmɛ̃/","zh":"但我知道他明天会来","en":"But I know he will come tomorrow","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-07-010","lineIndex":10,"speaker":"Cosette","original":"Mon prince est déjà en chemin","ipa":"/mɔ̃ pʁɛ̃s ɛ deʒa ɑ̃ ʃəmɛ̃/","zh":"我的王子已经上路了","en":"My prince is already on his way","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-07-011","lineIndex":11,"speaker":"Cosette","original":"D'un coup de mon balai magique","ipa":"/dœ̃ ku də mɔ̃ balɛ maʒik/","zh":"用我的魔法扫帚一扫","en":"With a wave of my magic broom","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-07-012","lineIndex":12,"speaker":"Cosette","original":"Il apparaît si je le veux","ipa":"/il apaʁɛ si ʒə lə vø/","zh":"只要我愿意，他便会出现。","en":"He appears if I want him","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-07-013","lineIndex":13,"speaker":"Cosette","original":"Et je voyage dans ses yeux","ipa":"/e ʒə vwajaʒ dɑ̃ sez jø/","zh":"我在他的眼中旅行","en":"And I travel in his eyes","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-07-014","lineIndex":14,"speaker":"Cosette","original":"Tous les enfants ont une enfance","ipa":"/tu lez ɑ̃fɑ̃z ɔ̃t yn ɑ̃fɑ̃s/","zh":"所有的孩子都有童年","en":"All children have a childhood","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-07-015","lineIndex":15,"speaker":"Cosette","original":"Une famille et des jouets","ipa":"/yn famij e de ʒwɛ/","zh":"家庭和玩具","en":"A family and toys","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-07-016","lineIndex":16,"speaker":"Cosette","original":"C'est tout ou rien, chance ou bien malchance","ipa":"/sɛ tu u ʁjɛ̃ ʃɑ̃s u bjɛ̃ malʃɑ̃s/","zh":"要么全有，要么全无，幸运还是不幸","en":"It's all or nothing, luck or bad luck","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-07-017","lineIndex":17,"speaker":"Cosette","original":"Je n'ai ni père, ni mère, ni poupée","ipa":"/ʒə ne ni pɛʁ ni mɛʁ ni pupe/","zh":"我没有爸爸，没有妈妈，没有娃娃","en":"I have no father, no mother, no doll","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-07-018","lineIndex":18,"speaker":"Cosette","original":"Mon prince est en chemin déjà","ipa":"/mɔ̃ pʁɛ̃s ɛt ɑ̃ ʃəmɛ̃ deʒa/","zh":"我的王子已经上路了","en":"My prince is already on his way","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-07-019","lineIndex":19,"speaker":"Cosette","original":"Je ne sais pas comme il sera","ipa":"/ʒə nə sɛ pa kɔm il səʁa/","zh":"我不知道他会是什么模样","en":"I don't know what he will be like","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-07-020","lineIndex":20,"speaker":"Cosette","original":"Mais je sais qu'il viendra demain","ipa":"/mɛ ʒə sɛ kil vjɛ̃dʁa dəmɛ̃/","zh":"但我知道他明天会来","en":"But I know he will come tomorrow","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-07-021","lineIndex":21,"speaker":"Cosette","original":"Mon prince est déjà en chemin","ipa":"/mɔ̃ pʁɛ̃s ɛ deʒa ɑ̃ ʃəmɛ̃/","zh":"我的王子已经上路了","en":"My prince is already on his way","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-07-022","lineIndex":22,"speaker":"Cosette","original":"La la la la...","ipa":"/la la la la/","zh":"啦啦啦啦...","en":"La la la la...","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-07-023","lineIndex":23,"speaker":"Cosette","original":"C'est tout ou rien, chance ou bien malchance","ipa":"/sɛ tu u ʁjɛ̃ ʃɑ̃s u bjɛ̃ malʃɑ̃s/","zh":"要么全有，要么全无，幸运还是不幸","en":"It's all or nothing, luck or bad luck","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-07-024","lineIndex":24,"speaker":"Cosette","original":"Je n'ai ni père, ni mère, ni poupée","ipa":"/ʒə ne ni pɛʁ ni mɛʁ ni pupe/","zh":"我没有爸爸，没有妈妈，没有娃娃","en":"I have no father, no mother, no doll","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-07-025","lineIndex":25,"speaker":"Cosette","original":"Mon prince est déjà en chemin","ipa":"/mɔ̃ pʁɛ̃s ɛ deʒa ɑ̃ ʃəmɛ̃/","zh":"我的王子已经上路了","en":"My prince is already on his way","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-07-026","lineIndex":26,"speaker":"Cosette","original":"Ils vont venir bientôt, et je n'ai pas fini","ipa":"/il vɔ̃ vəniʁ bjɛ̃to e ʒə ne pa fini/","zh":"他们很快就会来，可我还没干完。","en":"They will come soon, and I haven't finished","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-07-027","lineIndex":27,"speaker":"Cosette","original":"De laver, de brosser, de cirer le parquet","ipa":"/də lave də bʁɔse də siʁe lə paʁkɛ/","zh":"清洗、刷洗、打蜡镶木地板","en":"Washing, brushing, waxing the floor","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-07-028","lineIndex":28,"speaker":"Cosette","original":"Mon Dieu, v'là madame Thénardier!","ipa":"/mɔ̃ djø vla madam tenaʁdje/","zh":"天啊，泰纳第夫人来了！","en":"My God, there's Madame Thénardier!","note":"","sourceLineIndex":28}],"sourceOrder":7,"displayOrder":7},{"order":8,"id":"08-mam-zelle-crapaud","title":"Mam'zelle Crapaud","titleZh":"玛泽尔·克拉波","lines":[{"id":"les-miserables-1980-08-001","lineIndex":1,"speaker":"Madame Thénardier","original":"Mam'zelle Crapaud, range ton balai et ton seau","ipa":"/mamzɛl kʁapo ʁɑ̃ʒ tɔ̃ balɛ e tɔ̃ so/","zh":"小蛤蟆，收起你的扫帚和水桶。","en":"Mam'zelle Crapaud, put away your broom and your bucket","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-08-002","lineIndex":2,"speaker":"Madame Thénardier","original":"Il est trop tard pour faire semblant de faire le ménage","ipa":"/il ɛ tʁo taʁ puʁ fɛʁ sɑ̃blɑ̃ də fɛʁ lə menaʒ/","zh":"假装做家务已经太晚了","en":"It's too late to pretend to be cleaning","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-08-003","lineIndex":3,"speaker":"Madame Thénardier","original":"Ce soir, je te conseille d'être très très gentille","ipa":"/sə swaʁ ʒə tə kɔ̃sɛj dɛtʁ tʁɛ tʁɛ ʒɑ̃tij/","zh":"今晚，我建议你要非常非常友善","en":"This evening, I advise you to be very, very nice","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-08-004","lineIndex":4,"speaker":"Madame Thénardier","original":"Et souriante avec les clients","ipa":"/e suʁjɑ̃t avɛk le kliɑ̃/","zh":"对客人也要笑脸相迎。","en":"And smile with the customers","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-08-005","lineIndex":5,"speaker":"Madame Thénardier","original":"Sinon gare à la trique et au lit sans manger","ipa":"/sinɔ̃ ɡaʁ a la tʁik e o li sɑ̃ mɑ̃ʒe/","zh":"不然小心挨棍子，再饿着肚子上床。","en":"Or beware the stick, and bed without supper.","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-08-006","lineIndex":6,"speaker":"Madame Thénardier","original":"Pour t'apprendre à rêver","ipa":"/puʁ tapʁɑ̃dʁ a ʁɛve/","zh":"好叫你知道什么叫做白日做梦。","en":"To teach you to dream","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-08-007","lineIndex":7,"speaker":"Madame Thénardier","original":"Chien faute de nom, j'ai trouvé à t'occuper","ipa":"/ʃjɛ̃ fot də nɔ̃ ʒe tʁuve a tɔkype/","zh":"叫你“狗”都嫌没个名字；我给你找了活干。","en":"Dog, for lack of a name—I found something to keep you busy.","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-08-008","lineIndex":8,"speaker":"Madame Thénardier","original":"Cours me remplir ce seau dans la forêt","ipa":"/kuʁ mə ʁɑ̃pliʁ sə so dɑ̃ la foʁɛ/","zh":"跑到森林里给我装满这个桶","en":"Run and fill this bucket for me in the forest","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-08-009","lineIndex":9,"speaker":"Madame Thénardier","original":"Venez, donc, près de moi, mes jolies, mes poulettes","ipa":"/vəne dɔ̃k pʁɛ də mwa me ʒoli me pulɛt/","zh":"那么，来靠近我吧，我的漂亮宝贝们，我的小妞们","en":"Come, then, near me, my pretty ones, my chickens","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-08-010","lineIndex":10,"speaker":"Madame Thénardier","original":"Éponine, Azelma, mes petites peluches","ipa":"/eponin azɛlma me pətit pəlyʃ/","zh":"艾潘妮、阿泽玛，我的小宝贝们。","en":"Éponine, Azelma, my little darlings.","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-08-011","lineIndex":11,"speaker":"Madame Thénardier","original":"Que je voie comme vous vont vos nouvelles fanfreluches","ipa":"/kə ʒə vwa kɔm vu vɔ̃ vo nuvɛl fɑ̃fʁəlyʃ/","zh":"让我瞧瞧，你们的新花边穿着多合身。","en":"Let me see how your new frills look on you","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-08-012","lineIndex":12,"speaker":"Madame Thénardier","original":"Éponine, tu es belle dans cette robe en dentelle","ipa":"/eponin ty ɛ bɛl dɑ̃ sɛt ʁɔb ɑ̃ dɑ̃tɛl/","zh":"艾潘妮，你穿这件蕾丝连衣裙真漂亮。","en":"Éponine, you look beautiful in this lace dress","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-08-013","lineIndex":13,"speaker":"Madame Thénardier","original":"Azelma, mon amour as-tu fait ta lettre au père Noël?","ipa":"/azɛlma mɔ̃n amuʁ aty fɛ ta lɛtʁ o pɛʁ nɔɛl/","zh":"阿泽玛，亲爱的，你给圣诞老人写信了吗？","en":"Azelma, my love, have you written your letter to Santa Claus?","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-08-014","lineIndex":14,"speaker":"Madame Thénardier","original":"Cette souillon voudrait bien toucher à vos poupées","ipa":"/sɛt sujɔ̃ vudʁɛ bjɛ̃ tuʃe a vo pupe/","zh":"这个邋遢丫头竟想碰你们的娃娃","en":"This dirty girl would like to touch your dolls","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-08-015","lineIndex":15,"speaker":"Madame Thénardier","original":"Mais je me charge d'elle si jamais elle essaie","ipa":"/mɛ ʒə mə ʃaʁʒ dɛl si ʒamɛz ɛl esɛ/","zh":"她若胆敢碰，我自会收拾她。","en":"But I'll take care of her if she ever tries","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-08-016","lineIndex":16,"speaker":"Madame Thénardier","original":"Alors, Cosette, tu n'es pas encore partie","ipa":"/alɔʁ kozɛt ty nɛ paz ɑ̃kɔʁ paʁti/","zh":"所以，珂赛特，你还没有离开","en":"So, Cosette, you haven't left yet","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-08-017","lineIndex":17,"speaker":"Madame Thénardier","original":"Je n'aime pas répéter deux fois ce que je dis","ipa":"/ʒə nɛm pa ʁepete dø fwa sə kə ʒə di/","zh":"我不喜欢重复说过两次的话","en":"I don't like to repeat what I say twice","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-08-018","lineIndex":18,"speaker":"Cosette","original":"Il fait si noir et j'ai si peur","ipa":"/il fɛ si nwaʁ e ʒe si pœʁ/","zh":"天这么黑我很害怕","en":"It's so dark and I'm so scared","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-08-019","lineIndex":19,"speaker":"Cosette","original":"Dans la forêt seule à cette heure","ipa":"/dɑ̃ la foʁɛ sœl a sɛt œʁ/","zh":"这个时候独自在森林里","en":"In the forest alone at this hour","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-08-020","lineIndex":20,"speaker":"Madame Thénardier","original":"Ne discute pas et va me remplir ce seau","ipa":"/nə diskyt paz e va mə ʁɑ̃pliʁ sə so/","zh":"别争论了，去帮我装满这个桶吧","en":"Don't argue and go fill this bucket for me","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-08-021","lineIndex":21,"speaker":"Madame Thénardier","original":"Et si tu vois le loup salue-le bien bas pour nous!","ipa":"/e si ty vwa lə lu salylə bjɛ̃ ba puʁ nu/","zh":"如果你看到狼，请替我们向他低声敬礼！","en":"And if you see the wolf, salute him low for us!","note":"","sourceLineIndex":21}],"sourceOrder":8,"displayOrder":8},{"order":9,"id":"09-la-devise-du-cabaretier","title":"La Devise du Cabaretier","titleZh":"酒馆老板的座右铭","lines":[{"id":"les-miserables-1980-09-001","lineIndex":1,"speaker":"Thénardier","original":"Bon aubergiste allège les bourses","ipa":"/bɔ̃n obɛʁʒist alɛʒ le buʁs/","zh":"好客栈老板总能把客人的钱包掏轻","en":"A good innkeeper lightens purses","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-09-002","lineIndex":2,"speaker":"Thénardier","original":"Grosses ou petites des touristes en route","ipa":"/ɡʁos u pətit de tuʁistz ɑ̃ ʁut/","zh":"不论赶路旅客的钱包是大是小。","en":"whether those of passing travellers are large or small.","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-09-003","lineIndex":3,"speaker":"Thénardier","original":"Cabaretier honnêtement","ipa":"/kabaʁətje ɔnɛtmɑ̃/","zh":"做酒馆老板的，理所当然地","en":"An innkeeper, quite honestly","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-09-004","lineIndex":4,"speaker":"Thénardier","original":"Sait monnayer la soif du passant","ipa":"/sɛ mɔnɛje la swaf dy pasɑ̃/","zh":"知道怎样把过路人的口渴换成钱。","en":"knows how to turn a passerby’s thirst into money.","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-09-005","lineIndex":5,"speaker":"Thénardier","original":"Et faire tout payer par le voyageur","ipa":"/e fɛʁ tu pɛje paʁ lə vwajaʒœʁ/","zh":"让旅行者支付一切费用","en":"And make the traveler pay for everything","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-09-006","lineIndex":6,"speaker":"Thénardier","original":"Jusqu'aux mouches que son chien gobe dans le secteur","ipa":"/ʒysko muʃ kə sɔ̃ ʃjɛ̃ ɡɔb dɑ̃ lə sɛktœʁ/","zh":"连他的狗在店里吞掉的苍蝇，也得算进账。","en":"even the flies his dog swallows around the place.","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-09-007","lineIndex":7,"speaker":"Thénardier","original":"Maître Thénardier, d'infinie sagesse","ipa":"/mɛtʁ tenaʁdje dɛ̃fini saʒɛs/","zh":"泰纳第老爷，智慧无穷","en":"Master Thénardier, of endless wisdom","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-09-008","lineIndex":8,"speaker":"Thénardier","original":"Docteur-es-ivresse, et conseil en mic-mac","ipa":"/dɔktœʁɛzivʁɛs e kɔ̃sɛj ɑ̃ mikmak/","zh":"醉酒博士，兼管各种诡计的顾问","en":"doctor of drunkenness and adviser in shady schemes","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-09-009","lineIndex":9,"speaker":"Thénardier","original":"Nouveau filousophe, faux apothicaire","ipa":"/nuvo filuzɔf fo apɔtikɛʁ/","zh":"新派“骗子哲人”，假药剂师","en":"a new rogue-philosopher, a false apothecary","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-09-010","lineIndex":10,"speaker":"Thénardier","original":"Faux témoin expert près la Cour des Miracles","ipa":"/fo temwɛ̃ ɛkspɛʁ pʁɛ la kuʁ de miʁakl/","zh":"奇迹宫廷一带的资深伪证人。","en":"an expert false witness near the Court of Miracles.","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-09-011","lineIndex":11,"speaker":"Thénardier","original":"Qu'une destinée contraire","ipa":"/kyn dɛstine kɔ̃tʁɛʁ/","zh":"偏偏是坏命运","en":"A contrary fate","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-09-012","lineIndex":12,"speaker":"Thénardier","original":"A fait naître loin de la Suisse","ipa":"/a fɛ nɛtʁ lwɛ̃ də la sɥis/","zh":"把我生在远离瑞士的地方—","en":"had me born far from Switzerland","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-09-013","lineIndex":13,"speaker":"Thénardier","original":"Chambre forte de la terre","ipa":"/ʃɑ̃bʁ fɔʁt də la tɛʁ/","zh":"那里是大地的金库","en":"the earth’s strongbox","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-09-014","lineIndex":14,"speaker":"Thénardier","original":"Dont je m'sens le fils","ipa":"/dɔ̃ ʒə msɑ̃ lə fis/","zh":"我自认本该是它的儿子。","en":"whose son I feel myself to be.","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-09-015","lineIndex":15,"speaker":"Thénardier","original":"Baron de Thénard, petit en noblesse","ipa":"/baʁɔ̃ də tenaʁ pətit ɑ̃ nɔblɛs/","zh":"泰纳尔男爵，贵族气派微薄","en":"Baron de Thénard, slight in nobility","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-09-016","lineIndex":16,"speaker":"Thénardier","original":"Grand par ses bassesses et noble en petitesse","ipa":"/ɡʁɑ̃ paʁ se basɛsz e nɔbl ɑ̃ pətitɛs/","zh":"卑鄙得伟大，渺小得高贵。","en":"great in his baseness and noble in his smallness.","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-09-017","lineIndex":17,"speaker":"Thénardier","original":"Despote idéal, seigneur conjugal","ipa":"/dɛspɔt ideal sɛnjœʁ kɔ̃ʒyɡal/","zh":"理想的暴君、家中的领主","en":"an ideal despot, lord of his household","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-09-018","lineIndex":18,"speaker":"Thénardier","original":"Prince des valets, tyran du tiroir-caisse","ipa":"/pʁɛ̃s de valɛ tiʁɑ̃ dy tiʁwaʁkɛs/","zh":"仆役之王、收银抽屉的暴君。","en":"prince of servants, tyrant of the cash drawer.","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-09-019","lineIndex":19,"speaker":"Thénardier","original":"Qu'une destinée contraire","ipa":"/kyn dɛstine kɔ̃tʁɛʁ/","zh":"偏偏是坏命运","en":"A contrary fate","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-09-020","lineIndex":20,"speaker":"Thénardier","original":"A planté dans ce canton","ipa":"/a plɑ̃te dɑ̃ sə kɑ̃tɔ̃/","zh":"却把我钉在这个小地方","en":"planted me in this canton","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-09-021","lineIndex":21,"speaker":"Thénardier","original":"Quand il me faudrait la planète","ipa":"/kɑ̃t il mə fodʁɛ la planɛt/","zh":"而我需要的本该是整个世界","en":"when what I need is the whole planet","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-09-022","lineIndex":22,"speaker":"Thénardier","original":"Pour assouvir mes ambitions","ipa":"/puʁ asuviʁ mez ɑ̃bisjɔ̃/","zh":"才够填满我的野心。","en":"To satisfy my ambitions","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-09-023","lineIndex":23,"speaker":"Tous","original":"Baron de Thénard, petit en noblesse","ipa":"/baʁɔ̃ də tenaʁ pətit ɑ̃ nɔblɛs/","zh":"泰纳尔男爵，贵族气派微薄","en":"Baron de Thénard, slight in nobility","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-09-024","lineIndex":24,"speaker":"Tous","original":"Grand par ses bassesses et noble en petitesse","ipa":"/ɡʁɑ̃ paʁ se basɛsz e nɔbl ɑ̃ pətitɛs/","zh":"卑鄙时倒显得气派，渺小时又自命高贵。","en":"great in his baseness and noble in his smallness.","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-09-025","lineIndex":25,"speaker":"Tous","original":"Despote idéal, seigneur conjugal","ipa":"/dɛspɔt ideal sɛnjœʁ kɔ̃ʒyɡal/","zh":"理想的暴君、家中的领主","en":"an ideal despot, lord of his household","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-09-026","lineIndex":26,"speaker":"Tous","original":"Prince des valets, tyran du tiroir-caisse","ipa":"/pʁɛ̃s de valɛ tiʁɑ̃ dy tiʁwaʁkɛs/","zh":"仆役中的王子、钱柜里的暴君。","en":"prince of servants, tyrant of the cash drawer.","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-09-027","lineIndex":27,"speaker":"Tous","original":"Qu'une destinée contraire","ipa":"/kyn dɛstine kɔ̃tʁɛʁ/","zh":"偏偏是坏命运","en":"A contrary fate","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-09-028","lineIndex":28,"speaker":"Tous","original":"A planté dans ce canton","ipa":"/a plɑ̃te dɑ̃ sə kɑ̃tɔ̃/","zh":"却把他钉在这个小地方","en":"planted him in this canton","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-09-029","lineIndex":29,"speaker":"Tous","original":"Quand il lui faudrait la planète","ipa":"/kɑ̃t il lɥi fodʁɛ la planɛt/","zh":"而他需要的本该是整个世界","en":"when what he needs is the whole planet","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-09-030","lineIndex":30,"speaker":"Tous","original":"Pour assouvir ses ambitions","ipa":"/puʁ asuviʁ sez ɑ̃bisjɔ̃/","zh":"才够填满他的野心。","en":"To satisfy its ambitions","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-09-031","lineIndex":31,"speaker":"Thénardier","original":"Bon aubergiste doit tarifer","ipa":"/bɔ̃n obɛʁʒist dwa taʁife/","zh":"好客栈老板就得样样标价","en":"A good innkeeper must put a price on things","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-09-032","lineIndex":32,"speaker":"Thénardier","original":"Fenêtre ouverte, fenêtre fermée","ipa":"/fənɛtʁ uvɛʁt fənɛtʁ fɛʁme/","zh":"窗户打开，窗户关闭","en":"Window open, window closed","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-09-033","lineIndex":33,"speaker":"Thénardier","original":"L'fauteuil, la chaise, le tabouret","ipa":"/lfotœj la ʃɛz lə tabuʁɛ/","zh":"扶手椅、椅子、凳子","en":"The armchair, the chair, the stool","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-09-034","lineIndex":34,"speaker":"Thénardier","original":"Le lit de plume et la botte de paille","ipa":"/lə li də plym e la bɔt də paj/","zh":"羽绒床和稻草包","en":"The feather bed and the bale of straw","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-09-035","lineIndex":35,"speaker":"Thénardier","original":"Et savoir combien l'ombre use le miroir","ipa":"/e savwaʁ kɔ̃bjɛ̃ lɔ̃bʁ yz lə miʁwaʁ/","zh":"连影子会磨损镜子多少都得算清","en":"and know how much the shadow wears out the mirror","note":"","sourceLineIndex":35},{"id":"les-miserables-1980-09-036","lineIndex":36,"speaker":"Thénardier","original":"Pour saler la facture avant le départ","ipa":"/puʁ sale la faktyʁ avɑ̃ lə depaʁ/","zh":"好在客人走前把账单再加一笔。","en":"so as to salt the bill before departure.","note":"","sourceLineIndex":36},{"id":"les-miserables-1980-09-037","lineIndex":37,"speaker":"Thénardier","original":"Maître Thénardier, d'infinie sagesse","ipa":"/mɛtʁ tenaʁdje dɛ̃fini saʒɛs/","zh":"泰纳第老爷，智慧无穷","en":"Master Thénardier, of endless wisdom","note":"","sourceLineIndex":37},{"id":"les-miserables-1980-09-038","lineIndex":38,"speaker":"Thénardier","original":"Docteur-es-ivresse et conseil en mic-mac","ipa":"/dɔktœʁɛzivʁɛs e kɔ̃sɛj ɑ̃ mikmak/","zh":"醉酒博士、阴谋诡计顾问","en":"doctor of drunkenness and adviser in shady schemes","note":"","sourceLineIndex":38},{"id":"les-miserables-1980-09-039","lineIndex":39,"speaker":"Thénardier","original":"Nouveau filousophe, faux apothicaire","ipa":"/nuvo filuzɔf fo apɔtikɛʁ/","zh":"新派“骗子哲人”、假药剂师","en":"a new rogue-philosopher, a false apothecary","note":"","sourceLineIndex":39},{"id":"les-miserables-1980-09-040","lineIndex":40,"speaker":"Thénardier","original":"Faux témoin expert près la Cour des Miracles","ipa":"/fo temwɛ̃ ɛkspɛʁ pʁɛ la kuʁ de miʁakl/","zh":"奇迹宫一带的资深伪证人。","en":"an expert false witness near the Court of Miracles.","note":"","sourceLineIndex":40},{"id":"les-miserables-1980-09-041","lineIndex":41,"speaker":"Thénardier","original":"Qu'une destinée contraire","ipa":"/kyn dɛstine kɔ̃tʁɛʁ/","zh":"偏偏是坏命运","en":"A contrary fate","note":"","sourceLineIndex":41},{"id":"les-miserables-1980-09-042","lineIndex":42,"speaker":"Thénardier","original":"A fait naître loin de la Suisse","ipa":"/a fɛ nɛtʁ lwɛ̃ də la sɥis/","zh":"把我生在远离瑞士的地方—","en":"had me born far from Switzerland—","note":"","sourceLineIndex":42},{"id":"les-miserables-1980-09-043","lineIndex":43,"speaker":"Thénardier","original":"Chambre forte de la terre","ipa":"/ʃɑ̃bʁ fɔʁt də la tɛʁ/","zh":"瑞士本是大地的金库","en":"the earth's strongbox, Switzerland","note":"","sourceLineIndex":43},{"id":"les-miserables-1980-09-044","lineIndex":44,"speaker":"Thénardier","original":"Dont je me sens le fils","ipa":"/dɔ̃ ʒə mə sɑ̃ lə fis/","zh":"而我觉得自己本该是它的儿子。","en":"whose son I feel myself to be.","note":"","sourceLineIndex":44},{"id":"les-miserables-1980-09-045","lineIndex":45,"speaker":"Tous","original":"Baron de Thénard, petit en noblesse","ipa":"/baʁɔ̃ də tenaʁ pətit ɑ̃ nɔblɛs/","zh":"泰纳尔男爵，贵族气派微薄","en":"Baron de Thénard, slight in nobility","note":"","sourceLineIndex":45},{"id":"les-miserables-1980-09-046","lineIndex":46,"speaker":"Tous","original":"Grand par ses bassesses et noble en petitesse","ipa":"/ɡʁɑ̃ paʁ se basɛsz e nɔbl ɑ̃ pətitɛs/","zh":"卑鄙得伟大，渺小得高贵。","en":"great in his baseness and noble in his smallness.","note":"","sourceLineIndex":46},{"id":"les-miserables-1980-09-047","lineIndex":47,"speaker":"Tous","original":"Despote idéal, seigneur conjugal","ipa":"/dɛspɔt ideal sɛnjœʁ kɔ̃ʒyɡal/","zh":"理想的暴君、家中的领主","en":"an ideal despot, lord of his household","note":"","sourceLineIndex":47},{"id":"les-miserables-1980-09-048","lineIndex":48,"speaker":"Tous","original":"Prince des valets, tyran du tiroir-caisse","ipa":"/pʁɛ̃s de valɛ tiʁɑ̃ dy tiʁwaʁkɛs/","zh":"仆役之王、收银抽屉的暴君。","en":"prince of servants, tyrant of the cash drawer.","note":"","sourceLineIndex":48},{"id":"les-miserables-1980-09-049","lineIndex":49,"speaker":"Tous","original":"Qu'une destinée contraire","ipa":"/kyn dɛstine kɔ̃tʁɛʁ/","zh":"偏偏是坏命运","en":"A contrary fate","note":"","sourceLineIndex":49},{"id":"les-miserables-1980-09-050","lineIndex":50,"speaker":"Tous","original":"A planté dans ce canton","ipa":"/a plɑ̃te dɑ̃ sə kɑ̃tɔ̃/","zh":"却把他钉在这个小地方","en":"planted him in this canton","note":"","sourceLineIndex":50},{"id":"les-miserables-1980-09-051","lineIndex":51,"speaker":"Tous","original":"Quand il lui faudrait la planète","ipa":"/kɑ̃t il lɥi fodʁɛ la planɛt/","zh":"而他需要的本该是整个世界","en":"when what he needs is the whole planet","note":"","sourceLineIndex":51},{"id":"les-miserables-1980-09-052","lineIndex":52,"speaker":"Tous","original":"Pour assouvir ses ambitions","ipa":"/puʁ asuviʁ sez ɑ̃bisjɔ̃/","zh":"满足他的野心","en":"To satisfy its ambitions","note":"","sourceLineIndex":52},{"id":"les-miserables-1980-09-053","lineIndex":53,"speaker":"Madame Thénardier","original":"Ses ambitions au sergent parlons-en","ipa":"/sez ɑ̃bisjɔ̃z o sɛʁʒɑ̃ paʁlɔ̃zɑ̃/","zh":"说到他的雄心，还是问问中士吧","en":"As for his ambitions, ask the sergeant about them","note":"","sourceLineIndex":53},{"id":"les-miserables-1980-09-054","lineIndex":54,"speaker":"Madame Thénardier","original":"Il les a toutes laissées au berceau en naissant","ipa":"/il lez a tut lɛsez o bɛʁso ɑ̃ nɛsɑ̃/","zh":"他出生时就把它们全丢在摇篮里了。","en":"he left every one of them in the cradle at birth.","note":"","sourceLineIndex":54},{"id":"les-miserables-1980-09-055","lineIndex":55,"speaker":"Madame Thénardier","original":"Maître Feignardier d'infinie paresse","ipa":"/mɛtʁ fɛnjaʁdje dɛ̃fini paʁɛs/","zh":"懒鬼泰纳第老爷，懒得无边无际","en":"Master Lazy-nardier, infinitely lazy","note":"","sourceLineIndex":55},{"id":"les-miserables-1980-09-056","lineIndex":56,"speaker":"Madame Thénardier","original":"Avare en prouesse et mari de justesse","ipa":"/avaʁ ɑ̃ pʁwɛs e maʁi də ʒystɛs/","zh":"本事吝啬，做丈夫也只是勉强及格。","en":"miserly in deeds and barely a husband.","note":"","sourceLineIndex":56},{"id":"les-miserables-1980-09-057","lineIndex":57,"speaker":"Madame Thénardier","original":"Baron de Tocard, conjugale altesse","ipa":"/baʁɔ̃ də tokaʁ kɔ̃ʒyɡal altɛs/","zh":"废物男爵，婚姻里的“殿下”","en":"Baron of the fool, highness of the marital realm","note":"","sourceLineIndex":57},{"id":"les-miserables-1980-09-058","lineIndex":58,"speaker":"Madame Thénardier","original":"Étroit de largesse et large sans espèce","ipa":"/etʁwa də laʁʒɛs e laʁʒ sɑ̃z ɛspɛs/","zh":"出手小气，没钱时倒很“阔”。","en":"tight with generosity and expansive without a penny.","note":"","sourceLineIndex":58},{"id":"les-miserables-1980-09-059","lineIndex":59,"speaker":"Madame Thénardier","original":"Qu'une destinée traîtresse","ipa":"/kyn dɛstine tʁɛtʁɛs/","zh":"是狠心的命运","en":"A treacherous fate","note":"","sourceLineIndex":59},{"id":"les-miserables-1980-09-060","lineIndex":60,"speaker":"Madame Thénardier","original":"A placé sur mon chemin","ipa":"/a plase syʁ mɔ̃ ʃəmɛ̃/","zh":"把他摆在我的路上","en":"placed in my path","note":"","sourceLineIndex":60},{"id":"les-miserables-1980-09-061","lineIndex":61,"speaker":"Madame Thénardier","original":"Et qui promet toujours","ipa":"/e ki pʁomɛ tuʒuʁ/","zh":"还总是许诺","en":"And which always promises","note":"","sourceLineIndex":61},{"id":"les-miserables-1980-09-062","lineIndex":62,"speaker":"Madame Thénardier","original":"Que la richesse est pour demain","ipa":"/kə la ʁiʃɛs ɛ puʁ dəmɛ̃/","zh":"财富明天就会到手。","en":"That wealth is for tomorrow","note":"","sourceLineIndex":62},{"id":"les-miserables-1980-09-063","lineIndex":63,"speaker":"Thénardier","original":"Maître Thénardier","ipa":"/mɛtʁ tenaʁdje/","zh":"泰纳第老爷","en":"Maître Thénardier","note":"","sourceLineIndex":63},{"id":"les-miserables-1980-09-064","lineIndex":64,"speaker":"Madame Thénardier","original":"Maître Feignardier","ipa":"/mɛtʁ fɛnjaʁdje/","zh":"懒鬼泰纳第老爷","en":"Maître Feignardier","note":"","sourceLineIndex":64},{"id":"les-miserables-1980-09-065","lineIndex":65,"speaker":"Thénardier","original":"Docteur-es-ivresse","ipa":"/dɔktœʁɛzivʁɛs/","zh":"醉酒博士","en":"Drunken doctor","note":"","sourceLineIndex":65},{"id":"les-miserables-1980-09-066","lineIndex":66,"speaker":"Madame Thénardier","original":"Et mari de justesse","ipa":"/e maʁi də ʒystɛs/","zh":"勉强算个丈夫。","en":"And narrow husband","note":"","sourceLineIndex":66},{"id":"les-miserables-1980-09-067","lineIndex":67,"speaker":"Thénardier","original":"Baron de Thénard","ipa":"/baʁɔ̃ də tenaʁ/","zh":"泰纳尔男爵","en":"Baron de Thénard","note":"","sourceLineIndex":67},{"id":"les-miserables-1980-09-068","lineIndex":68,"speaker":"Madame Thénardier","original":"Baron de Tocard","ipa":"/baʁɔ̃ də tokaʁ/","zh":"废物男爵","en":"Baron de Tocard","note":"","sourceLineIndex":68},{"id":"les-miserables-1980-09-069","lineIndex":69,"speaker":"Thénardier","original":"Grand par ses bassesses","ipa":"/ɡʁɑ̃ paʁ se basɛs/","zh":"卑鄙得气派","en":"Great for his baseness","note":"","sourceLineIndex":69},{"id":"les-miserables-1980-09-070","lineIndex":70,"speaker":"Madame Thénardier","original":"Mais large sans espèce","ipa":"/mɛ laʁʒ sɑ̃z ɛspɛs/","zh":"可一文不名时倒装得大方。","en":"but generous when he has no money.","note":"","sourceLineIndex":70},{"id":"les-miserables-1980-09-071","lineIndex":71,"speaker":"Tous","original":"Qu'une destinée contraire","ipa":"/kyn dɛstine kɔ̃tʁɛʁ/","zh":"偏偏是坏命运","en":"A contrary fate","note":"","sourceLineIndex":71},{"id":"les-miserables-1980-09-072","lineIndex":72,"speaker":"Tous","original":"A planté dans ce canton","ipa":"/a plɑ̃te dɑ̃ sə kɑ̃tɔ̃/","zh":"把他钉在这个小地方","en":"planted him in this canton","note":"","sourceLineIndex":72},{"id":"les-miserables-1980-09-073","lineIndex":73,"speaker":"Tous","original":"Quand il lui faudrait la planète","ipa":"/kɑ̃t il lɥi fodʁɛ la planɛt/","zh":"而他需要的本该是整个世界","en":"when what he needs is the whole planet","note":"","sourceLineIndex":73},{"id":"les-miserables-1980-09-074","lineIndex":74,"speaker":"Tous","original":"Quand il lui faudrait la planète","ipa":"/kɑ̃t il lɥi fodʁɛ la planɛt/","zh":"而他需要的本该是整个世界","en":"when what he needs is the whole planet","note":"","sourceLineIndex":74},{"id":"les-miserables-1980-09-075","lineIndex":75,"speaker":"Thénardier","original":"Quand il me faudrait la planète","ipa":"/kɑ̃t il mə fodʁɛ la planɛt/","zh":"而我需要的本该是整个世界","en":"when what I need is the whole planet","note":"","sourceLineIndex":75},{"id":"les-miserables-1980-09-076","lineIndex":76,"speaker":"Thénardier","original":"Pour assouvir mes ambitions","ipa":"/puʁ asuviʁ mez ɑ̃bisjɔ̃/","zh":"才够填满我的野心。","en":"To satisfy my ambitions","note":"","sourceLineIndex":76}],"sourceOrder":9,"displayOrder":9},{"order":10,"id":"10-valjean-chez-les-thenardier","title":"Valjean chez Les Thénardier","titleZh":"冉阿让来到泰纳第家","lines":[{"id":"les-miserables-1980-10-001","lineIndex":1,"speaker":"Valjean","original":"J'ai rencontré dans la forêt","ipa":"/ʒe ʁɑ̃kɔ̃tʁe dɑ̃ la foʁɛ/","zh":"我在森林里遇见了","en":"I met in the forest","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-10-002","lineIndex":2,"speaker":"Valjean","original":"Cette petite qui tremblait de peur dans le noir","ipa":"/sɛt pətit ki tʁɑ̃blɛ də pœʁ dɑ̃ lə nwaʁ/","zh":"一个在黑暗中吓得发抖的小女孩","en":"This little one who trembled with fear in the dark","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-10-003","lineIndex":3,"speaker":"Valjean","original":"Elle m'a dit qu'elle était Cosette","ipa":"/ɛl ma di kɛl etɛ kozɛt/","zh":"她告诉我她是珂赛特","en":"She told me that she was Cosette","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-10-004","lineIndex":4,"speaker":"Valjean","original":"Et elle m'a guidé jusqu'ici à ma demande","ipa":"/e ɛl ma ɡide ʒyskisi a ma dəmɑ̃d/","zh":"她应我请求，把我领到了这里。","en":"And she guided me here at my request","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-10-005","lineIndex":5,"speaker":"Valjean","original":"Je venais chez vous ce soir pour parler d'elle ensemble","ipa":"/ʒə vənɛ ʃe vu sə swaʁ puʁ paʁle dɛl ɑ̃sɑ̃bl/","zh":"今晚我本就是来和你们谈谈她的。","en":"I came to you this evening to speak with you about her.","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-10-006","lineIndex":6,"speaker":"Valjean","original":"Oui je viens pour emmener Cosette","ipa":"/wi ʒə vjɛ̃ puʁ ɑ̃mne kozɛt/","zh":"是的，我来接珂赛特","en":"Yes I have come to take Cosette","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-10-007","lineIndex":7,"speaker":"Valjean","original":"J'ai sur moi de quoi payer ses dettes","ipa":"/ʒe syʁ mwa də kwa pɛje se dɛt/","zh":"我身上带了钱，足够偿清她的债。","en":"I have on me enough to pay her debts","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-10-008","lineIndex":8,"speaker":"Valjean","original":"Je représente ici sa pauvre mère","ipa":"/ʒə ʁəpʁezɑ̃t isi sa povʁ mɛʁ/","zh":"我在这里代替她可怜的母亲。","en":"I represent here her poor mother","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-10-009","lineIndex":9,"speaker":"Valjean","original":"Dont Dieu a décidé d'abréger enfin les misères","ipa":"/dɔ̃ djø a deside dabʁeʒe ɑ̃fɛ̃ le mizɛʁ/","zh":"上帝决定最终结束她的痛苦","en":"Whose miseries God has decided to finally put an end to","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-10-010","lineIndex":10,"speaker":"Valjean","original":"J'ai juré avant qu'elle ne nous quitte","ipa":"/ʒe ʒyʁe avɑ̃ kɛl nə nu kit/","zh":"在她离开我们之前，我曾发过誓","en":"Before she left us, I swore","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-10-011","lineIndex":11,"speaker":"Valjean","original":"J'ai juré de lui ramener son enfant","ipa":"/ʒe ʒyʁe də lɥi ʁamne sɔ̃n ɑ̃fɑ̃/","zh":"我发誓要把她的孩子带回来","en":"I swore to bring her child back","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-10-012","lineIndex":12,"speaker":"Valjean","original":"Elle n'aura pas revu sa petite","ipa":"/ɛl noʁa pa ʁəvy sa pətit/","zh":"她终究没能再见女儿一面","en":"She won't have seen her little one again","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-10-013","lineIndex":13,"speaker":"Valjean","original":"Et Cosette pas vu sa maman","ipa":"/e kozɛt pa vy sa mamɑ̃/","zh":"珂赛特也没能再见母亲一面。","en":"And Cosette hasn't seen her mother","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-10-014","lineIndex":14,"speaker":"Valjean (en canon avec les Thénardier)","original":"Je ferai ce qu'elle n'a pas pu faire","ipa":"/ʒə fəʁe sə kɛl na pa py fɛʁ/","zh":"我会做她做不到的事情","en":"I will do what she couldn't do","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-10-015","lineIndex":15,"speaker":"Valjean (en canon avec les Thénardier)","original":"J'essaierai pour elle d'être bon père","ipa":"/ʒesɛʁe puʁ ɛl dɛtʁ bɔ̃ pɛʁ/","zh":"为了她，我会努力做个好父亲。","en":"For her, I will try to be a good father.","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-10-016","lineIndex":16,"speaker":"Valjean (en canon avec les Thénardier)","original":"Vos bienfaits vont trouver récompense","ipa":"/vo bjɛ̃fɛ vɔ̃ tʁuve ʁekɔ̃pɑ̃s/","zh":"你们照看她的恩情，自会得到回报。","en":"Your blessings will be rewarded","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-10-017","lineIndex":17,"speaker":"Valjean (en canon avec les Thénardier)","original":"Faites-moi sur l'heure le compte de vos dépenses","ipa":"/fɛtmwa syʁ lœʁ lə kɔ̃t də vo depɑ̃s/","zh":"现在就把你们的花费算给我。","en":"Give me an account of your expenses immediately","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-10-018","lineIndex":18,"speaker":"Les Thénardier (en canon avec Valjean)","original":"Donnez-moi votre manteau","ipa":"/dɔnemwa votʁ mɑ̃to/","zh":"把你的外套给我","en":"Give me your coat","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-10-019","lineIndex":19,"speaker":"Les Thénardier (en canon avec Valjean)","original":"Asseyez-vous, mon bon monsieur","ipa":"/asɛjevu mɔ̃ bɔ̃ məsjø/","zh":"坐下，我的好先生","en":"Sit down, my good sir","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-10-020","lineIndex":20,"speaker":"Les Thénardier (en canon avec Valjean)","original":"Là, près de la cheminée","ipa":"/la pʁɛ də la ʃəmine/","zh":"那边，壁炉边","en":"There, by the fireplace","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-10-021","lineIndex":21,"speaker":"Les Thénardier (en canon avec Valjean)","original":"Là, au chaud vous serez bien mieux","ipa":"/la o ʃo vu səʁe bjɛ̃ mjø/","zh":"那儿暖和，您会舒服得多。","en":"There, in the warmth you will be much better","note":"","sourceLineIndex":21}],"sourceOrder":10,"displayOrder":10},{"order":11,"id":"11-la-valse-de-la-fourberie","title":"La Valse de la Fourberie","titleZh":"欺骗的华尔兹","lines":[{"id":"les-miserables-1980-11-001","lineIndex":1,"speaker":"Thénardier","original":"Oui, Monsieur, bien Monsieur","ipa":"/wi məsjø bjɛ̃ məsjø/","zh":"是的，先生，好吧，先生","en":"Yes, sir, well sir","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-11-002","lineIndex":2,"speaker":"Thénardier","original":"Vous venez nous enlever Cosette","ipa":"/vu vəne nuz ɑ̃lve kozɛt/","zh":"你来接我们身边的珂赛特","en":"You have come to take Cosette away from us","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-11-003","lineIndex":3,"speaker":"Thénardier","original":"Que sa mère nous confia","ipa":"/kə sa mɛʁ nu kɔ̃fja/","zh":"她母亲托付给我们照看的","en":"whom her mother entrusted to us","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-11-004","lineIndex":4,"speaker":"Thénardier","original":"Et que Dieu ait son âme la pauvrette!","ipa":"/e kə djø ɛ sɔ̃n am la povʁɛt/","zh":"愿上帝收下她的灵魂，可怜的人！","en":"and God rest her soul, poor woman!","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-11-005","lineIndex":5,"speaker":"Thénardier","original":"Qui nous dit, qui nous prouve","ipa":"/ki nu di ki nu pʁuv/","zh":"谁能告诉我们，谁能证明","en":"Who tells us, who proves to us","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-11-006","lineIndex":6,"speaker":"Thénardier","original":"Que vos intentions sont bien honnêtes?","ipa":"/kə voz ɛ̃tɑ̃sjɔ̃ sɔ̃ bjɛ̃n ɔnɛt/","zh":"您的意图真的正当呢？","en":"That your intentions are truly honest?","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-11-007","lineIndex":7,"speaker":"Thénardier","original":"Je vous crois mais l'argent","ipa":"/ʒə vu kʁwa mɛ laʁʒɑ̃/","zh":"我相信你，但钱","en":"I believe you but money","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-11-008","lineIndex":8,"speaker":"Thénardier","original":"Compte peu quand on aime comptant","ipa":"/kɔ̃t pø kɑ̃t ɔ̃n ɛm kɔ̃tɑ̃/","zh":"可要是拿现金来说，感情就不值几个钱。","en":"counts for little when one loves cash.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-11-009","lineIndex":9,"speaker":"Thénardier","original":"Elle était chouchoutée","ipa":"/ɛl etɛ ʃuʃute/","zh":"她被宠坏了","en":"She was pampered","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-11-010","lineIndex":10,"speaker":"Thénardier","original":"Tout comme si elle était notre enfant","ipa":"/tu kɔm si ɛl etɛ notʁ ɑ̃fɑ̃/","zh":"就像我们的孩子","en":"Just as if she were our child","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-11-011","lineIndex":11,"speaker":"Thénardier","original":"Notre enfant, Monsieur!","ipa":"/notʁ ɑ̃fɑ̃ məsjø/","zh":"我们的孩子，先生！","en":"Our child, Sir!","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-11-012","lineIndex":12,"speaker":"Valjean","original":"Vous avez pris beaucoup de peine","ipa":"/vuz ave pʁi boku də pɛn/","zh":"你费了很多麻烦","en":"You have taken a lot of trouble","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-11-013","lineIndex":13,"speaker":"Valjean","original":"Mais tout salaire mérite sa peine","ipa":"/mɛ tu salɛʁ meʁit sa pɛn/","zh":"但每一份劳动都该得到报酬。","en":"But all labour deserves its wage.","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-11-014","lineIndex":14,"speaker":"Valjean","original":"Voilà encore cinquante francs pour solde de tout paiement","ipa":"/vwala ɑ̃kɔʁ sɛ̃kɑ̃t fʁɑ̃ puʁ sɔld də tu pɛmɑ̃/","zh":"再给五十法郎，作为全部款项的结清。","en":"Here is another fifty francs for the balance of all payment","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-11-015","lineIndex":15,"speaker":"Valjean","original":"Et cette fois est-ce que ça va?","ipa":"/e sɛt fwaz ɛs kə sa va/","zh":"这次可以吗？","en":"And this time is it okay?","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-11-016","lineIndex":16,"speaker":"Madame Thénardier","original":"Ça irait bien assez","ipa":"/sa iʁɛ bjɛ̃n ase/","zh":"这样就足够了","en":"It would be good enough","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-11-017","lineIndex":17,"speaker":"Madame Thénardier","original":"Si nous ne l'avions pas tant gâtée","ipa":"/si nu nə lavjɔ̃ pa tɑ̃ ɡate/","zh":"如果我们没有太宠坏她的话","en":"If we hadn't spoiled her so much","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-11-018","lineIndex":18,"speaker":"Madame Thénardier","original":"Les potions coûtent cher","ipa":"/le posjɔ̃ kut ʃɛʁ/","zh":"药水很贵","en":"Potions are expensive","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-11-019","lineIndex":19,"speaker":"Madame Thénardier","original":"Il fallait se serrer la ceinture","ipa":"/il falɛ sə sɛʁe la sɛ̃tyʁ/","zh":"我们必须勒紧裤腰带","en":"We had to tighten our belts","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-11-020","lineIndex":20,"speaker":"Madame Thénardier","original":"Mais Monsieur on l'aimait","ipa":"/mɛ məsjø ɔ̃ lɛmɛ/","zh":"可是先生，我们很爱她","en":"But, sir, we loved her","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-11-021","lineIndex":21,"speaker":"Madame Thénardier","original":"Et on ne refait pas sa nature","ipa":"/e ɔ̃ nə ʁəfɛ pa sa natyʁ/","zh":"人总改不了自己的天性。","en":"and one cannot remake one's nature.","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-11-022","lineIndex":22,"speaker":"Les Thénardier","original":"Oui Monsieur, bien Monsieur","ipa":"/wi məsjø bjɛ̃ məsjø/","zh":"是的，先生，好的，先生","en":"Yes Sir, well Sir","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-11-023","lineIndex":23,"speaker":"Les Thénardier","original":"Vous venez nous enlever Cosette","ipa":"/vu vəne nuz ɑ̃lve kozɛt/","zh":"你来接我们身边的珂赛特","en":"You have come to take Cosette away from us","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-11-024","lineIndex":24,"speaker":"Les Thénardier","original":"Ah, Monsieur! Vrai, Monsieur!","ipa":"/a məsjø vʁɛ məsjø/","zh":"啊，先生！确实，先生！","en":"Ah, Sir! True, sir!","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-11-025","lineIndex":25,"speaker":"Les Thénardier","original":"C'est qu'elle va nous manquer la fillette","ipa":"/sɛ kɛl va nu mɑ̃ke la fijɛt/","zh":"我们会想念那个小女孩的","en":"We're going to miss the little girl","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-11-026","lineIndex":26,"speaker":"Valjean","original":"Je rajoute trente sous","ipa":"/ʒə ʁaʒut tʁɑ̃t su/","zh":"我再添三十苏。","en":"I'll add thirty cents","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-11-027","lineIndex":27,"speaker":"Valjean","original":"Ça nous fait quinze cent francs en tout","ipa":"/sa nu fɛ kɛ̃z sɑ̃ fʁɑ̃z ɑ̃ tu/","zh":"这样我们总共就有一千五百法郎","en":"That makes us fifteen hundred francs in total","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-11-028","lineIndex":28,"speaker":"Valjean","original":"Adjugé viens Cosette","ipa":"/adʒyʒe vjɛ̃ kozɛt/","zh":"成交，来吧，珂赛特。","en":"Come on Cosette","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-11-029","lineIndex":29,"speaker":"Valjean","original":"Ta poupée est pressée de partir","ipa":"/ta pupe ɛ pʁɛse də paʁtiʁ/","zh":"你的娃娃急着要离开","en":"Your doll is in a hurry to leave","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-11-030","lineIndex":30,"speaker":"Valjean","original":"Et vous deux comptez bien","ipa":"/e vu dø kɔ̃te bjɛ̃/","zh":"你们两个真会算计","en":"And you two count well","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-11-031","lineIndex":31,"speaker":"Valjean","original":"Et que Dieu vous donne à réfléchir","ipa":"/e kə djø vu dɔn a ʁefleʃiʁ/","zh":"愿上帝让你们好好反省。","en":"And may God give you something to think about","note":"","sourceLineIndex":31}],"sourceOrder":11,"displayOrder":11},{"order":12,"id":"12-donnez-donnez","title":"Donnez, donnez","titleZh":"给予，给予","lines":[{"id":"les-miserables-1980-12-001","lineIndex":1,"speaker":"Mendiants","original":"Donnez, donnez, donnez aux pauvres gueux","ipa":"/dɔne dɔne dɔnez o povʁ ɡø/","zh":"给，给，给可怜的乞丐","en":"Give, give, give to the poor beggars","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-12-002","lineIndex":2,"speaker":"Mendiants","original":"Donner, donner, c'est prêter au bon Dieu","ipa":"/dɔne dɔne sɛ pʁɛte o bɔ̃ djø/","zh":"给，给，就是借给善良的主","en":"To give, to give, is to lend to the good Lord","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-12-003","lineIndex":3,"speaker":"Mendiants","original":"Donnez, donnez, belles Dames, jolis Messieurs","ipa":"/dɔne dɔne bɛl dam ʒoli mesjø/","zh":"给，给，美丽的女士，漂亮先生们","en":"Give, give, beautiful ladies, pretty gentlemen","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-12-004","lineIndex":4,"speaker":"Mendiants","original":"Donner, donner, c'est gagner sa place aux cieux","ipa":"/dɔne dɔne sɛ ɡanje sa plas o sjø/","zh":"给予，给予，就是在天堂赢得一席之地","en":"To give, to give, is to earn your place in heaven","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-12-005","lineIndex":5,"speaker":"Gavroche","original":"Bonjour, Paris, c'est moi, Gavroche","ipa":"/bɔ̃ʒuʁ paʁi sɛ mwa ɡavʁɔʃ/","zh":"你好，巴黎，我是加弗罗什","en":"Hello, Paris, it's me, Gavroche","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-12-006","lineIndex":6,"speaker":"Gavroche","original":"V'la ma famille, v'la ma maison","ipa":"/vla ma famij vla ma mɛzɔ̃/","zh":"这是我的家人，这是我的房子","en":"There's my family, there's my house","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-12-007","lineIndex":7,"speaker":"Gavroche","original":"Rien dans les mains, rien dans les poches","ipa":"/ʁiɛ̃ dɑ̃ le mɛ̃ ʁiɛ̃ dɑ̃ le poʃ/","zh":"我手里什么都没有，口袋里什么也没有","en":"Nothing in my hands, nothing in my pockets","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-12-008","lineIndex":8,"speaker":"Gavroche","original":"J'ai pas de sous et pourtant j'me démerde","ipa":"/ʒe pa də suz e puʁtɑ̃ ʒmə demɛʁd/","zh":"我没钱，可我总能自己想办法。","en":"I have no money, yet I manage somehow.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-12-009","lineIndex":9,"speaker":"Gavroche","original":"Et j'y vois clair, surtout la nuit","ipa":"/e ʒi vwa klɛʁ syʁtu la nɥi/","zh":"我看得很清楚，尤其是在晚上","en":"And I see clearly, especially at night","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-12-010","lineIndex":10,"speaker":"Gavroche","original":"De la Glacière à Belleville","ipa":"/də la ɡlasjɛʁ a bɛlvil/","zh":"从冰窖街到贝尔维尔","en":"From the Glacière to Belleville","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-12-011","lineIndex":11,"speaker":"Gavroche","original":"Et de Montmartre à Montsouris","ipa":"/e də mɔ̃maʁtʁ a mɔ̃tsuʁi/","zh":"从蒙马特到蒙苏里","en":"And from Montmartre to Montsouris","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-12-012","lineIndex":12,"speaker":"Gavroche","original":"Les timides, les caïds, suivez l'guide!","ipa":"/le timid le kaid sɥive lɡid/","zh":"胆小的、狠角色，都跟着我！","en":"The timid, the tough guys, follow the guide!","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-12-013","lineIndex":13,"speaker":"Mendiants","original":"Donnez, donnez, donnez aux pauvres gueux","ipa":"/dɔne dɔne dɔnez o povʁ ɡø/","zh":"给，给，给可怜的乞丐","en":"Give, give, give to the poor beggars","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-12-014","lineIndex":14,"speaker":"Mendiants","original":"Donner, donner, c'est prêter au bon Dieu","ipa":"/dɔne dɔne sɛ pʁɛte o bɔ̃ djø/","zh":"给，给，就是借给善良的主","en":"To give, to give, is to lend to the good Lord","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-12-015","lineIndex":15,"speaker":"Mendiants","original":"Donnez, donnez, belles Dames, jolis Messieurs","ipa":"/dɔne dɔne bɛl dam ʒoli mesjø/","zh":"给，给，美丽的女士，漂亮先生们","en":"Give, give, beautiful ladies, pretty gentlemen","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-12-016","lineIndex":16,"speaker":"Mendiants","original":"Donner, donner, c'est gagner sa place aux cieux","ipa":"/dɔne dɔne sɛ ɡanje sa plas o sjø/","zh":"给予，给予，就是在天堂赢得一席之地","en":"To give, to give, is to earn your place in heaven","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-12-017","lineIndex":17,"speaker":"Gavroche","original":"Faut qu'j'affranchisse les gens d'la haute","ipa":"/fo k ʒafʁɑ̃ʃis le ʒɑ̃ də la ot/","zh":"得让上流人见见世面","en":"I have to enlighten the people up top","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-12-018","lineIndex":18,"speaker":"Gavroche","original":"C'est pas Versailles pour l'élégance","ipa":"/sɛ pa vɛʁsaj puʁ leleɡɑ̃s/","zh":"这不是凡尔赛宫的优雅","en":"It's not Versailles for elegance","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-12-019","lineIndex":19,"speaker":"Gavroche","original":"Mais d'puis qu'on a raccourci l'autre","ipa":"/mɛ dpɥi kɔ̃n a ʁakuʁsi lotʁ/","zh":"可自从我们把前一个国王送上断头台","en":"But since the other king was shortened","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-12-020","lineIndex":20,"speaker":"Gavroche","original":"Versailles, ça manque plutôt d'ambiance","ipa":"/vɛʁsaj sa mɑ̃k plyto dɑ̃bjɑ̃s/","zh":"凡尔赛反倒冷清得很。","en":"Versailles has rather lacked atmosphere.","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-12-021","lineIndex":21,"speaker":"Gavroche","original":"C'est pas qu'le diable qu'on a aux Tuileries","ipa":"/sɛ pa k lə djabl kɔ̃n a o tɥiləʁi/","zh":"杜伊勒里宫里的那位“魔王”","en":"It is not that the devil at the Tuileries","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-12-022","lineIndex":22,"speaker":"Gavroche","original":"Soit plus malin qu'le serrurier","ipa":"/swa ply malɛ̃ k lə sɛʁyʁje/","zh":"会比开锁匠更聪明；","en":"is cleverer than the locksmith;","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-12-023","lineIndex":23,"speaker":"Gavroche","original":"J'aime bien sa poire mais qu'en effigie","ipa":"/ʒɛm bjɛ̃ sa pwaʁ mɛ kɑ̃n efiʒi/","zh":"我喜欢他那张“梨脸”，只限于肖像上","en":"I like his pear-shaped face, but only as an effigy","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-12-024","lineIndex":24,"speaker":"Gavroche","original":"Frappée sur les pièces de monnaie","ipa":"/fʁape syʁ le pjɛs də mɔnɛ/","zh":"印在硬币上的那一种。","en":"stamped on coins.","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-12-025","lineIndex":25,"speaker":"Gavroche","original":"Vive moi, pas le roi, ça ira, ça ira!","ipa":"/viv mwa pa lə ʁwa sa iʁa sa iʁa/","zh":"我万岁，不是国王万岁！“会好的，终会好的！”","en":"Long live me, not the king, it will be fine, it will be fine!","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-12-026","lineIndex":26,"speaker":"Enjolras","original":"Heureusement qu'chez les gens d'la haute","ipa":"/øʁøzmɑ̃ k ʃe le ʒɑ̃ də la ot/","zh":"还好，上流社会的人中","en":"Fortunately, among the upper class people","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-12-027","lineIndex":27,"speaker":"Enjolras","original":"Y en a qui regardent en bas!","ipa":"/i ɑ̃n a ki ʁəɡaʁdt ɑ̃ ba/","zh":"还有人会往下看！","en":"there are some who look down!","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-12-028","lineIndex":28,"speaker":"Enjolras","original":"On a le général Lamarque","ipa":"/ɔ̃n a lə ʒeneʁal lamaʁk/","zh":"我们有拉马克将军","en":"We have General Lamarque","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-12-029","lineIndex":29,"speaker":"Enjolras","original":"Qui parle un peu de nous, parfois","ipa":"/ki paʁl œ̃ pø də nu paʁfwa/","zh":"他偶尔还会替我们说几句话。","en":"Who talks a little about us, sometimes","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-12-030","lineIndex":30,"speaker":"Enjolras","original":"Y paraît qu'il est bien malade","ipa":"/i paʁɛ kil ɛ bjɛ̃ malad/","zh":"看起来他病得很重","en":"It seems that he is very ill","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-12-031","lineIndex":31,"speaker":"Enjolras","original":"Qu'est-ce qu'on f'ra quand il s'en ira?","ipa":"/kɛs kɔ̃ fʁa kɑ̃t il sɑ̃n iʁa/","zh":"他走后我们该怎么办？","en":"What will we do when he goes away?","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-12-032","lineIndex":32,"speaker":"Enjolras","original":"Avec l'émeute déjà qui gronde","ipa":"/avɛk lemøt deʒa ki ɡʁɔ̃d/","zh":"骚乱已经酝酿","en":"With the riot already brewing","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-12-033","lineIndex":33,"speaker":"Enjolras","original":"Paris ressemble à un volcan","ipa":"/paʁi ʁəsɑ̃bl a œ̃ vɔlkɑ̃/","zh":"巴黎就像一座火山","en":"Paris resembles a volcano","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-12-034","lineIndex":34,"speaker":"Enjolras","original":"Prêt à vomir la lave de sa colère","ipa":"/pʁɛ a vomiʁ la lav də sa kolɛʁ/","zh":"随时要喷涌出愤怒的熔岩","en":"ready to spew the lava of its anger","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-12-035","lineIndex":35,"speaker":"Enjolras","original":"Enfin révolutionnaire!","ipa":"/ɑ̃fɛ̃ ʁevolysjɔnɛʁ/","zh":"终会化作革命！","en":"at last revolutionary!","note":"","sourceLineIndex":35},{"id":"les-miserables-1980-12-036","lineIndex":36,"speaker":"Gavroche","original":"Le chef de c'te bande qui complote","ipa":"/lə ʃɛf də stə bɑ̃d ki kɔ̃plɔt/","zh":"这个团伙的头目正在密谋","en":"The leader of this gang who is plotting","note":"","sourceLineIndex":36},{"id":"les-miserables-1980-12-037","lineIndex":37,"speaker":"Gavroche","original":"C'est Thénardier, de Montfermeil","ipa":"/sɛ tenaʁdje də mɔ̃tfɛʁmɛj/","zh":"这是来自蒙费梅伊的德纳第","en":"It's Thénardier, from Montfermeil","note":"","sourceLineIndex":37},{"id":"les-miserables-1980-12-038","lineIndex":38,"speaker":"Gavroche","original":"Qu'a lâché là-bas sa gargote","ipa":"/ka laʃe laba sa ɡaʁɡɔt/","zh":"他把那边的小饭馆丢下不管了","en":"who left his little eatery back there","note":"","sourceLineIndex":38},{"id":"les-miserables-1980-12-039","lineIndex":39,"speaker":"Gavroche","original":"Parce qu'à Paname, y a plus d'oseille","ipa":"/paʁs ka panam i a ply dozɛj/","zh":"因为巴黎这边更有油水。","en":"because there is more money in Paris.","note":"","sourceLineIndex":39},{"id":"les-miserables-1980-12-040","lineIndex":40,"speaker":"Gavroche","original":"Çui-là, y fait bosser toute sa famille","ipa":"/sɥila i fɛ bɔse tut sa famij/","zh":"那家伙让全家都替他干活","en":"That one puts his whole family to work","note":"","sourceLineIndex":40},{"id":"les-miserables-1980-12-041","lineIndex":41,"speaker":"Gavroche","original":"Même sa gamine piège les pigeons","ipa":"/mɛm sa ɡamin pjɛʒ le piʒɔ̃/","zh":"连他的小女儿都去诱骗冤大头。","en":"even his little girl traps gullible marks.","note":"","sourceLineIndex":41},{"id":"les-miserables-1980-12-042","lineIndex":42,"speaker":"Gavroche","original":"C'est l'Éponine, Gavroche en jupons","ipa":"/sɛ leponin ɡavʁɔʃ ɑ̃ ʒypɔ̃/","zh":"那是艾潘妮—穿裙子的加弗罗什","en":"That is Éponine, Gavroche in petticoats","note":"","sourceLineIndex":42},{"id":"les-miserables-1980-12-043","lineIndex":43,"speaker":"Gavroche","original":"Qu'a l'cœur qui flanche pour pas un rond","ipa":"/ka lkœʁ ki flɑ̃ʃ puʁ paz œ̃ ʁɔ̃/","zh":"一颗心硬得连一分钱都动摇不了。","en":"whose heart does not falter for a penny.","note":"","sourceLineIndex":43},{"id":"les-miserables-1980-12-044","lineIndex":44,"speaker":"Gavroche","original":"Y fait faim, y fait froid, mais au moins, j'm'ennuie pas","ipa":"/i fɛ fɛ̃ i fɛ fʁwa mɛz o mwɛ̃ ʒəmɑ̃nɥi pa/","zh":"挨饿受冻也罢，至少我不无聊。","en":"I am hungry and cold, but at least I am not bored.","note":"","sourceLineIndex":44},{"id":"les-miserables-1980-12-045","lineIndex":45,"speaker":"Mendiants","original":"Donnez, donnez, donnez aux pauvres gueux","ipa":"/dɔne dɔne dɔnez o povʁ ɡø/","zh":"给，给，给可怜的乞丐","en":"Give, give, give to the poor beggars","note":"","sourceLineIndex":45},{"id":"les-miserables-1980-12-046","lineIndex":46,"speaker":"Mendiants","original":"Donner, donner, c'est prêter au bon Dieu","ipa":"/dɔne dɔne sɛ pʁɛte o bɔ̃ djø/","zh":"给，给，就是借给善良的主","en":"To give, to give, is to lend to the good Lord","note":"","sourceLineIndex":46},{"id":"les-miserables-1980-12-047","lineIndex":47,"speaker":"Mendiants","original":"Donnez, donnez, belles Dames, jolis Messieurs","ipa":"/dɔne dɔne bɛl dam ʒoli mesjø/","zh":"给，给，美丽的女士，漂亮先生们","en":"Give, give, beautiful ladies, pretty gentlemen","note":"","sourceLineIndex":47},{"id":"les-miserables-1980-12-048","lineIndex":48,"speaker":"Mendiants","original":"Donner, donner, c'est gagner sa place aux cieux","ipa":"/dɔne dɔne sɛ ɡanje sa plas o sjø/","zh":"给予，给予，就是在天堂赢得一席之地","en":"To give, to give, is to earn your place in heaven","note":"","sourceLineIndex":48},{"id":"les-miserables-1980-12-049","lineIndex":49,"speaker":"Thénardier","original":"Répétition, chacun son poste","ipa":"/ʁepetisjɔ̃ ʃakœ̃ sɔ̃ pɔst/","zh":"重复，各司其职","en":"Repetition, each to his own post","note":"","sourceLineIndex":49},{"id":"les-miserables-1980-12-050","lineIndex":50,"speaker":"Thénardier","original":"Babet, Claquesous, en place","ipa":"/babɛ klakzu ɑ̃ plas/","zh":"巴贝特，克拉克索，到位","en":"Babet, Claquesous, in place","note":"","sourceLineIndex":50},{"id":"les-miserables-1980-12-051","lineIndex":51,"speaker":"Thénardier","original":"Toi, Montparnasse, tu fais le guet","ipa":"/twa mɔ̃paʁnas ty fɛ lə ɡɛ/","zh":"你，蒙帕纳斯，你保持警惕","en":"You, Montparnasse, you keep watch","note":"","sourceLineIndex":51},{"id":"les-miserables-1980-12-052","lineIndex":52,"speaker":"Thénardier","original":"Avec 'Ponine, faites bien gaffe","ipa":"/avɛk ponin fɛt bjɛ̃ ɡaf/","zh":"跟小潘妮一起，给我盯紧点。","en":"With ’Ponine, keep a sharp watch.","note":"","sourceLineIndex":52},{"id":"les-miserables-1980-12-053","lineIndex":53,"speaker":"Thénardier","original":"J'ai pas envie, non, de r'voir l'maton","ipa":"/ʒe paz ɑ̃vi nɔ̃ də ʁəvwaʁ lmatɔ̃/","zh":"我可不想再见到狱警。","en":"I do not want to see the prison guard again.","note":"","sourceLineIndex":53},{"id":"les-miserables-1980-12-054","lineIndex":54,"speaker":"Thénardier","original":"J'y fais d'abord mon numéro","ipa":"/ʒi fɛ dabɔʁ mɔ̃ nymeʁo/","zh":"我先在那儿演一出自己的戏。","en":"I will do my little act there first.","note":"","sourceLineIndex":54},{"id":"les-miserables-1980-12-055","lineIndex":55,"speaker":"Thénardier","original":"Méli-malheur-mélo","ipa":"/melimalœʁmelo/","zh":"大杂烩","en":"Hodge-podge","note":"","sourceLineIndex":55},{"id":"les-miserables-1980-12-056","lineIndex":56,"speaker":"Thénardier","original":"S'il a du cœur, deux thunes qu'y pleure","ipa":"/sil a dy kœʁ dø tyn ki plœʁ/","zh":"他若有点良心，我赌两苏他会哭。","en":"If he has a heart, I bet two sous he will cry.","note":"","sourceLineIndex":56},{"id":"les-miserables-1980-12-057","lineIndex":57,"speaker":"Thénardier","original":"Qu'y crie bravo, encore, bis","ipa":"/ki kʁi bʁavo ɑ̃kɔʁ bis/","zh":"然后喊“好！”“再来一遍！”","en":"and shout “bravo, again, encore!”","note":"","sourceLineIndex":57},{"id":"les-miserables-1980-12-058","lineIndex":58,"speaker":"Thénardier","original":"C'est là qu'on cogne sec","ipa":"/sɛ la kɔ̃ kɔɲ sɛk/","zh":"到那时候，我们就下狠手","en":"That is when we hit hard","note":"","sourceLineIndex":58},{"id":"les-miserables-1980-12-059","lineIndex":59,"speaker":"Thénardier","original":"Jusqu'à c'qu'y casque","ipa":"/ʒyska ski kask/","zh":"直到他掏钱为止。","en":"until he coughs up.","note":"","sourceLineIndex":59},{"id":"les-miserables-1980-12-060","lineIndex":60,"speaker":"Madame Thénardier","original":"Voilà l'étudiant qui s'amène","ipa":"/vwala letydjɑ̃ ki samɛn/","zh":"学生来了","en":"Here comes the student","note":"","sourceLineIndex":60},{"id":"les-miserables-1980-12-061","lineIndex":61,"speaker":"Madame Thénardier","original":"Notre voisin déshérité","ipa":"/notʁ vwazɛ̃ dezeʁite/","zh":"我们这个被剥夺了继承权的邻居","en":"our disinherited neighbour","note":"","sourceLineIndex":61},{"id":"les-miserables-1980-12-062","lineIndex":62,"speaker":"Madame Thénardier","original":"Par un grand-père qu'a de la fraîche","ipa":"/paʁ œ̃ ɡʁɑ̃pɛʁ ka də la fʁɛʃ/","zh":"有个很有钱的祖父","en":"whose grandfather has plenty of cash","note":"","sourceLineIndex":62},{"id":"les-miserables-1980-12-063","lineIndex":63,"speaker":"Madame Thénardier","original":"Et qui veut pas lui en lâcher","ipa":"/e ki vø pa lɥi ɑ̃ laʃe/","zh":"却一分钱也不肯给他。","en":"and will not let him have any of it.","note":"","sourceLineIndex":63},{"id":"les-miserables-1980-12-064","lineIndex":64,"speaker":"Marius","original":"Bonjour Mademoiselle Éponine","ipa":"/bɔ̃ʒuʁ madmwazɛl eponin/","zh":"你好艾潘妮小姐","en":"Hello Miss Éponine","note":"","sourceLineIndex":64},{"id":"les-miserables-1980-12-065","lineIndex":65,"speaker":"Marius","original":"Que faites-vous dans le quartier?","ipa":"/kə fɛtvu dɑ̃ lə kaʁtje/","zh":"你在附近做什么？","en":"What are you doing in the neighborhood?","note":"","sourceLineIndex":65},{"id":"les-miserables-1980-12-066","lineIndex":66,"speaker":"Éponine","original":"Des choses que la morale réprime","ipa":"/de ʃoz kə la moʁal ʁepʁim/","zh":"做些道德不容的事","en":"Things morality condemns","note":"","sourceLineIndex":66},{"id":"les-miserables-1980-12-067","lineIndex":67,"speaker":"Éponine","original":"Pour qu'ce soir, on ait à manger","ipa":"/puʁ k sə swaʁ ɔ̃n ɛt a mɑ̃ʒe/","zh":"今晚我们有东西吃","en":"So that tonight we have something to eat","note":"","sourceLineIndex":67}],"sourceOrder":12,"displayOrder":12},{"order":13,"id":"13-rouge-et-noir","title":"Rouge et noir","titleZh":"红与黑","lines":[{"id":"les-miserables-1980-13-001","lineIndex":1,"speaker":"Marius","original":"L'ai-je au moins jamais vue, cette douce inconnue","ipa":"/lɛʒ o mwɛ̃ ʒamɛ vy sɛt dus ɛ̃kɔny/","zh":"这温柔的陌生姑娘，我究竟见过她吗？","en":"Have I ever truly seen this gentle stranger?","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-13-002","lineIndex":2,"speaker":"Marius","original":"Ou n'est elle qu'un songe vain comme les mensonges de l'histoire","ipa":"/u nɛt ɛl kœ̃ sɔ̃ʒ vɛ̃ kɔm le mɑ̃sɔ̃ʒ də listwaʁ/","zh":"还是说，她只是历史谎言般的一场虚幻梦境？","en":"Or is she only a vain dream, like history’s lies?","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-13-003","lineIndex":3,"speaker":"Marius","original":"Ne l'ai-je pas rêvée comme cet idéal","ipa":"/nə lɛʒ pa ʁɛve kɔm sɛt ideal/","zh":"难道我不曾梦见她，如同梦见那个理想？","en":"Have I not dreamed of her as I dreamed of that ideal","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-13-004","lineIndex":4,"speaker":"Marius","original":"Qui ferait qu'enfin l'homme échappe à l'animal","ipa":"/ki fəʁɛ kɑ̃fɛ̃ lɔm eʃap a lanimal/","zh":"那理想终于能让人摆脱兽性","en":"that would finally let humankind escape the animal","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-13-005","lineIndex":5,"speaker":"Marius","original":"Qu'il soit enfin lui-même et vive son poème","ipa":"/kil swa ɑ̃fɛ̃ lɥimɛm e viv sɔ̃ pɔɛm/","zh":"让他最终成为他自己，活出他的诗","en":"Let him finally be himself and live his poem","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-13-006","lineIndex":6,"speaker":"Marius","original":"Rouge, le peuple est en colère","ipa":"/ʁuʒ lə pøpl ɛt ɑ̃ kolɛʁ/","zh":"红色，是愤怒的人民；","en":"the people are angry.","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-13-007","lineIndex":7,"speaker":"Marius","original":"Noire, l'espérance de la terre","ipa":"/nwaʁ lɛspeʁɑ̃s də la tɛʁ/","zh":"黑色，是大地的希望。","en":"the earth’s hope.","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-13-008","lineIndex":8,"speaker":"Marius","original":"Rouge, mon sang tourne à l'envers","ipa":"/ʁuʒ mɔ̃ sɑ̃ tuʁn a lɑ̃vɛʁ/","zh":"红色，我的血在倒流；","en":"my blood runs backwards.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-13-009","lineIndex":9,"speaker":"Marius","original":"Noir, mon cœur est en misère","ipa":"/nwaʁ mɔ̃ kœʁ ɛt ɑ̃ mizɛʁ/","zh":"黑色，我的心陷在苦难里。","en":"my heart is in misery.","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-13-010","lineIndex":10,"speaker":"Marius","original":"Sans elle, loin d'elle, malade d'elle","ipa":"/sɑ̃z ɛl lwɛ̃ dɛl malad dɛl/","zh":"没有她，远离她，又为她害相思。","en":"Without her, far from her, sick with longing for her.","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-13-011","lineIndex":11,"speaker":"Marius","original":"Elle venait au jardin tous les après-midis","ipa":"/ɛl vənɛt o ʒaʁdɛ̃ tu lez apʁɛmidi/","zh":"她每天下午都会来花园。","en":"She came to the garden every afternoon","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-13-012","lineIndex":12,"speaker":"Marius","original":"Le temps d'une ou deux heures illuminait ma vie sans bonheur","ipa":"/lə tɑ̃ dyn u døz œʁz ilyminɛ ma vi sɑ̃ bɔnœʁ/","zh":"那一两个小时，照亮了我原本无望的人生。","en":"The time of one or two hours illuminated my life without happiness","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-13-013","lineIndex":13,"speaker":"Marius","original":"Mais elle a disparu, mon courage avec elle","ipa":"/mɛz ɛl a dispaʁy mɔ̃ kuʁaʒ avɛk ɛl/","zh":"可她消失了，我的勇气也随她而去。","en":"But she vanished, and my courage vanished with her.","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-13-014","lineIndex":14,"speaker":"Marius","original":"Je n'ai jamais rien su, je ne sais plus rien d'elle","ipa":"/ʒə ne ʒamɛ ʁjɛ̃ sy ʒə nə sɛ ply ʁjɛ̃ dɛl/","zh":"我从未了解过她，如今更一无所知。","en":"I never knew anything of her; now I know even less.","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-13-015","lineIndex":15,"speaker":"Marius","original":"Et plus quoi faire de moi que mourir au combat","ipa":"/e ply kwa fɛʁ də mwa kə muʁiʁ o kɔ̃ba/","zh":"除了战死沙场，我已不知该拿自己怎么办。","en":"And what else can I do with myself than die in combat","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-13-016","lineIndex":16,"speaker":"Marius","original":"Rouge, le peuple est en colère","ipa":"/ʁuʒ lə pøpl ɛt ɑ̃ kolɛʁ/","zh":"红色，是愤怒的人民；","en":"the people are angry.","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-13-017","lineIndex":17,"speaker":"Marius","original":"Noir, mon cœur est en misère","ipa":"/nwaʁ mɔ̃ kœʁ ɛt ɑ̃ mizɛʁ/","zh":"黑色，我的心陷在苦难里。","en":"my heart is in misery.","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-13-018","lineIndex":18,"speaker":"Marius","original":"Rouge, mon sang tourne à l'envers","ipa":"/ʁuʒ mɔ̃ sɑ̃ tuʁn a lɑ̃vɛʁ/","zh":"红色，我的血在倒流；","en":"my blood runs backwards.","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-13-019","lineIndex":19,"speaker":"Marius","original":"Noir, mon amour désespoir","ipa":"/nwaʁ mɔ̃n amuʁ dezɛspwaʁ/","zh":"黑色，我绝望的爱。","en":"Black, my despairing love","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-13-020","lineIndex":20,"speaker":"Combeferre","original":"Allons, Marius, tu exagères","ipa":"/alɔ̃ maʁjys ty ɛɡzaʒɛʁ/","zh":"来吧，马吕斯，你太夸张了","en":"Come on, Marius, you are exaggerating","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-13-021","lineIndex":21,"speaker":"Combeferre","original":"L'amour fait souvent des manières","ipa":"/lamuʁ fɛ suvɑ̃ de manjɛʁ/","zh":"爱情总爱故弄玄虚","en":"Love often gets in the way","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-13-022","lineIndex":22,"speaker":"Combeferre","original":"Mais il ne t'abandonnera pas","ipa":"/mɛz il nə tabɑ̃dɔnʁa pa/","zh":"但它不会抛弃你","en":"But it will not abandon you","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-13-023","lineIndex":23,"speaker":"Combeferre","original":"Il sait bien que tu es sincère","ipa":"/il sɛ bjɛ̃ kə ty ɛ sɛ̃sɛʁ/","zh":"它很清楚你是真心的","en":"He knows well that you are sincere","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-13-024","lineIndex":24,"speaker":"Combeferre","original":"Il exaucera ta prière","ipa":"/il ɛɡzosʁa ta pʁiɛʁ/","zh":"他会回应你的祈祷","en":"He will hear your prayer","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-13-025","lineIndex":25,"speaker":"Combeferre","original":"Et demain tu la retrouveras","ipa":"/e dəmɛ̃ ty la ʁətʁuvʁa/","zh":"明天你就会找到她","en":"And tomorrow you will find her","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-13-026","lineIndex":26,"speaker":"Marius","original":"Rouge, mon sang tourne à l'envers","ipa":"/ʁuʒ mɔ̃ sɑ̃ tuʁn a lɑ̃vɛʁ/","zh":"红色，我的血在倒流；","en":"my blood runs backwards.","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-13-027","lineIndex":27,"speaker":"Marius","original":"Noir, mon cœur est en misère","ipa":"/nwaʁ mɔ̃ kœʁ ɛt ɑ̃ mizɛʁ/","zh":"黑色，我的心陷在苦难里。","en":"my heart is in misery.","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-13-028","lineIndex":28,"speaker":"Tous","original":"Rouge, le peuple est en colère","ipa":"/ʁuʒ lə pøpl ɛt ɑ̃ kolɛʁ/","zh":"红色，是愤怒的人民；","en":"the people are angry.","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-13-029","lineIndex":29,"speaker":"Tous","original":"Noire, l'espérance de la terre","ipa":"/nwaʁ lɛspeʁɑ̃s də la tɛʁ/","zh":"黑色，是大地的希望。","en":"the earth's hope.","note":"","sourceLineIndex":29}],"sourceOrder":13,"displayOrder":13},{"order":14,"id":"14-les-amis-de-l-abc","title":"Les Amis de l'ABC","titleZh":"ABC 之友","lines":[{"id":"les-miserables-1980-14-001","lineIndex":1,"speaker":"Enjolras","original":"Six heures, c'est l'heure, parfait, tout le monde est là","ipa":"/siz œʁ sɛ lœʁ paʁfɛ tulmɔ̃d ɛ la/","zh":"六点了，时间到了，完美，大家都在这里","en":"Six o'clock, it's time, perfect, everyone is here","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-14-002","lineIndex":2,"speaker":"Enjolras","original":"Des chaises, du vin, des verres, écoutez-moi","ipa":"/de ʃɛz dy vɛ̃ de vɛʁ ekutemwa/","zh":"椅子，酒，杯子，听我说","en":"Chairs, wine, glasses, listen to me","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-14-003","lineIndex":3,"speaker":"Enjolras","original":"Que personne ne nous dérange","ipa":"/kə pɛʁsɔn nə nu deʁɑ̃ʒ/","zh":"没人打扰我们","en":"Let no one disturb us","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-14-004","lineIndex":4,"speaker":"Enjolras","original":"Chacun parle à tour de rôle","ipa":"/ʃakœ̃ paʁl a tuʁ də ʁol/","zh":"大家轮流发言","en":"Everyone speaks in turn","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-14-005","lineIndex":5,"speaker":"Enjolras","original":"Tu reviens du Pont au Change","ipa":"/ty ʁəvjɛ̃ dy pɔ̃t o ʃɑ̃ʒ/","zh":"你刚从交易桥回来","en":"You are back from the Pont au Change","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-14-006","lineIndex":6,"speaker":"Enjolras","original":"Courfeyrac, tu as la parole","ipa":"/kuʁfɛʁak ty a la paʁɔl/","zh":"古费拉克，请发言","en":"Courfeyrac, you have the floor","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-14-007","lineIndex":7,"speaker":"Courfeyrac","original":"Au Pont au Change, toutes les sections sont prêtes","ipa":"/o pɔ̃t o ʃɑ̃ʒ tut le sɛksjɔ̃ sɔ̃ pʁɛt/","zh":"交易桥那边，各个小组都准备好了。","en":"At the Pont au Change, every section is ready.","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-14-008","lineIndex":8,"speaker":"Courfeyrac","original":"Grantaire attend à la barrière du Maine","ipa":"/ɡʁɑ̃tɛʁ atɑ̃t a la baʁjɛʁ dy mɛn/","zh":"格朗泰尔在曼恩关卡等着。","en":"Grantaire is waiting at the Barrière du Maine.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-14-009","lineIndex":9,"speaker":"Courfeyrac","original":"Les sculpteurs, les marbriers","ipa":"/le skyltœʁ le maʁbʁie/","zh":"雕塑家、大理石工人","en":"The sculptors, the marble workers","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-14-010","lineIndex":10,"speaker":"Courfeyrac","original":"Tardent à se joindre à nous","ipa":"/taʁdt a sə ʒwɛ̃dʁ a nu/","zh":"迟迟没有加入我们","en":"Late to join us","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-14-011","lineIndex":11,"speaker":"Courfeyrac","original":"Mais les maçons de Montreuil","ipa":"/mɛ le masɔ̃ də mɔ̃tʁœj/","zh":"但蒙特勒伊的泥瓦匠","en":"But the masons of Montreuil","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-14-012","lineIndex":12,"speaker":"Courfeyrac","original":"Seront tous au rendez-vous","ipa":"/səʁɔ̃ tus o ʁɑ̃devu/","zh":"都会在那里","en":"All will be there","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-14-013","lineIndex":13,"speaker":"Enjolras","original":"Lamarque est mort","ipa":"/lamaʁk ɛ mɔʁ/","zh":"拉马克死了","en":"Lamarque is dead","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-14-014","lineIndex":14,"speaker":"Enjolras","original":"Demain, nous irons le rendre à la terre","ipa":"/dəmɛ̃ nuz iʁɔ̃ lə ʁɑ̃dʁ a la tɛʁ/","zh":"明天，我们将送他入土。","en":"Tomorrow, we will return him to the earth.","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-14-015","lineIndex":15,"speaker":"Enjolras","original":"La terre patrie","ipa":"/la tɛʁ patʁi/","zh":"祖国","en":"The homeland","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-14-016","lineIndex":16,"speaker":"Enjolras","original":"Sans lui, n'est qu'un cimetière","ipa":"/sɑ̃ lɥi nɛ kœ̃ simtjɛʁ/","zh":"没有他，只是一座墓地","en":"Without him, it is only a cemetery","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-14-017","lineIndex":17,"speaker":"Courfeyrac","original":"C'était un fils du peuple, un très grand général","ipa":"/setɛt œ̃ fis dy pøpl œ̃ tʁɛ ɡʁɑ̃ ʒeneʁal/","zh":"他是人民的儿子，一位非常伟大的将军","en":"He was a son of the people, a very great general","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-14-018","lineIndex":18,"speaker":"Courfeyrac","original":"L'empereur admirait sa bravoure au combat","ipa":"/lɑ̃pʁœʁ admiʁɛ sa bʁavuʁ o kɔ̃ba/","zh":"皇帝钦佩他在战斗中的英勇","en":"The emperor admired his bravery in battle","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-14-019","lineIndex":19,"speaker":"Feuilly","original":"Il nous faut mériter de servir son idéal","ipa":"/il nu fo meʁite də sɛʁviʁ sɔ̃n ideal/","zh":"我们必须为他的理想服务","en":"We must deserve to serve his ideal","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-14-020","lineIndex":20,"speaker":"Feuilly","original":"Son cœur vibrait à gauche et il le proclama","ipa":"/sɔ̃ kœʁ vibʁɛt a ɡoʃ e il lə pʁɔklama/","zh":"他的心向着左翼，并且公开宣告过。","en":"His heart beat on the left, and he proclaimed it.","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-14-021","lineIndex":21,"speaker":"Enjolras","original":"Il n'est pas mort","ipa":"/il nɛ pa mɔʁ/","zh":"他没有死","en":"He is not dead","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-14-022","lineIndex":22,"speaker":"Enjolras","original":"Lamarque ressuscité à chaque homme tombé","ipa":"/lamaʁk ʁesysite a ʃak ɔm tɔ̃be/","zh":"每倒下一人，拉马克便在他身上复生","en":"Lamarque is reborn in every fallen man;","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-14-023","lineIndex":23,"speaker":"Enjolras","original":"Est le drapeau vivant de ceux qui n'en ont pas","ipa":"/ɛ lə dʁapo vivɑ̃ də sø ki nɑ̃n ɔ̃ pa/","zh":"成为那些没有旗帜者的活旗。","en":"he is the living flag of those who have none.","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-14-024","lineIndex":24,"speaker":"Enjolras","original":"La liberté en deuil affronte l'autorité","ipa":"/la libɛʁte ɑ̃ dœj afʁɔ̃t lotoʁite/","zh":"哀悼中的自由对抗权威","en":"Freedom in mourning confronts authority","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-14-025","lineIndex":25,"speaker":"Enjolras","original":"Dans les rues de Paris, où nous régnons déjà","ipa":"/dɑ̃ le ʁy də paʁi u nu ʁenjɔ̃ deʒa/","zh":"在我们已经统治的巴黎街头","en":"In the streets of Paris, where we already reign","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-14-026","lineIndex":26,"speaker":"Feuilly","original":"Des hommes, des femmes au faubourg St Antoine","ipa":"/dez ɔm de famz o fobuʁ sɛ̃t ɑ̃twan/","zh":"圣安托万郊区的男男女女","en":"Men, women in the Faubourg St Antoine","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-14-027","lineIndex":27,"speaker":"Feuilly","original":"Ont fait des armes d'un rabot, d'un compas","ipa":"/ɔ̃ fɛ dez aʁm dœ̃ ʁabo dœ̃ kɔ̃pa/","zh":"用刨子和圆规改造成武器。","en":"have made weapons from a plane and a compass.","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-14-028","lineIndex":28,"speaker":"Feuilly","original":"À la barrière de Montreuil","ipa":"/a la baʁjɛʁ də mɔ̃tʁœj/","zh":"在蒙特勒伊屏障","en":"At the Montreuil barrier","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-14-029","lineIndex":29,"speaker":"Feuilly","original":"L'armurier est avec nous","ipa":"/laʁmyʁje ɛ avɛk nu/","zh":"军械师和我们在一起","en":"The gunsmith is with us","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-14-030","lineIndex":30,"speaker":"Feuilly","original":"Il distribue des cartouches","ipa":"/il distʁiby de kaʁtuʃ/","zh":"他分发子弹","en":"He distributes cartridges","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-14-031","lineIndex":31,"speaker":"Feuilly","original":"Et des fusils à deux coups","ipa":"/e de fyziz a dø ku/","zh":"和双发步枪","en":"And double-shot rifles","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-14-032","lineIndex":32,"speaker":"Enjolras","original":"La garde observe","ipa":"/la ɡaʁd ɔbsɛʁv/","zh":"警卫观察","en":"The guard observes","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-14-033","lineIndex":33,"speaker":"Enjolras","original":"Et elle se garde bien d'intervenir","ipa":"/e ɛl sə ɡaʁd bjɛ̃ dɛ̃tɛʁvəniʁ/","zh":"却刻意按兵不动","en":"And she is careful not to intervene","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-14-034","lineIndex":34,"speaker":"Enjolras","original":"Jusqu'à demain","ipa":"/ʒyska dəmɛ̃/","zh":"直到明天","en":"Until tomorrow","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-14-035","lineIndex":35,"speaker":"Enjolras","original":"Afin de provoquer le pire","ipa":"/afɛ̃ də pʁovoke lə piʁ/","zh":"好把局势推向最坏。","en":"In order to provoke the worst","note":"","sourceLineIndex":35},{"id":"les-miserables-1980-14-036","lineIndex":36,"speaker":"Courfeyrac","original":"Tout le 6ème dragon prend place aux Célestins","ipa":"/tu lə siz jɛm dʁaɡɔ̃ pʁɑ̃ plas o selɛstɛ̃/","zh":"第六龙骑兵团已驻扎在塞莱斯坦","en":"The whole 6th Dragoons are positioned at the Célestins","note":"","sourceLineIndex":36},{"id":"les-miserables-1980-14-037","lineIndex":37,"speaker":"Courfeyrac","original":"Et le 12ème léger a été consigné","ipa":"/e lə duz jɛm leʒe a ete kɔ̃sinje/","zh":"第十二轻骑兵团也已被限制行动。","en":"and the 12th Light Infantry has been confined to barracks.","note":"","sourceLineIndex":37},{"id":"les-miserables-1980-14-038","lineIndex":38,"speaker":"Courfeyrac","original":"Plus de 30.000 soldats sont massés à Pantin","ipa":"/ply də tʁɑ̃t mil sɔlda sɔ̃ masez a pɑ̃tɛ̃/","zh":"超过三万名士兵集结在庞坦","en":"More than 30, 000 soldiers are massed in Pantin","note":"","sourceLineIndex":38},{"id":"les-miserables-1980-14-039","lineIndex":39,"speaker":"Marius","original":"Prêts à tuer leurs frères pour un morceau de pain","ipa":"/pʁɛz a tye lœʁ fʁɛʁ puʁ œ̃ mɔʁso də pɛ̃/","zh":"准备为一块面包杀死自己的兄弟。","en":"Ready to kill their brothers for a piece of bread","note":"","sourceLineIndex":39},{"id":"les-miserables-1980-14-040","lineIndex":40,"speaker":"Enjolras","original":"C'est pour demain","ipa":"/sɛ puʁ dəmɛ̃/","zh":"这是为了明天","en":"It's for tomorrow","note":"","sourceLineIndex":40},{"id":"les-miserables-1980-14-041","lineIndex":41,"speaker":"Enjolras","original":"Préparons-nous à tout puisque nous n'avons rien","ipa":"/pʁepaʁɔ̃nuz a tu pɥiskə nu navɔ̃ ʁjɛ̃/","zh":"让我们做好一切准备，因为我们一无所有","en":"Let's prepare for everything since we have nothing","note":"","sourceLineIndex":41},{"id":"les-miserables-1980-14-042","lineIndex":42,"speaker":"Enjolras","original":"Et le tout pour le tout","ipa":"/e lə tu puʁ lə tu/","zh":"总而言之","en":"And all in all","note":"","sourceLineIndex":42}],"sourceOrder":14,"displayOrder":14},{"order":15,"id":"15-a-la-volonte-du-peuple","title":"À la Volonté du Peuple","titleZh":"为了人民的意愿","lines":[{"id":"les-miserables-1980-15-001","lineIndex":1,"speaker":"Enjolras","original":"A la volonté du peuple","ipa":"/a la volɔ̃te dy pøpl/","zh":"为了人民的意志","en":"To the will of the people","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-15-002","lineIndex":2,"speaker":"Enjolras","original":"Et à la santé du progrès","ipa":"/e a la sɑ̃te dy pʁɔɡʁɛ/","zh":"为了进步，干杯！","en":"and to the health of progress!","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-15-003","lineIndex":3,"speaker":"Enjolras","original":"Remplis ton cœur d'un vin rebelle","ipa":"/ʁɑ̃pli tɔ̃ kœʁ dœ̃ vɛ̃ ʁəbɛl/","zh":"让反抗的酒注满你的心","en":"Fill your heart with rebellious wine","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-15-004","lineIndex":4,"speaker":"Enjolras","original":"Et à demain, ami fidèle","ipa":"/e a dəmɛ̃ ami fidɛl/","zh":"明天见，忠诚的朋友。","en":"and until tomorrow, faithful friend.","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-15-005","lineIndex":5,"speaker":"Enjolras","original":"Nous voulons faire la lumière","ipa":"/nu vulɔ̃ fɛʁ la lymjɛʁ/","zh":"我们要点亮光明","en":"We want to make light","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-15-006","lineIndex":6,"speaker":"Enjolras","original":"Malgré le masque de la nuit","ipa":"/malɡʁe lə mask də la nɥi/","zh":"穿透夜的面具","en":"despite the mask of night","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-15-007","lineIndex":7,"speaker":"Enjolras","original":"Pour illuminer notre terre","ipa":"/puʁ ilymine notʁ tɛʁ/","zh":"照亮我们的土地","en":"to illuminate our land","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-15-008","lineIndex":8,"speaker":"Enjolras","original":"Et changer la vie","ipa":"/e ʃɑ̃ʒe la vi/","zh":"改变生活。","en":"and change life.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-15-009","lineIndex":9,"speaker":"Enjolras","original":"Il faut gagner à la guerre","ipa":"/il fo ɡanje a la ɡɛʁ/","zh":"我们必须赢得战争","en":"We must win in war","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-15-010","lineIndex":10,"speaker":"Enjolras","original":"Notre sillon à labourer","ipa":"/notʁ sijɔ̃ a labuʁe/","zh":"去耕耘属于我们的沟垄","en":"Our furrow is there to plough;","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-15-011","lineIndex":11,"speaker":"Enjolras","original":"Déblayer la misère","ipa":"/deblɛje la mizɛʁ/","zh":"清除苦难","en":"clear away misery","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-15-012","lineIndex":12,"speaker":"Enjolras","original":"Pour les blonds épis de la paix","ipa":"/puʁ le blɔ̃z epi də la pɛ/","zh":"好让和平金黄的麦穗","en":"for the golden ears of peace","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-15-013","lineIndex":13,"speaker":"Enjolras","original":"Qui danseront de joie","ipa":"/ki dɑ̃sʁɔ̃ də ʒwa/","zh":"欢喜地摇曳","en":"to dance with joy","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-15-014","lineIndex":14,"speaker":"Enjolras","original":"Au grand vent de la liberté","ipa":"/o ɡʁɑ̃ vɑ̃ də la libɛʁte/","zh":"在自由的大风中","en":"In the great wind of freedom","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-15-015","lineIndex":15,"speaker":"Enjolras","original":"A la volonté du peuple","ipa":"/a la volɔ̃te dy pøpl/","zh":"为了人民的意志","en":"To the will of the people","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-15-016","lineIndex":16,"speaker":"Enjolras","original":"Et à la santé du progrès","ipa":"/e a la sɑ̃te dy pʁɔɡʁɛ/","zh":"为了进步，干杯！","en":"and to the health of progress!","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-15-017","lineIndex":17,"speaker":"Enjolras","original":"Remplis ton cœur d'un vin rebelle","ipa":"/ʁɑ̃pli tɔ̃ kœʁ dœ̃ vɛ̃ ʁəbɛl/","zh":"让反抗的酒注满你的心","en":"Fill your heart with rebellious wine","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-15-018","lineIndex":18,"speaker":"Enjolras","original":"Et à demain, ami fidèle","ipa":"/e a dəmɛ̃ ami fidɛl/","zh":"明天见，忠诚的朋友。","en":"and until tomorrow, faithful friend.","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-15-019","lineIndex":19,"speaker":"Enjolras","original":"Nous voulons faire la lumière","ipa":"/nu vulɔ̃ fɛʁ la lymjɛʁ/","zh":"我们要点亮光明","en":"We want to shed light","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-15-020","lineIndex":20,"speaker":"Enjolras","original":"Malgré le masque de la nuit","ipa":"/malɡʁe lə mask də la nɥi/","zh":"穿透夜的面具","en":"Despite the mask of the night","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-15-021","lineIndex":21,"speaker":"Enjolras","original":"Pour illuminer notre terre","ipa":"/puʁ ilymine notʁ tɛʁ/","zh":"照亮我们的土地","en":"To illuminate our earth","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-15-022","lineIndex":22,"speaker":"Enjolras","original":"Et changer la vie","ipa":"/e ʃɑ̃ʒe la vi/","zh":"改变生活。","en":"And change life","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-15-023","lineIndex":23,"speaker":"Enjolras","original":"A la volonté du peuple","ipa":"/a la volɔ̃te dy pøpl/","zh":"为了人民的意志","en":"To the will of the people","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-15-024","lineIndex":24,"speaker":"Enjolras","original":"Je fais don de ma volonté","ipa":"/ʒə fɛ dɔ̃ də ma volɔ̃te/","zh":"我将自己的意志献出去","en":"I give my own will","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-15-025","lineIndex":25,"speaker":"Enjolras","original":"S'il faut mourir pour elle","ipa":"/sil fo muʁiʁ puʁ ɛl/","zh":"若必须为它而死","en":"if I must die for it","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-15-026","lineIndex":26,"speaker":"Enjolras","original":"Moi je veux être le premier","ipa":"/mwa ʒə vøz ɛtʁ lə pʁəmje/","zh":"我愿做第一个。","en":"I want to be the first","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-15-027","lineIndex":27,"speaker":"Enjolras","original":"Le premier nom gravé","ipa":"/lə pʁəmje nɔ̃ ɡʁave/","zh":"第一个被刻下的名字","en":"the first name engraved","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-15-028","lineIndex":28,"speaker":"Enjolras","original":"Au marbre du monument d'espoir","ipa":"/o maʁbʁ dy monymɑ̃ dɛspwaʁ/","zh":"在希望纪念碑的大理石上","en":"At the marble of the monument of hope","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-15-029","lineIndex":29,"speaker":"Enjolras","original":"A la volonté du peuple","ipa":"/a la volɔ̃te dy pøpl/","zh":"为了人民的意志","en":"To the will of the people","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-15-030","lineIndex":30,"speaker":"Enjolras","original":"Et à la santé du progrès","ipa":"/e a la sɑ̃te dy pʁɔɡʁɛ/","zh":"为了进步，干杯！","en":"and to the health of progress!","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-15-031","lineIndex":31,"speaker":"Enjolras","original":"Remplis ton cœur d'un vin rebelle","ipa":"/ʁɑ̃pli tɔ̃ kœʁ dœ̃ vɛ̃ ʁəbɛl/","zh":"让反抗的酒注满你的心","en":"Fill your heart with rebellious wine","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-15-032","lineIndex":32,"speaker":"Enjolras","original":"Et à demain, ami fidèle","ipa":"/e a dəmɛ̃ ami fidɛl/","zh":"明天见，忠诚的朋友。","en":"and until tomorrow, faithful friend.","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-15-033","lineIndex":33,"speaker":"Enjolras","original":"Nous voulons faire la lumière","ipa":"/nu vulɔ̃ fɛʁ la lymjɛʁ/","zh":"我们要点亮光明","en":"We want to shed light","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-15-034","lineIndex":34,"speaker":"Enjolras","original":"Malgré le masque de la nuit","ipa":"/malɡʁe lə mask də la nɥi/","zh":"穿透夜的面具","en":"Despite the mask of the night","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-15-035","lineIndex":35,"speaker":"Enjolras","original":"Pour illuminer notre terre","ipa":"/puʁ ilymine notʁ tɛʁ/","zh":"照亮我们的土地","en":"To illuminate our earth","note":"","sourceLineIndex":35},{"id":"les-miserables-1980-15-036","lineIndex":36,"speaker":"Enjolras","original":"Et changer la vie","ipa":"/e ʃɑ̃ʒe la vi/","zh":"改变生活。","en":"And change life","note":"","sourceLineIndex":36}],"sourceOrder":15,"displayOrder":15},{"order":16,"id":"16-cosette-dans-la-vie","title":"Cosette: Dans la Vie","titleZh":"珂赛特：生活中","lines":[{"id":"les-miserables-1980-16-001","lineIndex":1,"speaker":"Cosette","original":"Dans la vie, il ne me manque rien","ipa":"/dɑ̃ la vi il nə mə mɑ̃k ʁiɛ̃/","zh":"生活里我什么都不缺","en":"In life, I lack nothing","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-16-002","lineIndex":2,"speaker":"Cosette","original":"Mais il manque quelqu'un de mon âge","ipa":"/mɛz il mɑ̃k kɛlkœ̃ də mɔ̃n aʒ/","zh":"却少了一个和我同龄的人。","en":"but someone my own age is missing.","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-16-003","lineIndex":3,"speaker":"Cosette","original":"Est-il loin, encore loin","ipa":"/ɛtil lwɛ̃ ɑ̃kɔʁ lwɛ̃/","zh":"他还远吗？仍然很远吗？","en":"Is he far—still far away","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-16-004","lineIndex":4,"speaker":"Cosette","original":"Le beau prince en chemin","ipa":"/lə bo pʁɛ̃s ɑ̃ ʃəmɛ̃/","zh":"我在路上的俊美王子","en":"my handsome prince on his way","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-16-005","lineIndex":5,"speaker":"Cosette","original":"De mon rêve enfantin, dans sa cage?","ipa":"/də mɔ̃ ʁɛv ɑ̃fɑ̃tɛ̃ dɑ̃ sa kaʒ/","zh":"他还困在我童年梦境的笼中吗？","en":"still caged inside my childhood dream?","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-16-006","lineIndex":6,"speaker":"Valjean","original":"Mon enfant, et moi qui te crois une enfant","ipa":"/mɔ̃n ɑ̃fɑ̃ e mwa ki tə kʁwaz yn ɑ̃fɑ̃/","zh":"我的孩子，而我还把你当作孩子。","en":"My child—and I still think of you as a child.","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-16-007","lineIndex":7,"speaker":"Valjean","original":"Il n'est pas de beau prince charmant sur cette terre","ipa":"/il nɛ pa də bo pʁɛ̃s ʃaʁmɑ̃ syʁ sɛt tɛʁ/","zh":"这世上没有什么俊美的白马王子。","en":"There is no handsome Prince Charming on this earth.","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-16-008","lineIndex":8,"speaker":"Cosette","original":"Mais vous avez été le prince de mon enfance","ipa":"/mɛ vuz avez ete lə pʁɛ̃s də mɔ̃n ɑ̃fɑ̃s/","zh":"但你是我童年的王子","en":"But you were the prince of my childhood","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-16-009","lineIndex":9,"speaker":"Cosette","original":"Un autre doit venir pour mon adolescence","ipa":"/œ̃n otʁ dwa vəniʁ puʁ mɔ̃n adolɛsɑ̃s/","zh":"可我的青春，得有另一位王子来到身边。","en":"Another must come for my adolescence.","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-16-010","lineIndex":10,"speaker":"Cosette","original":"Dans ma vie, ni chagrin, ni douleur","ipa":"/dɑ̃ ma vi ni ʃaɡʁɛ̃ ni dulœʁ/","zh":"我的生命里没有悲伤也没有痛苦","en":"In my life, neither sorrow nor pain","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-16-011","lineIndex":11,"speaker":"Cosette","original":"Mais je n'ai pas le cœur au bonheur","ipa":"/mɛ ʒə ne pa lə kœʁ o bɔnœʁ/","zh":"可我的心还无意享受幸福。","en":"But I don't have the heart for happiness","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-16-012","lineIndex":12,"speaker":"Cosette","original":"Pas le cœur au bonheur","ipa":"/pa lə kœʁ o bɔnœʁ/","zh":"还无意享受幸福。","en":"Not the heart for happiness","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-16-013","lineIndex":13,"speaker":"Valjean","original":"Le bonheur, c'est un cadeau de Dieu","ipa":"/lə bɔnœʁ sɛt œ̃ kado də djø/","zh":"幸福是上帝赐予的礼物","en":"Happiness is a gift from God","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-16-014","lineIndex":14,"speaker":"Valjean","original":"À chacun, à son heure","ipa":"/a ʃakœ̃ a sɔ̃n œʁ/","zh":"每个人都会在自己的时刻得到它。","en":"To each one, in their own time","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-16-015","lineIndex":15,"speaker":"Valjean","original":"À son heure","ipa":"/a sɔ̃n œʁ/","zh":"在属于自己的时刻。","en":"In their own time","note":"","sourceLineIndex":15}],"sourceOrder":16,"displayOrder":16},{"order":17,"id":"17-marius-dans-la-vie","title":"Marius: Dans la Vie","titleZh":"马吕斯：生活中","lines":[{"id":"les-miserables-1980-17-001","lineIndex":1,"speaker":"Marius","original":"Dans la vie, si je manque de tout","ipa":"/dɑ̃ la vi si ʒə mɑ̃k də tu/","zh":"人生里，即使我一无所有","en":"In life, if I lack of everything","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-17-002","lineIndex":2,"speaker":"Marius","original":"Il ne me manque rien devant elle","ipa":"/il nə mə mɑ̃k ʁiɛ̃ dəvɑ̃ ɛl/","zh":"只要在她面前，我便别无所缺。","en":"I lack nothing in front of her","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-17-003","lineIndex":3,"speaker":"Marius","original":"Elle est là, près de moi","ipa":"/ɛl ɛ la pʁɛ də mwa/","zh":"她就在那里，离我很近","en":"She is there, close to me","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-17-004","lineIndex":4,"speaker":"Marius","original":"Ma princesse au jardin","ipa":"/ma pʁɛ̃sɛs o ʒaʁdɛ̃/","zh":"我花园里的公主","en":"My princess in the garden","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-17-005","lineIndex":5,"speaker":"Marius","original":"Une rose à la main, irréelle","ipa":"/yn ʁɔz a la mɛ̃ iʁeɛl/","zh":"手持一朵玫瑰，如梦似幻。","en":"A rose in my hand, unreal","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-17-006","lineIndex":6,"speaker":"Marius","original":"Je croyais l'avoir perdue à tout jamais","ipa":"/ʒə kʁwajɛ lavwaʁ pɛʁdy a tu ʒamɛ/","zh":"我以为我永远失去了她","en":"I thought I had lost her forever","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-17-007","lineIndex":7,"speaker":"Marius","original":"Et voilà qu'Éponine se transforme en bonne fée!","ipa":"/e vwala keponin sə tʁɑ̃sfɔʁm ɑ̃ bɔn fe/","zh":"看哪，艾潘妮竟成了善良的仙女！","en":"And now Éponine transforms into a good fairy!","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-17-008","lineIndex":8,"speaker":"Marius","original":"Le bon Dieu, quelquefois, est un grand magicien","ipa":"/lə bɔ̃ djø kɛlkəfwa ɛt œ̃ ɡʁɑ̃ maʒisjɛ̃/","zh":"仁慈的上帝有时也是一位伟大的魔术师。","en":"The good Lord, sometimes, is a great magician","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-17-009","lineIndex":9,"speaker":"Marius","original":"Père Noël égaré venant au mois de juin","ipa":"/pɛʁ nɔɛl eɡaʁe vənɑ̃ o mwa də ʒyɛ̃/","zh":"像一位六月才迷路赶来的圣诞老人。","en":"Lost Santa Claus coming in June","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-17-010","lineIndex":10,"speaker":"Marius","original":"Et la vie soudain en un éclair","ipa":"/e la vi sudɛ̃ ɑ̃n œ̃n eklɛʁ/","zh":"生命忽然在一瞬之间","en":"And life suddenly in a flash","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-17-011","lineIndex":11,"speaker":"Marius","original":"Me cravache le cœur quand la mort","ipa":"/mə kʁavaʃ lə kœʁ kɑ̃ la mɔʁ/","zh":"狠狠抽打我的心—而死亡","en":"Wracks my heart when death","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-17-012","lineIndex":12,"speaker":"Marius","original":"M'habitait, hier encore","ipa":"/mabitɛ jɛʁ ɑ̃kɔʁ/","zh":"昨天还住在我的心里。","en":"Inhabited me, just yesterday","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-17-013","lineIndex":13,"speaker":"Éponine","original":"Le bonheur fait le pauvre plus riche","ipa":"/lə bɔnœʁ fɛ lə povʁ ply ʁiʃ/","zh":"幸福让穷人变得更富有","en":"Happiness makes the poor richer","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-17-014","lineIndex":14,"speaker":"Éponine","original":"Et fait le riche meilleur","ipa":"/e fɛ lə ʁiʃ mɛjœʁ/","zh":"让富人变得更好","en":"And do the rich better","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-17-015","lineIndex":15,"speaker":"Éponine","original":"Meilleur","ipa":"/mɛjœʁ/","zh":"更好","en":"Best","note":"","sourceLineIndex":15}],"sourceOrder":17,"displayOrder":17},{"order":18,"id":"18-voila-le-soir-qui-tombe","title":"Voilà le Soir qui tombe","titleZh":"夜晚来了","lines":[{"id":"les-miserables-1980-18-001","lineIndex":1,"speaker":"Éponine","original":"Voilà, le soir qui tombe","ipa":"/vwala lə swaʁ ki tɔ̃b/","zh":"夜幕降临","en":"There, the evening falls","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-18-002","lineIndex":2,"speaker":"Éponine","original":"Hélas, trêve de rêve","ipa":"/elas tʁɛv də ʁɛv/","zh":"唉，梦该停一停了。","en":"Alas, dream truce","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-18-003","lineIndex":3,"speaker":"Éponine","original":"Ils vont venir en nombre","ipa":"/il vɔ̃ vəniʁ ɑ̃ nɔ̃bʁ/","zh":"他们会成群结队地到来","en":"They will come in numbers","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-18-004","lineIndex":4,"speaker":"Éponine","original":"L'attaque est pour cette nuit","ipa":"/latak ɛ puʁ sɛt nɥi/","zh":"今晚他们就要动手。","en":"The attack is for this night","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-18-005","lineIndex":5,"speaker":"Éponine","original":"C'est l'autre jour comme ça par hasard","ipa":"/sɛ lotʁ ʒuʁ kɔm sa paʁ azaʁ/","zh":"前几天偶然间","en":"It was the other day just like that by chance","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-18-006","lineIndex":6,"speaker":"Éponine","original":"Que j'ai retrouvé sa trace","ipa":"/kə ʒe ʁətʁuve sa tʁas/","zh":"我找到了她的踪迹。","en":"That I found his trace","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-18-007","lineIndex":7,"speaker":"Éponine","original":"En faisant le guet devant","ipa":"/ɑ̃ fəzɑ̃ lə ɡɛ dəvɑ̃/","zh":"我替","en":"While keeping watch in front of","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-18-008","lineIndex":8,"speaker":"Éponine","original":"Pour ce coquin de Montparnasse","ipa":"/puʁ sə kokɛ̃ də mɔ̃paʁnas/","zh":"那个叫蒙帕纳斯的混混望风","en":"For this rascal from Montparnasse","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-18-009","lineIndex":9,"speaker":"Éponine","original":"Qu'avait repéré","ipa":"/kavɛ ʁəpeʁe/","zh":"他盯上了","en":"What had","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-18-010","lineIndex":10,"speaker":"Éponine","original":"C'te belle villa déserte, abandonnée","ipa":"/stə bɛl vila dezɛʁt abɑ̃dɔne/","zh":"这座漂亮却空置的别墅","en":"spotted beautiful deserted, abandoned villa","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-18-011","lineIndex":11,"speaker":"Éponine","original":"Et qui voulait que j'vérifie","ipa":"/e ki vulɛ kə ʒveʁifi/","zh":"要我去查清","en":"And who wanted me to check","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-18-012","lineIndex":12,"speaker":"Éponine","original":"Qu'on pouvait la vider en paix","ipa":"/kɔ̃ puvɛ la vide ɑ̃ pɛ/","zh":"能不能安安静静把它洗劫一空。","en":"That we could empty it in peace","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-18-013","lineIndex":13,"speaker":"Éponine","original":"L'endroit n'était pas vide","ipa":"/lɑ̃dʁwa netɛ pa vid/","zh":"这个地方并不空","en":"The place was not empty","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-18-014","lineIndex":14,"speaker":"Éponine","original":"J'ai vu un vieux monsieur","ipa":"/ʒe vy œ̃ vjø məsjø/","zh":"我看到了一位老绅士","en":"I saw an old gentleman","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-18-015","lineIndex":15,"speaker":"Éponine","original":"Le père, le vieux mécène","ipa":"/lə pɛʁ lə vjø mesɛn/","zh":"她父亲，那个年迈的恩人","en":"The father, the old patron","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-18-016","lineIndex":16,"speaker":"Éponine","original":"Avec une jeune fille","ipa":"/avɛk yn ʒøn fij/","zh":"和一个年轻的女孩","en":"With a young girl","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-18-017","lineIndex":17,"speaker":"Éponine","original":"J'ai su tout d'suite que c'est elle","ipa":"/ʒe sy tu dsɥit kə sɛt ɛl/","zh":"我立刻就知道是她","en":"I knew straight away that it was her","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-18-018","lineIndex":18,"speaker":"Éponine","original":"J'ai dit: \"Danger, c'est louche","ipa":"/ʒe di dɑ̃ʒe sɛ luʃ/","zh":"我说：“危险，有蹊跷","en":"I said, “Danger, something's suspicious—","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-18-019","lineIndex":19,"speaker":"Éponine","original":"À c'te villa, pas touche!\"","ipa":"/a stə vila pa tuʃ/","zh":"别碰那栋房子！”","en":"don't touch that house!”","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-18-020","lineIndex":20,"speaker":"Éponine","original":"J'ai voulu protéger l'amour","ipa":"/ʒe vuly pʁoteʒe lamuʁ/","zh":"我想守护爱情","en":"I wanted to protect love","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-18-021","lineIndex":21,"speaker":"Éponine","original":"Sans rien trahir pourtant dans mon discours","ipa":"/sɑ̃ ʁjɛ̃ tʁaiʁ puʁtɑ̃ dɑ̃ mɔ̃ diskuʁ/","zh":"话里却没露出半点。","en":"without giving anything away in what I said.","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-18-022","lineIndex":22,"speaker":"Éponine","original":"Mais je sens qu'ils viendront quand même","ipa":"/mɛ ʒə sɑ̃ kil vjɛ̃dʁɔ̃ kɑ̃ mɛm/","zh":"但我感觉他们还是会来","en":"But I feel that they will come all the same","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-18-023","lineIndex":23,"speaker":"Éponine","original":"Et mon père, s'il s'évade, de même","ipa":"/e mɔ̃ pɛʁ sil sevad də mɛm/","zh":"我父亲若逃脱，也会回来。","en":"And my father, if he gets away, will be the same.","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-18-024","lineIndex":24,"speaker":"Éponine","original":"Courez vite auprès d'elle","ipa":"/kuʁe vit opʁɛ dɛl/","zh":"快跑到她身边","en":"Run quickly to her","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-18-025","lineIndex":25,"speaker":"Éponine","original":"Lui dire que vous l'aimez","ipa":"/lɥi diʁ kə vu lɛme/","zh":"告诉她你爱她。","en":"Tell her that you love her.","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-18-026","lineIndex":26,"speaker":"Éponine","original":"Je reste en sentinelle","ipa":"/ʒə ʁɛst ɑ̃ sɑ̃tinɛl/","zh":"我继续放哨","en":"I remain on sentry","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-18-027","lineIndex":27,"speaker":"Éponine","original":"Chacun sa destinée","ipa":"/ʃakœ̃ sa dɛstine/","zh":"每个人都有自己的命运","en":"Everyone has their own destiny","note":"","sourceLineIndex":27}],"sourceOrder":18,"displayOrder":18},{"order":19,"id":"19-le-c-ur-au-bonheur-cosette-et-marius","title":"Le Cœur au Bonheur (Cosette et Marius)","titleZh":"幸福之心（珂赛特和马吕斯）","lines":[{"id":"les-miserables-1980-19-001","lineIndex":1,"speaker":"Marius","original":"Le cœur au bonheur","ipa":"/lə kœʁ o bɔnœʁ/","zh":"幸福之心","en":"The heart of happiness","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-19-002","lineIndex":2,"speaker":"Marius","original":"J'espère et j'ai peur","ipa":"/ʒɛspɛʁ e ʒe pœʁ/","zh":"我希望也担心","en":"I hope and I fear","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-19-003","lineIndex":3,"speaker":"Marius","original":"Que ces mots fassent mon malheur","ipa":"/kə se mo fas mɔ̃ malœʁ/","zh":"只怕这些话会带来我的不幸","en":"That these words will make me unhappy","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-19-004","lineIndex":4,"speaker":"Marius","original":"Et qu'elle me dise","ipa":"/e kɛl mə diz/","zh":"她会这样对我说。","en":"And that she will tell me","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-19-005","lineIndex":5,"speaker":"Cosette","original":"Je n'connais même pas votre nom","ipa":"/ʒə nkɔnɛ mɛm pa votʁ nɔ̃/","zh":"我什至不知道你的名字","en":"I don't even know your name","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-19-006","lineIndex":6,"speaker":"Marius","original":"Mon dieu, pardon","ipa":"/mɔ̃ djø paʁdɔ̃/","zh":"我的上帝，对不起","en":"My god, sorry","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-19-007","lineIndex":7,"speaker":"Marius","original":"Excusez ma sottise","ipa":"/ɛkskyze ma sɔtiz/","zh":"请原谅我的愚蠢","en":"Excuse my stupidity","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-19-008","lineIndex":8,"speaker":"Cosette","original":"Le cœur au bonheur","ipa":"/lə kœʁ o bɔnœʁ/","zh":"幸福之心","en":"The heart of happiness","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-19-009","lineIndex":9,"speaker":"Cosette","original":"J'attendais un prince","ipa":"/ʒatɑ̃dɛz œ̃ pʁɛ̃s/","zh":"我在等一个王子","en":"I was expecting a prince","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-19-010","lineIndex":10,"speaker":"Marius","original":"Je m'appelle Marius Pontmercy","ipa":"/ʒə mapɛl maʁjys pɔ̃mɛʁsi/","zh":"我的名字是马吕斯·庞特默西","en":"My name is Marius Pontmercy","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-19-011","lineIndex":11,"speaker":"Cosette","original":"Et moi, Cosette","ipa":"/e mwa kozɛt/","zh":"而我，珂赛特","en":"And I, Cosette","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-19-012","lineIndex":12,"speaker":"Marius","original":"Je vous ai vue au Luxembourg","ipa":"/ʒə vuz e vy o lyksɑ̃buʁ/","zh":"我在卢森堡见到了你","en":"I saw you in Luxembourg","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-19-013","lineIndex":13,"speaker":"Cosette","original":"Prince d'amour","ipa":"/pʁɛ̃s damuʁ/","zh":"爱情王子","en":"Prince of love","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-19-014","lineIndex":14,"speaker":"Ensemble","original":"Te voilà, comme en rêve","ipa":"/tə vwala kɔm ɑ̃ ʁɛv/","zh":"你在这里，就像在梦中","en":"Here you are, as in a dream","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-19-015","lineIndex":15,"speaker":"Ensemble","original":"Les anges, quelquefois","ipa":"/lez ɑ̃ʒ kɛlkəfwa/","zh":"天使，有时","en":"Angels, sometimes","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-19-016","lineIndex":16,"speaker":"Ensemble","original":"Se rencontrent sur terre","ipa":"/sə ʁɑ̃kɔ̃tʁ syʁ tɛʁ/","zh":"也会在人世相逢。","en":"Meet on earth","note":"","sourceLineIndex":16}],"sourceOrder":19,"displayOrder":19},{"order":20,"id":"20-l-un-vers-l-autre","title":"L'un vers l'autre","titleZh":"走向彼此","lines":[{"id":"les-miserables-1980-20-001","lineIndex":1,"speaker":"Éponine","original":"Deux anges qui se découvrent","ipa":"/døz ɑ̃ʒ ki sə dekuvʁ/","zh":"两个初次发现彼此的天使","en":"Two angels discovering one another","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-20-002","lineIndex":2,"speaker":"Éponine","original":"N'ont rien à expliquer","ipa":"/nɔ̃ ʁiɛ̃n a ɛksplike/","zh":"无需解释什么。","en":"need explain nothing.","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-20-003","lineIndex":3,"speaker":"Éponine","original":"Deux âmes qui se retrouvent","ipa":"/døz am ki sə ʁətʁuv/","zh":"两个重逢的灵魂","en":"Two souls finding one another again","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-20-004","lineIndex":4,"speaker":"Éponine","original":"Ont tout dit sans parler","ipa":"/ɔ̃ tu di sɑ̃ paʁle/","zh":"不说话也已道尽一切。","en":"have said everything without speaking.","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-20-005","lineIndex":5,"speaker":"Éponine","original":"J'ai souvent rêvé","ipa":"/ʒe suvɑ̃ ʁɛve/","zh":"我常常梦想","en":"I have often dreamed","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-20-006","lineIndex":6,"speaker":"Éponine","original":"Dans les bras de Marius d'être à sa place","ipa":"/dɑ̃ le bʁa də maʁjys dɛtʁ a sa plas/","zh":"我常梦想能在马吕斯怀中，取代她的位置。","en":"of taking her place in Marius’s arms.","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-20-007","lineIndex":7,"speaker":"Éponine","original":"Devant ce bonheur","ipa":"/dəvɑ̃ sə bɔnœʁ/","zh":"面对这份幸福","en":"Before this happiness","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-20-008","lineIndex":8,"speaker":"Éponine","original":"D'un autre monde la jalousie s'efface","ipa":"/dœ̃n otʁ mɔ̃d la ʒaluzi sefas/","zh":"属于另一个世界的嫉妒渐渐消散。","en":"jealousy from another world fades away.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-20-009","lineIndex":9,"speaker":"Éponine","original":"Ils marchaient sans savoir l'un vers l'autre","ipa":"/il maʁʃɛ sɑ̃ savwaʁ lœ̃ vɛʁ lotʁ/","zh":"他们不自知地走向彼此","en":"They walked unknowingly toward each other","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-20-010","lineIndex":10,"speaker":"Éponine","original":"Comme la chance quand elle cherche le hasard","ipa":"/kɔm la ʃɑ̃s kɑ̃t ɛl ʃɛʁʃ lə azaʁ/","zh":"像命运去寻找偶然。","en":"like fortune when it seeks chance.","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-20-011","lineIndex":11,"speaker":"Éponine","original":"Deux enfants mis au monde l'un pour l'autre","ipa":"/døz ɑ̃fɑ̃ mi o mɔ̃d lœ̃ puʁ lotʁ/","zh":"两个为彼此而生的孩子","en":"Two children born for one another","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-20-012","lineIndex":12,"speaker":"Éponine","original":"Pour jouer les héros d'une histoire","ipa":"/puʁ ʒwe le eʁo dyn istwaʁ/","zh":"来演一则故事里的主角。","en":"to play the heroes in a story.","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-20-013","lineIndex":13,"speaker":"Éponine","original":"Ils descendent des nuages","ipa":"/il dɛsɑ̃d de nyaʒ/","zh":"他们仿佛从云端降临","en":"They descend from the clouds","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-20-014","lineIndex":14,"speaker":"Éponine","original":"Rayonnants de mystère","ipa":"/ʁɛjɔnɑ̃ də mistɛʁ/","zh":"周身闪耀着神秘。","en":"radiant with mystery","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-20-015","lineIndex":15,"speaker":"Éponine","original":"Pour faire un long voyage","ipa":"/puʁ fɛʁ œ̃ lɔ̃ vwajaʒ/","zh":"在这世上踏上一段漫长的","en":"to make a long","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-20-016","lineIndex":16,"speaker":"Éponine","original":"D'amour sur cette terre","ipa":"/damuʁ syʁ sɛt tɛʁ/","zh":"爱的旅程。","en":"journey of love on this earth.","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-20-017","lineIndex":17,"speaker":"Éponine","original":"A peine se sont-ils vus","ipa":"/a pɛn sə sɔ̃til vy/","zh":"他们才刚见面","en":"Barely had they seen each other","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-20-018","lineIndex":18,"speaker":"Éponine","original":"Qu'ils se sont reconnus","ipa":"/kil sə sɔ̃ ʁəkɔny/","zh":"就已认出了彼此","en":"when they recognized one another","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-20-019","lineIndex":19,"speaker":"Éponine","original":"Avant de se connaître","ipa":"/avɑ̃ də sə kɔnɛtʁ/","zh":"在真正相识之前。","en":"before knowing each other.","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-20-020","lineIndex":20,"speaker":"Éponine","original":"Le bonheur leur va bien l'un à l'autre","ipa":"/lə bɔnœʁ lœʁ va bjɛ̃ lœ̃n a lotʁ/","zh":"他们彼此般配，幸福也格外衬他们。","en":"They suit each other; happiness suits them too.","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-20-021","lineIndex":21,"speaker":"Éponine","original":"Un aveugle en son cœur pourrait le voir","ipa":"/œ̃n avøɡl ɑ̃ sɔ̃ kœʁ puʁɛ lə vwaʁ/","zh":"连心盲的人也看得出来。","en":"Even one blind at heart could see it.","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-20-022","lineIndex":22,"speaker":"Éponine","original":"Le bonheur, ça fait mal chez les autres","ipa":"/lə bɔnœʁ sa fɛ mal ʃe lez otʁ/","zh":"别人的幸福总叫人心痛","en":"Other people’s happiness hurts","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-20-023","lineIndex":23,"speaker":"Éponine","original":"Quand on n'a pas de rôle dans l'histoire","ipa":"/kɑ̃t ɔ̃ na pa də ʁol dɑ̃ listwaʁ/","zh":"当自己在这故事里没有角色。","en":"when you have no role in the story.","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-20-024","lineIndex":24,"speaker":"Éponine","original":"Mais dans une pièce à deux","ipa":"/mɛ dɑ̃z yn pjɛs a dø/","zh":"可在一出两个人的戏里","en":"But in a play for two","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-20-025","lineIndex":25,"speaker":"Éponine","original":"Les autres n'ont pas réplique","ipa":"/lez otʁ nɔ̃ pa ʁeplik/","zh":"旁人没有台词。","en":"the others have no lines.","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-20-026","lineIndex":26,"speaker":"Éponine","original":"Ils marchaient sans savoir l'un vers l'autre","ipa":"/il maʁʃɛ sɑ̃ savwaʁ lœ̃ vɛʁ lotʁ/","zh":"他们不自知地走向彼此","en":"They walked unknowingly toward each other","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-20-027","lineIndex":27,"speaker":"Éponine","original":"Et la chance à trouvé le hasard","ipa":"/e la ʃɑ̃s a tʁuve lə azaʁ/","zh":"命运找到了偶然","en":"and fortune found chance","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-20-028","lineIndex":28,"speaker":"Éponine","original":"On n'peut plus les aimer l'un sans l'autre","ipa":"/ɔ̃ npø ply lez ɛme lœ̃ sɑ̃ lotʁ/","zh":"再也不能只爱其中一个，不爱另一个","en":"we can no longer love one without the other","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-20-029","lineIndex":29,"speaker":"Éponine","original":"Sans trahir la morale de l'histoire","ipa":"/sɑ̃ tʁaiʁ la moʁal də listwaʁ/","zh":"否则便有违这故事的道理。","en":"without betraying the story's moral.","note":"","sourceLineIndex":29}],"sourceOrder":20,"displayOrder":20},{"order":21,"id":"21-la-faute-a-voltaire","title":"La Faute à Voltaire","titleZh":"伏尔泰的错误","lines":[{"id":"les-miserables-1980-21-001","lineIndex":1,"speaker":"Gavroche","original":"Je suis tombé par terre","ipa":"/ʒə sɥi tɔ̃be paʁ tɛʁ/","zh":"我摔倒在地","en":"I fell to the ground","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-21-002","lineIndex":2,"speaker":"Gavroche","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-21-003","lineIndex":3,"speaker":"Gavroche","original":"Le nez dans le ruisseau","ipa":"/lə ne dɑ̃ lə ʁyiso/","zh":"鼻子栽进了水沟","en":"Nose in the stream","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-21-004","lineIndex":4,"speaker":"Gavroche","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-21-005","lineIndex":5,"speaker":"Gavroche","original":"Je ne suis pas notaire","ipa":"/ʒə nə sɥi pa notɛʁ/","zh":"我不是公证人","en":"I'm not a notary","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-21-006","lineIndex":6,"speaker":"Gavroche","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-21-007","lineIndex":7,"speaker":"Gavroche","original":"Je suis petit oiseau","ipa":"/ʒə sɥi pətit wazo/","zh":"我是一只小鸟","en":"I am little bird","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-21-008","lineIndex":8,"speaker":"Gavroche","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-21-009","lineIndex":9,"speaker":"Tous","original":"Il est tombé par terre","ipa":"/il ɛ tɔ̃be paʁ tɛʁ/","zh":"他倒在地上","en":"He fell to the ground","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-21-010","lineIndex":10,"speaker":"Tous","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-21-011","lineIndex":11,"speaker":"Tous","original":"Le nez dans le ruisseau","ipa":"/lə ne dɑ̃ lə ʁyiso/","zh":"鼻子栽进了水沟","en":"Nose in the stream","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-21-012","lineIndex":12,"speaker":"Tous","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-21-013","lineIndex":13,"speaker":"Tous","original":"Si tu n'es pas notaire","ipa":"/si ty nɛ pa notɛʁ/","zh":"如果你不是公证人","en":"If you are not a notary","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-21-014","lineIndex":14,"speaker":"Tous","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-21-015","lineIndex":15,"speaker":"Tous","original":"Tu es petit oiseau","ipa":"/ty ɛ pətit wazo/","zh":"你就是一只小鸟","en":"You are little bird","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-21-016","lineIndex":16,"speaker":"Tous","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-21-017","lineIndex":17,"speaker":"Gavroche","original":"Je suis tombé sur terre","ipa":"/ʒə sɥi tɔ̃be syʁ tɛʁ/","zh":"我倒在地上","en":"I fell to the ground","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-21-018","lineIndex":18,"speaker":"Gavroche","original":"Même Dieu ne sait pas comment","ipa":"/mɛm djø nə sɛ pa kɔmɑ̃/","zh":"连上帝也不知道怎么","en":"Even God does not know how","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-21-019","lineIndex":19,"speaker":"Gavroche","original":"Je n'ai ni père, ni mère","ipa":"/ʒə ne ni pɛʁ ni mɛʁ/","zh":"我既没有爸爸也没有妈妈","en":"I have no father, nor mother","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-21-020","lineIndex":20,"speaker":"Gavroche","original":"Qui m'reconnaissent leur enfant","ipa":"/ki mʁəkɔnɛs lœʁ ɑ̃fɑ̃/","zh":"谁认我为孩子","en":"Who recognize me as their child","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-21-021","lineIndex":21,"speaker":"Gavroche","original":"Je m'suis fait une famille","ipa":"/ʒə msɥi fɛt yn famij/","zh":"我组建了一个家庭","en":"I made a family","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-21-022","lineIndex":22,"speaker":"Gavroche","original":"Avec ceux qui n'en ont pas","ipa":"/avɛk sø ki nɑ̃n ɔ̃ pa/","zh":"与那些没有家庭的人","en":"With those who don't have one","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-21-023","lineIndex":23,"speaker":"Gavroche","original":"Joyeux drilles en guenilles","ipa":"/ʒwajø dʁijz ɑ̃ ɡənij/","zh":"一群衣衫褴褛的快乐伙伴","en":"Happy girls in rags","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-21-024","lineIndex":24,"speaker":"Gavroche","original":"Avec un cœur gros comme ça","ipa":"/avɛk œ̃ kœʁ ɡʁo kɔm sa/","zh":"却都有这么大的一颗心。","en":"With a heart like that","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-21-025","lineIndex":25,"speaker":"Tous","original":"Il est tombé par terre","ipa":"/il ɛ tɔ̃be paʁ tɛʁ/","zh":"他倒在地上","en":"He fell to the ground","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-21-026","lineIndex":26,"speaker":"Tous","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-21-027","lineIndex":27,"speaker":"Tous","original":"Le nez dans le ruisseau","ipa":"/lə ne dɑ̃ lə ʁyiso/","zh":"鼻子栽进了水沟","en":"Nose in the stream","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-21-028","lineIndex":28,"speaker":"Tous","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-21-029","lineIndex":29,"speaker":"Tous","original":"Joie est ton caractère","ipa":"/ʒwa ɛ tɔ̃ kaʁaktɛʁ/","zh":"快乐是你的性格","en":"Joy is your character","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-21-030","lineIndex":30,"speaker":"Tous","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-21-031","lineIndex":31,"speaker":"Tous","original":"Misère est ton trousseau","ipa":"/mizɛʁ ɛ tɔ̃ tʁuso/","zh":"痛苦是你的嫁妆","en":"Misery is your trousseau","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-21-032","lineIndex":32,"speaker":"Tous","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-21-033","lineIndex":33,"speaker":"Gavroche","original":"Je suis un va-nu-pieds","ipa":"/ʒə sɥiz œ̃ vanypje/","zh":"我是个赤脚流浪儿","en":"I am a barefooter","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-21-034","lineIndex":34,"speaker":"Gavroche","original":"Mais, nu, le pied va quand même","ipa":"/mɛ ny lə pje va kɑ̃ mɛm/","zh":"脚再光着，也照样往前走。","en":"But, naked, the foot still fits","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-21-035","lineIndex":35,"speaker":"Gavroche","original":"Je prends ce qui me plaît","ipa":"/ʒə pʁɑ̃ sə ki mə plɛ/","zh":"我喜欢什么就拿什么","en":"I take what I like","note":"","sourceLineIndex":35},{"id":"les-miserables-1980-21-036","lineIndex":36,"speaker":"Gavroche","original":"Pour payer, pas de problème","ipa":"/puʁ pɛje pa də pʁɔblɛm/","zh":"至于付钱，没这个烦恼。","en":"To pay, no problem","note":"","sourceLineIndex":36},{"id":"les-miserables-1980-21-037","lineIndex":37,"speaker":"Gavroche","original":"Je fais des pieds de nez","ipa":"/ʒə fɛ de pje də ne/","zh":"我冲他们做鬼脸","en":"I make snub","note":"","sourceLineIndex":37},{"id":"les-miserables-1980-21-038","lineIndex":38,"speaker":"Gavroche","original":"Aux marchands et à leurs dames","ipa":"/o maʁʃɑ̃z e a lœʁ dam/","zh":"那些商人和太太们。","en":"To the merchants and their ladies","note":"","sourceLineIndex":38},{"id":"les-miserables-1980-21-039","lineIndex":39,"speaker":"Tous","original":"Et pour te rattraper","ipa":"/e puʁ tə ʁatʁape/","zh":"想要逮住你","en":"And to catch up with you","note":"","sourceLineIndex":39},{"id":"les-miserables-1980-21-040","lineIndex":40,"speaker":"Tous","original":"Il leur faut plus d'un gendarme!","ipa":"/il lœʁ fo ply dœ̃ ʒɑ̃daʁm/","zh":"他们需要不止一名警察！","en":"They need more than one policeman!","note":"","sourceLineIndex":40},{"id":"les-miserables-1980-21-041","lineIndex":41,"speaker":"Gavroche","original":"On me connaît partout","ipa":"/ɔ̃ mə kɔnɛ paʁtu/","zh":"我无处不在","en":"I am known everywhere","note":"","sourceLineIndex":41},{"id":"les-miserables-1980-21-042","lineIndex":42,"speaker":"Gavroche","original":"De Clignancourt à Belleville","ipa":"/də klinjɑ̃kuʁ a bɛlvil/","zh":"从克里尼昂库尔到贝尔维尔","en":"From Clignancourt to Belleville","note":"","sourceLineIndex":42},{"id":"les-miserables-1980-21-043","lineIndex":43,"speaker":"Gavroche","original":"Je suis aimé par tous","ipa":"/ʒə sɥiz ɛme paʁ tus/","zh":"每个人都爱我","en":"I am loved by everyone","note":"","sourceLineIndex":43},{"id":"les-miserables-1980-21-044","lineIndex":44,"speaker":"Gavroche","original":"Sauf par les sergents de ville","ipa":"/sof paʁ le sɛʁʒɑ̃ də vil/","zh":"除了城镇警官","en":"Except by the town sergeants","note":"","sourceLineIndex":44},{"id":"les-miserables-1980-21-045","lineIndex":45,"speaker":"Gavroche","original":"Je vis de ce qui vient","ipa":"/ʒə vi də sə ki vjɛ̃/","zh":"来什么，我就靠什么活","en":"I live on what comes","note":"","sourceLineIndex":45},{"id":"les-miserables-1980-21-046","lineIndex":46,"speaker":"Gavroche","original":"Et de ce qui ne vient pas","ipa":"/e də sə ki nə vjɛ̃ pa/","zh":"连没来的，也算我的日子。","en":"And on what does not come","note":"","sourceLineIndex":46},{"id":"les-miserables-1980-21-047","lineIndex":47,"speaker":"Gavroche","original":"Sans savoir à l'avance","ipa":"/sɑ̃ savwaʁ a lavɑ̃s/","zh":"我从不预先知道","en":"Without knowing in advance","note":"","sourceLineIndex":47},{"id":"les-miserables-1980-21-048","lineIndex":48,"speaker":"Gavroche","original":"Misère est mon trousseau","ipa":"/mizɛʁ ɛ mɔ̃ tʁuso/","zh":"苦难是我随身的行囊","en":"Misery is my trousseau","note":"","sourceLineIndex":48},{"id":"les-miserables-1980-21-049","lineIndex":49,"speaker":"Tous","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"都怪卢梭。","en":"It's Rousseau's fault","note":"","sourceLineIndex":49},{"id":"les-miserables-1980-21-050","lineIndex":50,"speaker":"Tous","original":"On est laid à Nanterre","ipa":"/ɔ̃n ɛ lɛd a nɑ̃tɛʁ/","zh":"在南泰尔，人就是丑","en":"We are ugly in Nanterre","note":"","sourceLineIndex":50},{"id":"les-miserables-1980-21-051","lineIndex":51,"speaker":"Gavroche","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":51},{"id":"les-miserables-1980-21-052","lineIndex":52,"speaker":"Tous","original":"Et bête à Palaiseau","ipa":"/e bɛt a palɛzo/","zh":"到帕莱索，人就犯傻","en":"And beast in Palaiseau","note":"","sourceLineIndex":52},{"id":"les-miserables-1980-21-053","lineIndex":53,"speaker":"Gavroche","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":53},{"id":"les-miserables-1980-21-054","lineIndex":54,"speaker":"Tous","original":"Si tu n'es pas notaire","ipa":"/si ty nɛ pa notɛʁ/","zh":"如果你不是公证人","en":"If you are not a notary","note":"","sourceLineIndex":54},{"id":"les-miserables-1980-21-055","lineIndex":55,"speaker":"Gavroche","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":55},{"id":"les-miserables-1980-21-056","lineIndex":56,"speaker":"Tous","original":"Tu es petit oiseau","ipa":"/ty ɛ pətit wazo/","zh":"你就是一只小鸟","en":"You are little bird","note":"","sourceLineIndex":56},{"id":"les-miserables-1980-21-057","lineIndex":57,"speaker":"Gavroche","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":57},{"id":"les-miserables-1980-21-058","lineIndex":58,"speaker":"Tous","original":"Il est tombé par terre","ipa":"/il ɛ tɔ̃be paʁ tɛʁ/","zh":"他倒在地上","en":"He fell to the ground","note":"","sourceLineIndex":58},{"id":"les-miserables-1980-21-059","lineIndex":59,"speaker":"Tous","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":59},{"id":"les-miserables-1980-21-060","lineIndex":60,"speaker":"Tous","original":"Le nez dans le ruisseau","ipa":"/lə ne dɑ̃ lə ʁyiso/","zh":"鼻子栽进了水沟","en":"Nose in the stream","note":"","sourceLineIndex":60},{"id":"les-miserables-1980-21-061","lineIndex":61,"speaker":"Tous","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":61},{"id":"les-miserables-1980-21-062","lineIndex":62,"speaker":"Tous","original":"Si tu n'es pas notaire","ipa":"/si ty nɛ pa notɛʁ/","zh":"如果你不是公证人","en":"If you are not a notary","note":"","sourceLineIndex":62},{"id":"les-miserables-1980-21-063","lineIndex":63,"speaker":"Tous","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":63},{"id":"les-miserables-1980-21-064","lineIndex":64,"speaker":"Tous","original":"Tu es petit oiseau","ipa":"/ty ɛ pətit wazo/","zh":"你就是一只小鸟","en":"You are little bird","note":"","sourceLineIndex":64},{"id":"les-miserables-1980-21-065","lineIndex":65,"speaker":"Tous","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":65},{"id":"les-miserables-1980-21-066","lineIndex":66,"speaker":"Tous","original":"Tu es petit oiseau","ipa":"/ty ɛ pətit wazo/","zh":"你就是一只小鸟","en":"You are little bird","note":"","sourceLineIndex":66},{"id":"les-miserables-1980-21-067","lineIndex":67,"speaker":"Tous","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"这是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":67}],"sourceOrder":21,"displayOrder":21},{"order":22,"id":"22-la-nuit-de-l-angoisse","title":"La Nuit de l'Angoisse","titleZh":"痛苦之夜","lines":[{"id":"les-miserables-1980-22-001","lineIndex":1,"speaker":"Feuilly","original":"Pourquoi doit-on tirer","ipa":"/puʁkwa dwatɔ̃ tiʁe/","zh":"为什么非得开枪","en":"Why must we shoot","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-22-002","lineIndex":2,"speaker":"Feuilly","original":"Pour s'élever contre le meurtre de ses idées?","ipa":"/puʁ selve kɔ̃tʁ lə mœʁtʁ də sez ide/","zh":"才能反抗自己理念被扼杀？","en":"to rise up against the murder of one’s ideas?","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-22-003","lineIndex":3,"speaker":"Feuilly","original":"Et pourquoi dominer","ipa":"/e puʁkwa domine/","zh":"为什么要统治","en":"And why dominate","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-22-004","lineIndex":4,"speaker":"Feuilly","original":"Pour renverser à leur tour les dominateurs?","ipa":"/puʁ ʁɑ̃vɛʁse a lœʁ tuʁ le dominatœʁ/","zh":"依次推翻统治者？","en":"To overthrow the dominators in turn?","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-22-005","lineIndex":5,"speaker":"Feuilly","original":"Et en quoi espérer","ipa":"/e ɑ̃ kwa ɛspeʁe/","zh":"当这场游戏的牌都被做了手脚","en":"And what can one hope for","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-22-006","lineIndex":6,"speaker":"Feuilly","original":"Quand les cartes du jeu sont truquées?","ipa":"/kɑ̃ le kaʁt dy ʒø sɔ̃ tʁyke/","zh":"还该期待什么？","en":"when the cards are rigged?","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-22-007","lineIndex":7,"speaker":"Combeferre","original":"C'est peut-être le dernier","ipa":"/sɛ pøtɛtʁ lə dɛʁnje/","zh":"这也许是最后一次","en":"This is perhaps the last","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-22-008","lineIndex":8,"speaker":"Combeferre","original":"Le dernier coup de blanc","ipa":"/lə dɛʁnje ku də blɑ̃/","zh":"最后一杯白酒","en":"the last drink of white wine","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-22-009","lineIndex":9,"speaker":"Combeferre","original":"Avant le coup de grâce","ipa":"/avɑ̃ lə ku də ɡʁas/","zh":"在最后一击之前","en":"Before the final blow","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-22-010","lineIndex":10,"speaker":"Combeferre","original":"Allez, vide ton verre","ipa":"/ale vid tɔ̃ vɛʁ/","zh":"来吧，倒空你的杯子","en":"Come on, empty your glass","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-22-011","lineIndex":11,"speaker":"Combeferre","original":"Et remplis vite le mien","ipa":"/e ʁɑ̃pli vit lə mjɛ̃/","zh":"并快速填充我的","en":"And quickly fill mine","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-22-012","lineIndex":12,"speaker":"Combeferre","original":"Avant que la mort passe","ipa":"/avɑ̃ kə la mɔʁ pas/","zh":"在死亡过去之前","en":"Before death passes","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-22-013","lineIndex":13,"speaker":"Enjolras","original":"Allons, Lamarque est mort","ipa":"/alɔ̃ lamaʁk ɛ mɔʁ/","zh":"来吧，拉马克死了","en":"Come on, Lamarque is dead","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-22-014","lineIndex":14,"speaker":"Enjolras","original":"Nous admirions sa bravoure au combat","ipa":"/nuz admiʁjɔ̃ sa bʁavuʁ o kɔ̃ba/","zh":"我们钦佩他在战斗中的英勇","en":"We admired his bravery in combat","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-22-015","lineIndex":15,"speaker":"Enjolras","original":"Il n'est pas mort","ipa":"/il nɛ pa mɔʁ/","zh":"他没有死","en":"He is not dead","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-22-016","lineIndex":16,"speaker":"Enjolras","original":"Drapeau vivant de ceux qui n'en ont pas","ipa":"/dʁapo vivɑ̃ də sø ki nɑ̃n ɔ̃ pa/","zh":"那些一无所有的人的活旗帜","en":"Living flag of those who have none","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-22-017","lineIndex":17,"speaker":"Enjolras","original":"Puisqu'on n'a toujours rien, persévérons en tout","ipa":"/pɥiskɔ̃ na tuʒuʁ ʁiɛ̃ pɛʁseveʁɔ̃z ɑ̃ tu/","zh":"既然我们仍一无所有，就在一切上坚持到底。","en":"Since we still have nothing, let us persevere in everything.","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-22-018","lineIndex":18,"speaker":"Enjolras","original":"Rêvons jusqu'à demain que Paris est à nous","ipa":"/ʁɛvɔ̃ ʒyska dəmɛ̃ kə paʁi ɛt a nu/","zh":"就梦到明天吧：巴黎属于我们。","en":"Let us dream until tomorrow that Paris is ours.","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-22-019","lineIndex":19,"speaker":"Feuilly","original":"Souviens-toi des jours heureux","ipa":"/suvjɛ̃twa de ʒuʁz øʁø/","zh":"记住那些快乐的日子","en":"Remember the happy days","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-22-020","lineIndex":20,"speaker":"Feuilly","original":"Souviens-toi de nos aveux","ipa":"/suvjɛ̃twa də noz avø/","zh":"记住我们的告白","en":"Remember our confessions","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-22-021","lineIndex":21,"speaker":"Feuilly","original":"Lorsqu'en ajoutant ton âge à mon âge","ipa":"/loʁskɑ̃n aʒutɑ̃ tɔ̃n aʒ a mɔ̃n aʒ/","zh":"将你的年龄加到我的年龄上","en":"When adding your age to my age","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-22-022","lineIndex":22,"speaker":"Feuilly","original":"Nous ne comptions pas quarante ans à deux","ipa":"/nu nə kɔ̃tjɔ̃ pa kaʁɑ̃t ɑ̃z a dø/","zh":"我们并没有算在一起四十年","en":"We did not count forty years together","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-22-023","lineIndex":23,"speaker":"Feuilly","original":"Souviens-toi de nos aveux","ipa":"/suvjɛ̃twa də noz avø/","zh":"记住我们的告白","en":"Remember our confessions","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-22-024","lineIndex":24,"speaker":"Feuilly","original":"Souviens-toi des jours heureux","ipa":"/suvjɛ̃twa de ʒuʁz øʁø/","zh":"记住那些快乐的日子","en":"Remember the happy days","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-22-025","lineIndex":25,"speaker":"Feuilly","original":"De dentelle, fleur au corsage et rubans","ipa":"/də dɑ̃tɛl flœʁ o kɔʁsaʒ e ʁybɑ̃/","zh":"有蕾丝、胸前的花和缎带","en":"of lace, a flower at the bodice and ribbons","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-22-026","lineIndex":26,"speaker":"Feuilly","original":"Où l'amour bégaie un argot charmant","ipa":"/u lamuʁ beɡɛ œ̃n aʁɡo ʃaʁmɑ̃/","zh":"爱情在那里结结巴巴说着迷人的俚语。","en":"where love stammers a charming slang.","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-22-027","lineIndex":27,"speaker":"Feuilly","original":"Souviens-toi de nos aveux","ipa":"/suvjɛ̃twa də noz avø/","zh":"记住我们的告白","en":"Remember our confessions","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-22-028","lineIndex":28,"speaker":"Feuilly","original":"Souviens-toi des jours heureux","ipa":"/suvjɛ̃twa de ʒuʁz øʁø/","zh":"记住那些快乐的日子","en":"Remember the happy days","note":"","sourceLineIndex":28}],"sourceOrder":22,"displayOrder":22},{"order":23,"id":"23-demain","title":"Demain","titleZh":"明天","lines":[{"id":"les-miserables-1980-23-001","lineIndex":1,"speaker":"Valjean","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么办？","en":"How to do it?","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-23-002","lineIndex":2,"speaker":"Valjean","original":"Verrai-je un jour la fin de ce calvaire","ipa":"/vɛʁeʒ œ̃ ʒuʁ la fɛ̃ də sə kalvɛʁ/","zh":"有一天我会看到这场磨难的结束","en":"Will I one day see the end of this ordeal","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-23-003","lineIndex":3,"speaker":"Valjean","original":"Vivrons-nous libres enfin et sans mystère","ipa":"/vivʁɔ̃nu libʁz ɑ̃fɛ̃ e sɑ̃ mistɛʁ/","zh":"我们终能自由生活，不必再躲藏吗？","en":"Will we finally live free and without secrecy?","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-23-004","lineIndex":4,"speaker":"Valjean","original":"Sans avoir à trembler sans cesse","ipa":"/sɑ̃z avwaʁ a tʁɑ̃ble sɑ̃ sɛs/","zh":"不必不断颤抖","en":"Without having to tremble constantly","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-23-005","lineIndex":5,"speaker":"Valjean","original":"À chaque alerte, changer d'adresse","ipa":"/a ʃak alɛʁt ʃɑ̃ʒe dadʁɛs/","zh":"每次警报，改变地址","en":"With each alert, change address","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-23-006","lineIndex":6,"speaker":"Valjean","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么办？","en":"How to do it?","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-23-007","lineIndex":7,"speaker":"Cosette","original":"Demain, je ne le verrai plus","ipa":"/dəmɛ̃ ʒə nə lə vɛʁe ply/","zh":"明天，我将不再见到他","en":"Tomorrow, I will no longer see him","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-23-008","lineIndex":8,"speaker":"Cosette","original":"Mon sang se glace dans mes veines","ipa":"/mɔ̃ sɑ̃ sə ɡlas dɑ̃ me vɛn/","zh":"我的血液在血管里冻结","en":"My blood freezes in my veins","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-23-009","lineIndex":9,"speaker":"Valjean","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么办？","en":"How to do it?","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-23-010","lineIndex":10,"speaker":"Marius et Cosette","original":"Demain, je ne la verrai plus","ipa":"/dəmɛ̃ ʒə nə la vɛʁe ply/","zh":"明天，我将不再见到她","en":"Tomorrow, I will no longer see her","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-23-011","lineIndex":11,"speaker":"Marius et Cosette","original":"C'est comme la foudre que l'on m'assène","ipa":"/sɛ kɔm la fudʁ kə lɔ̃ masɛn/","zh":"就像闪电击中我","en":"It's like lightning that strikes me","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-23-012","lineIndex":12,"speaker":"Éponine","original":"Demain, je perdrai peut-être","ipa":"/dəmɛ̃ ʒə pɛʁdʁe pøtɛtʁ/","zh":"明天，我也许会失去","en":"Tomorrow, I will perhaps lose","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-23-013","lineIndex":13,"speaker":"Éponine","original":"L'amitié d'un cœur honnête","ipa":"/lamitje dœ̃ kœʁ ɔnɛt/","zh":"一颗诚实的心的友谊","en":"The friendship of an honest heart","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-23-014","lineIndex":14,"speaker":"Éponine","original":"Qui ne peut me donner plus","ipa":"/ki nə pø mə dɔne ply/","zh":"他已不能再给我更多。","en":"who can give me no more.","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-23-015","lineIndex":15,"speaker":"Éponine","original":"Il aime Cosette, je l'accepte","ipa":"/il ɛm kozɛt ʒə laksɛpt/","zh":"他爱珂赛特，我接受这一点。","en":"He loves Cosette; I accept it.","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-23-016","lineIndex":16,"speaker":"Valjean","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么办？","en":"How to do it?","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-23-017","lineIndex":17,"speaker":"Javert","original":"Demain, le crime en vacances","ipa":"/dəmɛ̃ lə kʁim ɑ̃ vakɑ̃s/","zh":"明天，罪犯们会趁机撒野","en":"Tomorrow, crime will be on holiday","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-23-018","lineIndex":18,"speaker":"Javert","original":"Va se croire tout permis","ipa":"/va sə kʁwaʁ tu pɛʁmi/","zh":"会认为这都是可以的","en":"Will think it's all permissible","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-23-019","lineIndex":19,"speaker":"Javert","original":"Ce général qu'on encense","ipa":"/sə ʒeneʁal kɔ̃n ɑ̃sɑ̃s/","zh":"我们赞扬的这位将军","en":"This general who we praise","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-23-020","lineIndex":20,"speaker":"Javert","original":"Est un prétexte à chienlit","ipa":"/ɛt œ̃ pʁetɛkst a ʃjɑ̃li/","zh":"不过是制造混乱的借口。","en":"is a pretext for chaos.","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-23-021","lineIndex":21,"speaker":"Valjean","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么办？","en":"How to do it?","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-23-022","lineIndex":22,"speaker":"Les Thénardier","original":"Demain au cortège","ipa":"/dəmɛ̃ o kɔʁtɛʒ/","zh":"明天的游行","en":"Tomorrow at the procession","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-23-023","lineIndex":23,"speaker":"Les Thénardier","original":"C'est nous qu'on soulage","ipa":"/sɛ nu kɔ̃ sulaʒ/","zh":"要替大腹便便的富人们","en":"We will relieve","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-23-024","lineIndex":24,"speaker":"Les Thénardier","original":"Les ventripotents","ipa":"/le vɑ̃tʁipot/","zh":"把他们","en":"those potbellied people","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-23-025","lineIndex":25,"speaker":"Les Thénardier","original":"De leur trop plein d'argent","ipa":"/də lœʁ tʁo plɛ̃ daʁʒɑ̃/","zh":"从他们过多的钱里“解放”出来。","en":"of their excess money.","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-23-026","lineIndex":26,"speaker":"Les Thénardier","original":"De droite ou de gauche","ipa":"/də dʁwat u də ɡoʃ/","zh":"左还是右","en":"Right or left","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-23-027","lineIndex":27,"speaker":"Les Thénardier","original":"Qu'importe le blason","ipa":"/kɛ̃pɔʁt lə blazɔ̃/","zh":"徽章有什么关系","en":"What does the coat of arms matter","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-23-028","lineIndex":28,"speaker":"Les Thénardier","original":"Si c'est dans nos poches","ipa":"/si sɛ dɑ̃ no poʃ/","zh":"如果它在我们的口袋里","en":"If it's in our pockets","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-23-029","lineIndex":29,"speaker":"Les Thénardier","original":"Pour nous c'est tout bon","ipa":"/puʁ nu sɛ tu bɔ̃/","zh":"对我们来说一切都好","en":"For us it's all good","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-23-030","lineIndex":30,"speaker":"Les Amis de l'ABC","original":"À la volonté du peuple","ipa":"/a la volɔ̃te dy pøpl/","zh":"为了人民的意志","en":"To the will of the people","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-23-031","lineIndex":31,"speaker":"Gavroche","original":"À la volonté du peuple","ipa":"/a la volɔ̃te dy pøpl/","zh":"为了人民的意志","en":"To the will of the people","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-23-032","lineIndex":32,"speaker":"Les Amis de l'ABC","original":"À la santé du progrès","ipa":"/a la sɑ̃te dy pʁɔɡʁɛ/","zh":"为了进步，干杯！","en":"To the health of progress!","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-23-033","lineIndex":33,"speaker":"Gavroche","original":"À la santé du progrès","ipa":"/a la sɑ̃te dy pʁɔɡʁɛ/","zh":"为了进步，干杯！","en":"To the health of progress!","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-23-034","lineIndex":34,"speaker":"Les Amis de l'ABC","original":"Saoule ton cœur d'un chant rebelle","ipa":"/sul tɔ̃ kœʁ dœ̃ ʃɑ̃ ʁəbɛl/","zh":"用一首叛逆的歌充满你的心","en":"Fill your heart with a rebellious song","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-23-035","lineIndex":35,"speaker":"Gavroche","original":"Saoule ton cœur d'un chant rebelle","ipa":"/sul tɔ̃ kœʁ dœ̃ ʃɑ̃ ʁəbɛl/","zh":"用一首叛逆的歌充满你的心","en":"Fill your heart with a rebellious song","note":"","sourceLineIndex":35},{"id":"les-miserables-1980-23-036","lineIndex":36,"speaker":"Les Amis de l'ABC et Gavroche","original":"C'est pour demain, ami fidèle","ipa":"/sɛ puʁ dəmɛ̃ ami fidɛl/","zh":"明天，忠实的朋友","en":"It's for tomorrow, faithful friend","note":"","sourceLineIndex":36},{"id":"les-miserables-1980-23-037","lineIndex":37,"speaker":"Les Amis de l'ABC et Gavroche","original":"Demain, demain, demain, demain...","ipa":"/dəmɛ̃ dəmɛ̃ dəmɛ̃ dəmɛ̃/","zh":"明天，明天，明天，明天...","en":"Tomorrow, tomorrow, tomorrow, tomorrow...","note":"","sourceLineIndex":37},{"id":"les-miserables-1980-23-038","lineIndex":38,"speaker":"Valjean","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么办？","en":"How to do it?","note":"","sourceLineIndex":38},{"id":"les-miserables-1980-23-039","lineIndex":39,"speaker":"Cosette","original":"Demain, je ne le verrai plus...","ipa":"/dəmɛ̃ ʒə nə lə vɛʁe ply/","zh":"明天，我再也见不到他了...","en":"Tomorrow, I won't see him anymore...","note":"","sourceLineIndex":39},{"id":"les-miserables-1980-23-040","lineIndex":40,"speaker":"Javert","original":"Demain, le crime en vacances...","ipa":"/dəmɛ̃ lə kʁim ɑ̃ vakɑ̃s/","zh":"明天，假期犯罪...","en":"Tomorrow, crime on vacation...","note":"","sourceLineIndex":40},{"id":"les-miserables-1980-23-041","lineIndex":41,"speaker":"Cosette","original":"Mon sang se glace dans mes veines!","ipa":"/mɔ̃ sɑ̃ sə ɡlas dɑ̃ me vɛn/","zh":"我的血液在我的血管里冻结！","en":"My blood freezes in my veins!","note":"","sourceLineIndex":41},{"id":"les-miserables-1980-23-042","lineIndex":42,"speaker":"Javert","original":"Va se croire tout permis","ipa":"/va sə kʁwaʁ tu pɛʁmi/","zh":"会认为这都是可以的","en":"Will think it's all permissible","note":"","sourceLineIndex":42},{"id":"les-miserables-1980-23-043","lineIndex":43,"speaker":"Valjean","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么办？","en":"How to do it?","note":"","sourceLineIndex":43},{"id":"les-miserables-1980-23-044","lineIndex":44,"speaker":"Valjean","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么办？","en":"How to do it?","note":"","sourceLineIndex":44},{"id":"les-miserables-1980-23-045","lineIndex":45,"speaker":"Valjean","original":"Cosette a bien grandi ces derniers temps","ipa":"/kozɛt a bjɛ̃ ɡʁɑ̃di se dɛʁnje tɑ̃/","zh":"最近珂赛特长大了很多","en":"Cosette has grown up a lot lately","note":"","sourceLineIndex":45},{"id":"les-miserables-1980-23-046","lineIndex":46,"speaker":"Valjean","original":"Je sens qu'en elle s'éveille le printemps","ipa":"/ʒə sɑ̃ kɑ̃n ɛl sevɛj lə pʁɛ̃tɑ̃/","zh":"我感觉她的春天正在苏醒","en":"I feel that spring is awakening in her","note":"","sourceLineIndex":46},{"id":"les-miserables-1980-23-047","lineIndex":47,"speaker":"Valjean","original":"Il me faut protéger sa vie","ipa":"/il mə fo pʁoteʒe sa vi/","zh":"我必须保护她的生命","en":"I must protect her life","note":"","sourceLineIndex":47},{"id":"les-miserables-1980-23-048","lineIndex":48,"speaker":"Valjean","original":"Demain nous partons loin d'ici","ipa":"/dəmɛ̃ nu paʁtɔ̃ lwɛ̃ disi/","zh":"明天我们将远离这里","en":"Tomorrow we are going far from here","note":"","sourceLineIndex":48},{"id":"les-miserables-1980-23-049","lineIndex":49,"speaker":"Valjean","original":"Demain sera pour tous un lendemain","ipa":"/dəmɛ̃ səʁa puʁ tus œ̃ lɑ̃dmɛ̃/","zh":"明天将是所有人的明天","en":"Tomorrow will be a tomorrow for everyone","note":"","sourceLineIndex":49},{"id":"les-miserables-1980-23-050","lineIndex":50,"speaker":"Valjean","original":"Qui ne peut pas mentir","ipa":"/ki nə pø pa mɑ̃tiʁ/","zh":"谁不能说谎","en":"Who can't lie","note":"","sourceLineIndex":50},{"id":"les-miserables-1980-23-051","lineIndex":51,"speaker":"Valjean","original":"C'est demain que chacun connaîtra son destin","ipa":"/sɛ dəmɛ̃ kə ʃakœ̃ kɔnɛtʁa sɔ̃ dɛstɛ̃/","zh":"明天每个人都会知道自己的命运","en":"It's tomorrow that everyone will know their destiny","note":"","sourceLineIndex":51},{"id":"les-miserables-1980-23-052","lineIndex":52,"speaker":"Tous","original":"Demain, demain, demain","ipa":"/dəmɛ̃ dəmɛ̃ dəmɛ̃/","zh":"明天，明天，明天","en":"Tomorrow, tomorrow, tomorrow","note":"","sourceLineIndex":52}],"sourceOrder":23,"displayOrder":23},{"order":24,"id":"24-ce-n-est-rien","title":"Ce n'est rien","titleZh":"没什么","lines":[{"id":"les-miserables-1980-24-001","lineIndex":1,"speaker":"Éponine","original":"Ce n'est rien, Monsieur Marius","ipa":"/sə nɛ ʁjɛ̃ məsjø maʁjys/","zh":"没什么，马吕斯先生","en":"It's nothing, Mr. Marius","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-24-002","lineIndex":2,"speaker":"Éponine","original":"Qu'un peu de sang qui pleure","ipa":"/kœ̃ pø də sɑ̃ ki plœʁ/","zh":"只是一点哭泣的鲜血","en":"Only a little blood that weeps","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-24-003","lineIndex":3,"speaker":"Éponine","original":"Dernier chagrin de pluie","ipa":"/dɛʁnje ʃaɡʁɛ̃ də plɥi/","zh":"如雨般最后一阵哀伤","en":"the last, rain-like sorrow","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-24-004","lineIndex":4,"speaker":"Éponine","original":"Aux couleurs de la mort","ipa":"/o kulœʁ də la mɔʁ/","zh":"染着死亡的颜色","en":"colored by death","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-24-005","lineIndex":5,"speaker":"Éponine","original":"Qui siffle en rafales au dehors","ipa":"/ki sifl ɑ̃ ʁafalz o dəɔʁ/","zh":"外头的枪弹正一阵阵呼啸。","en":"whistling in bursts outside.","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-24-006","lineIndex":6,"speaker":"Éponine","original":"Dernier chagrin de pluie","ipa":"/dɛʁnje ʃaɡʁɛ̃ də plɥi/","zh":"最后一场雨的悲伤","en":"Last sorrow of rain","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-24-007","lineIndex":7,"speaker":"Éponine","original":"Dernier élan de vie","ipa":"/dɛʁnjeʁ elɑ̃ də vi/","zh":"生命最后的爆发","en":"Last burst of life","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-24-008","lineIndex":8,"speaker":"Éponine","original":"D'un cœur qui n'a servi à personne","ipa":"/dœ̃ kœʁ ki na sɛʁvi a pɛʁsɔn/","zh":"来自一颗从未属于过任何人的心。","en":"from a heart that has belonged to no one.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-24-009","lineIndex":9,"speaker":"Marius","original":"Mais tu vas vivre, 'Ponine, regarde-moi","ipa":"/mɛ ty va vivʁ ponin ʁəɡaʁdmwa/","zh":"可你会活下去的，艾潘妮，看着我！","en":"But you will live, 'Ponine—look at me!","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-24-010","lineIndex":10,"speaker":"Marius","original":"L'amour saura refermer ta blessure","ipa":"/lamuʁ soʁa ʁəfɛʁme ta blɛsyʁ/","zh":"爱会替你缝合伤口。","en":"Love will know how to close your wound.","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-24-011","lineIndex":11,"speaker":"Éponine","original":"Même l'amour ne peut plus rien pour moi","ipa":"/mɛm lamuʁ nə pø ply ʁjɛ̃ puʁ mwa/","zh":"就连爱情也无法为我做任何事","en":"Even love can do nothing more for me","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-24-012","lineIndex":12,"speaker":"Éponine","original":"Prenez-moi dans vos bras","ipa":"/pʁənemwa dɑ̃ vo bʁa/","zh":"把我抱在怀里","en":"Take me in your arms","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-24-013","lineIndex":13,"speaker":"Marius et Éponine","original":"Ce n'est rien, non ce n'est rien","ipa":"/sə nɛ ʁjɛ̃ nɔ̃ sə nɛ ʁjɛ̃/","zh":"没什么，不，没什么","en":"It's nothing, no it's nothing","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-24-014","lineIndex":14,"speaker":"Marius et Éponine","original":"Qu'un peu de sang qui pleure","ipa":"/kœ̃ pø də sɑ̃ ki plœʁ/","zh":"只剩下一点点血泪","en":"Only a little blood that cries","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-24-015","lineIndex":15,"speaker":"Marius et Éponine","original":"Dernier chagrin de pluie","ipa":"/dɛʁnje ʃaɡʁɛ̃ də plɥi/","zh":"最后一场雨的悲伤","en":"Last sorrow of rain","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-24-016","lineIndex":16,"speaker":"Marius et Éponine","original":"Aux couleurs de la nuit","ipa":"/o kulœʁ də la nɥi/","zh":"在夜晚的色彩中","en":"In the colors of the night","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-24-017","lineIndex":17,"speaker":"Marius et Éponine","original":"Qui va bientôt enfin vous réunir","ipa":"/ki va bjɛ̃to ɑ̃fɛ̃ vu ʁeyniʁ/","zh":"很快终于会让你们重逢。","en":"which will soon finally reunite you.","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-24-018","lineIndex":18,"speaker":"Marius et Éponine","original":"Dernier chagrin de pluie","ipa":"/dɛʁnje ʃaɡʁɛ̃ də plɥi/","zh":"最后一场雨的悲伤","en":"Last sorrow of rain","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-24-019","lineIndex":19,"speaker":"Marius et Éponine","original":"Dernier élan de vie","ipa":"/dɛʁnjeʁ elɑ̃ də vi/","zh":"生命最后的爆发","en":"Last burst of life","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-24-020","lineIndex":20,"speaker":"Marius et Éponine","original":"D'un cœur qui n'a servi à personne","ipa":"/dœ̃ kœʁ ki na sɛʁvi a pɛʁsɔn/","zh":"来自一颗从未属于过任何人的心。","en":"From a heart that has belonged to no one.","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-24-021","lineIndex":21,"speaker":"Éponine","original":"Ce n'est que moi qui pars, vous restez là","ipa":"/sə nɛ kə mwa ki paʁ vu ʁɛste la/","zh":"只是我一个人要走了，你们留在这里。","en":"It is only I who am leaving; you stay here.","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-24-022","lineIndex":22,"speaker":"Éponine","original":"Et comme à la noce, je serai absente","ipa":"/e kɔm a la nɔs ʒə səʁe absɑ̃t/","zh":"就像在婚礼上一样，我会缺席","en":"And like at the wedding, I will be absent","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-24-023","lineIndex":23,"speaker":"Éponine","original":"Voilà sa lettre, c'est mon cadeau","ipa":"/vwala sa lɛtʁ sɛ mɔ̃ kado/","zh":"这是他的信，算是我送你们的礼物","en":"Here is his letter; it is my gift","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-24-024","lineIndex":24,"speaker":"Éponine","original":"Quelques mois à l'avance","ipa":"/kɛlkə mwaz a lavɑ̃s/","zh":"提前几个月送上的。","en":"given a few months in advance.","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-24-025","lineIndex":25,"speaker":"Éponine","original":"Ce n'est rien, non ce n'est rien","ipa":"/sə nɛ ʁjɛ̃ nɔ̃ sə nɛ ʁjɛ̃/","zh":"没什么，不，没什么","en":"It's nothing, no it's nothing","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-24-026","lineIndex":26,"speaker":"Éponine","original":"Qu'un peu de sang qui pleure","ipa":"/kœ̃ pø də sɑ̃ ki plœʁ/","zh":"只剩下一点点血泪","en":"Only a little blood that cries","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-24-027","lineIndex":27,"speaker":"Éponine","original":"Dernier chagrin de pluie","ipa":"/dɛʁnje ʃaɡʁɛ̃ də plɥi/","zh":"最后一场雨的悲伤","en":"Last sorrow of rain","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-24-028","lineIndex":28,"speaker":"Éponine","original":"Aux couleurs de la nuit","ipa":"/o kulœʁ də la nɥi/","zh":"在夜晚的色彩中","en":"In the colors of the night","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-24-029","lineIndex":29,"speaker":"Éponine","original":"Qui va bientôt enfin vous réunir","ipa":"/ki va bjɛ̃to ɑ̃fɛ̃ vu ʁeyniʁ/","zh":"很快终于会让你们重逢。","en":"which will soon finally reunite you.","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-24-030","lineIndex":30,"speaker":"Éponine (en contre-chant)","original":"Dernier chagrin de pluie","ipa":"/dɛʁnje ʃaɡʁɛ̃ də plɥi/","zh":"最后一场雨的悲伤","en":"Last sorrow of rain","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-24-031","lineIndex":31,"speaker":"Éponine (en contre-chant)","original":"Dernier élan de vie","ipa":"/dɛʁnjeʁ elɑ̃ də vi/","zh":"生命最后的爆发","en":"Last burst of life","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-24-032","lineIndex":32,"speaker":"Éponine (en contre-chant)","original":"D'un cœur qui n'a servi à personne","ipa":"/dœ̃ kœʁ ki na sɛʁvi a pɛʁsɔn/","zh":"来自一颗从未属于过任何人的心。","en":"From a heart that has belonged to no one.","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-24-033","lineIndex":33,"speaker":"Marius (en contre-chant)","original":"Elle n'a vécu","ipa":"/ɛl na veky/","zh":"她这一生","en":"She lived","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-24-034","lineIndex":34,"speaker":"Marius (en contre-chant)","original":"Que pour les autres","ipa":"/kə puʁ lez otʁ/","zh":"只为别人而活。","en":"only for others.","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-24-035","lineIndex":35,"speaker":"Marius (en contre-chant)","original":"L'amour qu'elle n'a pas eu, elle me l'offre","ipa":"/lamuʁ kɛl na paz y ɛl mə lɔfʁ/","zh":"她从未得到的爱情，如今赠与我。","en":"The love she never had, she offers to me.","note":"","sourceLineIndex":35}],"sourceOrder":24,"displayOrder":24},{"order":25,"id":"25-l-aube-du-6-juin","title":"L'Aube du 6 Juin","titleZh":"6 月 6 日黎明","lines":[{"id":"les-miserables-1980-25-001","lineIndex":1,"speaker":"Enjolras","original":"J'ordonne, les pères de famille hors des rangs","ipa":"/ʒɔʁdɔn le pɛʁ də famij ɔʁ de ʁɑ̃/","zh":"我命令：有家室的父亲退出队伍。","en":"I order all fathers out of the ranks.","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-25-002","lineIndex":2,"speaker":"Enjolras","original":"Un père, ça sert vivant à ses enfants","ipa":"/œ̃ pɛʁ sa sɛʁ vivɑ̃ a sez ɑ̃fɑ̃/","zh":"父亲活着，才对孩子有用。","en":"A father is useful to his children alive.","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-25-003","lineIndex":3,"speaker":"Enjolras","original":"Je veux quatre volontaires","ipa":"/ʒə vø katʁ volɔ̃tɛʁ/","zh":"我要四名志愿者","en":"I want four volunteers","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-25-004","lineIndex":4,"speaker":"Enjolras","original":"Pour ramener des pavés","ipa":"/puʁ ʁamne de pave/","zh":"去搬回铺路石。","en":"To bring back paving stones","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-25-005","lineIndex":5,"speaker":"Enjolras","original":"Toi Feuilly, toi Combeferre","ipa":"/twa fœji twa kɔ̃bfɛʁ/","zh":"弗伊、孔白费尔","en":"You Feuilly, you Combeferre","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-25-006","lineIndex":6,"speaker":"Enjolras","original":"Non Joly, toi Bossuet","ipa":"/nɔ̃ ʒɔli twa bɔsyɛ/","zh":"不，乔利；博须埃，你去。","en":"No Joly, you Bossuet","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-25-007","lineIndex":7,"speaker":"Enjolras","original":"Il m'en reste encore un qui soit célibataire","ipa":"/il mɑ̃ ʁɛst ɑ̃kɔʁ œ̃ ki swa selibatɛʁ/","zh":"还差一个未婚的人。","en":"I still need one unmarried man.","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-25-008","lineIndex":8,"speaker":"Marius","original":"C'est à moi que revient la dernière cartouchière","ipa":"/sɛt a mwa kə ʁəvjɛ̃ la dɛʁnjɛʁ kaʁtuʃjɛʁ/","zh":"最后一条弹带是我的","en":"The last cartridge belt belongs to me","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-25-009","lineIndex":9,"speaker":"Enjolras","original":"Non, Marius, reste là, pour nous tu es marié","ipa":"/nɔ maʁjys ʁɛst la puʁ nu ty ɛ maʁje/","zh":"不，马吕斯，留下；在我们看来，你已经成家。","en":"No, Marius, stay there, for us you are married","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-25-010","lineIndex":10,"speaker":"Valjean","original":"Restez ici, jeune homme, puisqu'on vous le commande","ipa":"/ʁɛstez isi ʒøn ɔm pɥiskɔ̃ vu lə kɔmɑ̃d/","zh":"年轻人，既然他们命令你留下，就留下吧。","en":"Stay here, young man, since you are ordered to.","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-25-011","lineIndex":11,"speaker":"Valjean","original":"Et laissez-moi ma dernière croisade","ipa":"/e lɛsemwa ma dɛʁnjɛʁ kʁwazad/","zh":"把我最后这一场战役留给我。","en":"Leave me my last crusade.","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-25-012","lineIndex":12,"speaker":"Enjolras","original":"Hé d'où sort-il, celui-là","ipa":"/e du sɔʁil səlɥila/","zh":"嘿，这位是从哪儿冒出来的？","en":"Hey where does that one come from","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-25-013","lineIndex":13,"speaker":"Enjolras","original":"Hé Monsieur, qui êtes-vous","ipa":"/e məsjø ki ɛtvu/","zh":"嘿，先生，您是谁？","en":"Hey sir, who are you","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-25-014","lineIndex":14,"speaker":"Enjolras","original":"Et que faites-vous donc là?","ipa":"/e kə fɛtvu dɔ̃k la/","zh":"你在那里做什么？","en":"And what are you doing here?","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-25-015","lineIndex":15,"speaker":"Valjean","original":"J'ai rêvé cette nuit","ipa":"/ʒe ʁɛve sɛt nɥi/","zh":"我昨夜梦见","en":"I dreamed last night","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-25-016","lineIndex":16,"speaker":"Valjean","original":"Qu'on m'attendait ici","ipa":"/kɔ̃ matɑ̃dɛt isi/","zh":"有人在这里等我。","en":"That someone was waiting for me here","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-25-017","lineIndex":17,"speaker":"Valjean","original":"Je suis vieux, je suis seul","ipa":"/ʒə sɥi vjø ʒə sɥi sœl/","zh":"我老了，我孤身一人","en":"I am old, I am alone","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-25-018","lineIndex":18,"speaker":"Valjean","original":"Et je ne sers à rien","ipa":"/e ʒə nə sɛʁz a ʁjɛ̃/","zh":"而我却一无是处","en":"And I am of no use","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-25-019","lineIndex":19,"speaker":"Valjean","original":"Mieux vaux donner ma vie","ipa":"/mjø vo dɔne ma vi/","zh":"不如献出我的生命","en":"Better to give my life","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-25-020","lineIndex":20,"speaker":"Valjean","original":"Pour le progrès du genre humain","ipa":"/puʁ lə pʁɔɡʁɛ dy ʒɑ̃ʁ ymɛ̃/","zh":"为了人类的进步","en":"For the progress of the human race","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-25-021","lineIndex":21,"speaker":"Enjolras","original":"Vous me semblez sincère","ipa":"/vu mə sɑ̃ble sɛ̃sɛʁ/","zh":"您看起来是真心的。","en":"You seem sincere to me","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-25-022","lineIndex":22,"speaker":"Enjolras","original":"Oui, Monsieur, je vous crois","ipa":"/wi məsjø ʒə vu kʁwa/","zh":"是的，先生，我相信你","en":"Yes, Sir, I believe you","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-25-023","lineIndex":23,"speaker":"Enjolras","original":"Si vous êtes volontaire","ipa":"/si vuz ɛt volɔ̃tɛʁ/","zh":"若您愿意承担","en":"If you volunteer","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-25-024","lineIndex":24,"speaker":"Enjolras","original":"Pour cette mission-là","ipa":"/puʁ sɛt misjɔ̃la/","zh":"这项任务","en":"For this mission","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-25-025","lineIndex":25,"speaker":"Enjolras","original":"Quelles que soient vos raisons","ipa":"/kɛl kə swa vo ʁɛzɔ̃/","zh":"无论你的理由是什么","en":"Whatever your reasons","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-25-026","lineIndex":26,"speaker":"Enjolras","original":"Je vous en remercie","ipa":"/ʒə vuz ɑ̃ ʁəmɛʁsi/","zh":"我为此感谢你","en":"I thank you","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-25-027","lineIndex":27,"speaker":"Enjolras","original":"Vous qui sauvez la vie","ipa":"/vu ki sove la vi/","zh":"您救下了","en":"You who save the life","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-25-028","lineIndex":28,"speaker":"Enjolras","original":"De mon meilleur ami","ipa":"/də mɔ̃ mɛjœʁ ami/","zh":"我最好的朋友一命。","en":"of my best friend.","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-25-029","lineIndex":29,"speaker":"Valjean","original":"Ne me remerciez pas","ipa":"/nə mə ʁəmɛʁsje pa/","zh":"别谢我","en":"Don't thank me","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-25-030","lineIndex":30,"speaker":"Valjean","original":"Faites-moi une faveur","ipa":"/fɛtmwa yn favœʁ/","zh":"帮我一个忙","en":"Do me a favor","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-25-031","lineIndex":31,"speaker":"Enjolras","original":"Oui Monsieur","ipa":"/wi məsjø/","zh":"是的，先生","en":"Yes sir","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-25-032","lineIndex":32,"speaker":"Enjolras","original":"Dites-moi, laquelle?","ipa":"/ditmwa lakɛl/","zh":"请说，是什么忙？","en":"Tell me, which one?","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-25-033","lineIndex":33,"speaker":"Valjean","original":"Brûler de cet espion","ipa":"/bʁyle də sɛt ɛspjɔ̃/","zh":"把这个间谍的脑袋","en":"Burn this spy’s","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-25-034","lineIndex":34,"speaker":"Valjean","original":"Moi-même la cervelle","ipa":"/mwamɛm la sɛʁvɛl/","zh":"由我亲手打穿。","en":"brains myself.","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-25-035","lineIndex":35,"speaker":"Javert","original":"Quand tout va de travers","ipa":"/kɑ̃ tu va də tʁavɛʁ/","zh":"当一切出错时","en":"When everything goes wrong","note":"","sourceLineIndex":35},{"id":"les-miserables-1980-25-036","lineIndex":36,"speaker":"Javert","original":"La justice à l'envers","ipa":"/la ʒystis a lɑ̃vɛʁ/","zh":"正义逆转","en":"Justice in reverse","note":"","sourceLineIndex":36},{"id":"les-miserables-1980-25-037","lineIndex":37,"speaker":"Enjolras","original":"Eh bien nous sommes d'accord","ipa":"/ɛ bjɛ̃ nu sɔm dakɔʁ/","zh":"好吧，我们同意","en":"Well we agree","note":"","sourceLineIndex":37},{"id":"les-miserables-1980-25-038","lineIndex":38,"speaker":"Enjolras","original":"Le mouchard est à vous","ipa":"/lə muʃaʁ ɛt a vu/","zh":"这个告密者交给您。","en":"The snitch is yours","note":"","sourceLineIndex":38},{"id":"les-miserables-1980-25-039","lineIndex":39,"speaker":"Gavroche","original":"Alerte, un peloton de sapeurs","ipa":"/alɛʁt œ̃ pəlotɔ̃ də sapœʁ/","zh":"警报！一队工兵","en":"Alert, a squad of sappers","note":"","sourceLineIndex":39},{"id":"les-miserables-1980-25-040","lineIndex":40,"speaker":"Gavroche","original":"Va démolir la barricade","ipa":"/va demoliʁ la baʁikad/","zh":"要来拆路障","en":"Will demolish the barricade","note":"","sourceLineIndex":40},{"id":"les-miserables-1980-25-041","lineIndex":41,"speaker":"Gavroche","original":"Et les soldats derrière","ipa":"/e le sɔlda dɛʁjɛʁ/","zh":"后面的士兵","en":"And the soldiers behind","note":"","sourceLineIndex":41},{"id":"les-miserables-1980-25-042","lineIndex":42,"speaker":"Gavroche","original":"Se groupent en embuscade","ipa":"/sə ɡʁupt ɑ̃n ɑ̃byskad/","zh":"正在集结，准备伏击。","en":"Group in ambush","note":"","sourceLineIndex":42},{"id":"les-miserables-1980-25-043","lineIndex":43,"speaker":"Enjolras","original":"Tous dehors, amis fidèles","ipa":"/tus dəɔʁ ami fidɛl/","zh":"忠实的朋友们，全都出去！","en":"All outside, faithful friends","note":"","sourceLineIndex":43},{"id":"les-miserables-1980-25-044","lineIndex":44,"speaker":"Javert","original":"Et à tout à l'heure, au ciel","ipa":"/e a tut a lœʁ o sjɛl/","zh":"一会儿天上见。","en":"And see you later, in heaven","note":"","sourceLineIndex":44}],"sourceOrder":25,"displayOrder":25},{"order":26,"id":"26-noir-ou-blanc","title":"Noir ou blanc","titleZh":"黑白","lines":[{"id":"les-miserables-1980-26-001","lineIndex":1,"speaker":"Javert","original":"Je ne marche pas, la vertu d'un fonctionnaire","ipa":"/ʒə nə maʁʃ pa la vɛʁty dœ̃ fɔ̃ksjɔnɛʁ/","zh":"我绝不接受：一个公务员的德行","en":"I will not have it: a civil servant’s virtue","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-26-002","lineIndex":2,"speaker":"Javert","original":"Ne sera pas prise au piège de la vertu d'un forçat","ipa":"/nə səʁa pa pʁiz o pjɛʒ də la vɛʁty dœ̃ fɔʁsa/","zh":"不可能被一个苦役犯的“德行”困住。","en":"cannot be trapped by a convict’s virtue.","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-26-003","lineIndex":3,"speaker":"Javert","original":"Il n'y a que deux vérités, l'homme est soit bon, soit mauvais","ipa":"/il ni a kə dø veʁite lɔm ɛ swa bɔ̃ swa movɛ/","zh":"真理只有两个，人要么好，要么坏","en":"There are only two truths, man is either good or bad","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-26-004","lineIndex":4,"speaker":"Javert","original":"Mais, lui, qu'est-il, bon ou mauvais, faux ou vrai?","ipa":"/mɛ lɥi kɛtil bɔ̃ u movɛ fo u vʁɛ/","zh":"但他是什么，好还是坏，假还是真？","en":"But what is he, good or bad, false or true?","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-26-005","lineIndex":5,"speaker":"Javert","original":"Comme si le bien pouvait se servir du mal","ipa":"/kɔm si lə bjɛ̃ puvɛ sə sɛʁviʁ dy mal/","zh":"仿佛善可以借恶来行事","en":"As if good could make use of evil","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-26-006","lineIndex":6,"speaker":"Javert","original":"Pour faire douter un juste et pour torturer son âme","ipa":"/puʁ fɛʁ dute œ̃ ʒyst e puʁ tɔʁtyʁe sɔ̃n am/","zh":"让正义的人怀疑并折磨他的灵魂","en":"To make a righteous man doubt and to torture his soul","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-26-007","lineIndex":7,"speaker":"Javert","original":"Je ne veux pas la proie du doute","ipa":"/ʒə nə vø pa la pʁwa dy dut/","zh":"我不想成为怀疑的牺牲品","en":"I do not want to fall prey to doubt","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-26-008","lineIndex":8,"speaker":"Javert","original":"Cet accident ne peut dévier ma route","ipa":"/sɛt aksidɑ̃ nə pø devje ma ʁut/","zh":"这场意外无法改变我的道路","en":"This accident cannot deviate from my path","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-26-009","lineIndex":9,"speaker":"Javert","original":"Il n'y a que deux sortes d'homme et pas d'autre","ipa":"/il ni a kə dø sɔʁt dɔm e pa dotʁ/","zh":"人只有两种，别无其他。","en":"There are only two kinds of men, no others.","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-26-010","lineIndex":10,"speaker":"Javert","original":"Une pour subir et une autre pour sévir","ipa":"/yn puʁ sybiʁ e yn otʁ puʁ seviʁ/","zh":"一种承受，一种惩治。","en":"one to suffer, the other to punish.","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-26-011","lineIndex":11,"speaker":"Javert","original":"Noir ou blanc, dehors la loi ou dedans","ipa":"/nwaʁ u blɑ̃ dəɔʁ la lwa u dədɑ̃/","zh":"黑与白，法律之外还是法律内部","en":"Black or white, outside the law or inside","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-26-012","lineIndex":12,"speaker":"Javert","original":"Noir ou blanc, c'est Javert ou Valjean","ipa":"/nwaʁ u blɑ̃ sɛ ʒavɛʁ u valʒɑ̃/","zh":"黑与白，是沙威还是冉阿让","en":"Black or white, it's Javert or Valjean","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-26-013","lineIndex":13,"speaker":"Javert","original":"Pourquoi ai-je permis à cet homme","ipa":"/puʁkwa ɛʒ pɛʁmi a sɛt ɔm/","zh":"我为什么允许这个人","en":"Why did I allow this man","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-26-014","lineIndex":14,"speaker":"Javert","original":"De me laisser vivre après lui?","ipa":"/də mə lɛse vivʁ apʁɛ lɥi/","zh":"在饶我一命后离开？","en":"to let me live after him?","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-26-015","lineIndex":15,"speaker":"Javert","original":"Sa voix bat comme un métronome","ipa":"/sa vwa ba kɔm œ̃ metʁonom/","zh":"他的声音像节拍器一样跳动","en":"His voice beats like a metronome","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-26-016","lineIndex":16,"speaker":"Javert","original":"En moi, dit-il vrai ou a-t-il menti?","ipa":"/ɑ̃ mwa ditil vʁɛ u atil mɑ̃ti/","zh":"他在我心里说的是真话，还是谎言？","en":"Within me, did he speak truth or lie?","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-26-017","lineIndex":17,"speaker":"Javert","original":"J'avais le droit d'être tué et d'exiger","ipa":"/ʒavɛ lə dʁwa dɛtʁ tye e dɛɡziʒe/","zh":"我本有权被杀，也有权要求","en":"I had the right to be killed and to demand","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-26-018","lineIndex":18,"speaker":"Javert","original":"Qu'on me fusille de force sur l'heure","ipa":"/kɔ̃ mə fyzij də fɔʁs syʁ lœʁ/","zh":"立刻强行将我枪决。","en":"that I be shot at once by force.","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-26-019","lineIndex":19,"speaker":"Javert","original":"Pour ne pas voir Satan vainqueur","ipa":"/puʁ nə pa vwaʁ satɑ̃ vɛ̃kœʁ/","zh":"以免看到撒旦的胜利","en":"So as not to see Satan victorious","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-26-020","lineIndex":20,"speaker":"Javert","original":"Le pardon pour la haine","ipa":"/lə paʁdɔ̃ puʁ la ɛn/","zh":"用宽恕对待仇恨","en":"Forgiveness for hatred","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-26-021","lineIndex":21,"speaker":"Javert","original":"Malfaiteur bienfaisant","ipa":"/malfɛtœʁ bjɛ̃fəzɑ̃/","zh":"让恶徒行善","en":"a beneficent criminal—","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-26-022","lineIndex":22,"speaker":"Javert","original":"C'est ainsi qu'on gangrène","ipa":"/sɛt ɛ̃si kɔ̃ ɡɑ̃ɡʁɛn/","zh":"这正是让……腐烂的办法","en":"this is how one corrupts","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-26-023","lineIndex":23,"speaker":"Javert","original":"L'État et ces agents","ipa":"/leta e sez aʒɑ̃/","zh":"国家及其执法者。","en":"the State and its agents.","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-26-024","lineIndex":24,"speaker":"Javert","original":"Être de granit et douter","ipa":"/ɛtʁ də ɡʁanit e dute/","zh":"成为花岗岩并怀疑","en":"To be made of granite and doubt","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-26-025","lineIndex":25,"speaker":"Javert","original":"Être chien de garde et lécher","ipa":"/ɛtʁ ʃjɛ̃ də ɡaʁd e leʃe/","zh":"做看门狗却去舔","en":"To be a watchdog and lick","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-26-026","lineIndex":26,"speaker":"Javert","original":"Être de glace et se voir fondre","ipa":"/ɛtʁ də ɡlas e sə vwaʁ fɔ̃dʁ/","zh":"本是冰，却看着自己融化","en":"to be ice and see oneself melt","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-26-027","lineIndex":27,"speaker":"Javert","original":"Être le rempart au feu qui s'effondre","ipa":"/ɛtʁ lə ʁɑ̃paʁ o fø ki sefɔ̃dʁ/","zh":"成为一座在烈火中崩塌的堡垒。","en":"to be a bulwark collapsing in the fire.","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-26-028","lineIndex":28,"speaker":"Javert","original":"Je cherche et ne retrouve plus","ipa":"/ʒə ʃɛʁʃ e nə ʁətʁuv ply/","zh":"我寻找，却再也找不回","en":"I search and no longer find","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-26-029","lineIndex":29,"speaker":"Javert","original":"Qu'étais-je donc?","ipa":"/ketɛʒ dɔ̃k/","zh":"从前的自己。","en":"What was I then?","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-26-030","lineIndex":30,"speaker":"Javert","original":"Que suis-je encore et quel démon","ipa":"/kə sɥiʒ ɑ̃kɔʁ e kɛl demɔ̃/","zh":"我如今又是什么？是哪个恶魔","en":"What am I again and what demon","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-26-031","lineIndex":31,"speaker":"Javert","original":"Se joue de moi à mon insu?","ipa":"/sə ʒu də mwa a mɔ̃n ɛ̃sy/","zh":"正在我毫无察觉时戏弄我？","en":"Is playing on me without my knowledge?","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-26-032","lineIndex":32,"speaker":"Javert","original":"Je lâche prise, je me noie","ipa":"/ʒə laʃ pʁiz ʒə mə nwa/","zh":"我放手，我溺水","en":"I let go, I drown","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-26-033","lineIndex":33,"speaker":"Javert","original":"Tout à coup comme il fait froid","ipa":"/tut a ku kɔm il fɛ fʁwa/","zh":"突然就冷了","en":"Suddenly how cold it is","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-26-034","lineIndex":34,"speaker":"Javert","original":"Quand je regarde vers le fond","ipa":"/kɑ̃ ʒə ʁəɡaʁd vɛʁ lə fɔ̃/","zh":"当我低头看时","en":"When I look down","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-26-035","lineIndex":35,"speaker":"Javert","original":"Je ne vois que tourbillons","ipa":"/ʒə nə vwa kə tuʁbijɔ̃/","zh":"我只看到漩涡","en":"I only see whirlpools","note":"","sourceLineIndex":35},{"id":"les-miserables-1980-26-036","lineIndex":36,"speaker":"Javert","original":"Je préfère quitter ce monde","ipa":"/ʒə pʁefɛʁ kite sə mɔ̃d/","zh":"我宁愿离开这个世界","en":"I prefer to leave this world","note":"","sourceLineIndex":36},{"id":"les-miserables-1980-26-037","lineIndex":37,"speaker":"Javert","original":"Qui tolère les Valjean","ipa":"/ki tolɛʁ le valʒɑ̃/","zh":"一个容得下冉阿让这种人的世界","en":"that tolerates men like Valjean","note":"","sourceLineIndex":37},{"id":"les-miserables-1980-26-038","lineIndex":38,"speaker":"Javert","original":"Et où Javert volerait","ipa":"/e u ʒavɛʁ volʁɛ/","zh":"而沙威却要盗取","en":"and where Javert would steal","note":"","sourceLineIndex":38},{"id":"les-miserables-1980-26-039","lineIndex":39,"speaker":"Javert","original":"Le pain du gouvernement","ipa":"/lə pɛ̃ dy ɡuvɛʁnəmɑ̃/","zh":"政府的口粮。","en":"the government's bread.","note":"","sourceLineIndex":39}],"sourceOrder":26,"displayOrder":26},{"order":27,"id":"27-la-mort-de-gavroche","title":"La Mort de Gavroche","titleZh":"加弗罗什之死","lines":[{"id":"les-miserables-1980-27-001","lineIndex":1,"speaker":"Gavroche","original":"Cette fois, Javert, t'arrêteras plus personne","ipa":"/sɛt fwa ʒavɛʁ taʁɛtʁa ply pɛʁsɔn/","zh":"这回，沙威，你再也拦不住任何人了。","en":"This time, Javert, you won't stop anyone anymore.","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-27-002","lineIndex":2,"speaker":"Gavroche","original":"La mort t'a coffré à perpétuité","ipa":"/la mɔʁ ta kɔfʁe a pɛʁpetɥite/","zh":"死亡已经把你终身关进牢里。","en":"Death has locked you up for life.","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-27-003","lineIndex":3,"speaker":"Gavroche","original":"J'espère qu'là-haut, on s'ra pas dans l'même cachot","ipa":"/ʒɛspɛʁ k la o ɔ̃ sʁa pa dɑ̃ lmɛm kaʃo/","zh":"我希望到了上头，我们不会关在同一间牢房。","en":"I hope that up there we won't be in the same cell.","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-27-004","lineIndex":4,"speaker":"Gavroche","original":"Sur terre déjà, on n'était pas du même combat","ipa":"/syʁ tɛʁ deʒa ɔ̃ netɛ pa dy mɛm kɔ̃ba/","zh":"在人世间，我们本来就不是一条战线上的。","en":"Down here, we were never on the same side.","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-27-005","lineIndex":5,"speaker":"Courfeyrac","original":"Sacré Gavroche, t'as toujours l'mot pour rire","ipa":"/sakʁe ɡavʁɔʃ ta tuʒuʁ lmo puʁ ʁiʁ/","zh":"好个加弗罗什，你总有逗人笑的话。","en":"Dear Gavroche, you always have a quip.","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-27-006","lineIndex":6,"speaker":"Courfeyrac","original":"C'est pas la parlotte qui te f'ra guérir","ipa":"/sɛ pa la paʁlɔt ki tə fʁa ɡeʁiʁ/","zh":"说话并不能治愈你","en":"It's not talking that will make you heal","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-27-007","lineIndex":7,"speaker":"Marius","original":"Ah les salauds, ils ont tiré sur un enfant","ipa":"/a le salo ilz ɔ̃ tiʁe syʁ œ̃n ɑ̃fɑ̃/","zh":"啊，这些混蛋，他们向一个孩子开枪！","en":"Ah, the bastards—they shot at a child!","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-27-008","lineIndex":8,"speaker":"Marius","original":"Ils ont, sans savoir, abattu le printemps","ipa":"/ilz ɔ̃ sɑ̃ savwaʁ abaty lə pʁɛ̃tɑ̃/","zh":"他们自己都不知道，竟击倒了春天。","en":"Without knowing it, they have cut down spring itself.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-27-009","lineIndex":9,"speaker":"Marius","original":"Quel Dieu cruel s'abreuve du sang des innocents","ipa":"/kɛl djø kʁyɛl sabʁøv dy sɑ̃ dez inosɑ̃/","zh":"是怎样残酷的神，饮着无辜者的血？","en":"What cruel God drinks the blood of the innocent?","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-27-010","lineIndex":10,"speaker":"Marius","original":"Et combien faudra-t-il pleurer d'combattants?","ipa":"/e kɔ̃bjɛ̃ fodʁatil pløʁe dkɔ̃batɑ̃/","zh":"我们还要为多少战士落泪？","en":"And how many fighters must we still mourn?","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-27-011","lineIndex":11,"speaker":"Gavroche","original":"Notre drapeau était par terre","ipa":"/notʁ dʁapo etɛ paʁ tɛʁ/","zh":"我们的旗帜倒在地上","en":"Our flag lay on the ground","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-27-012","lineIndex":12,"speaker":"Gavroche","original":"Rouge de honte et bleu sali","ipa":"/ʁuʒ də ɔ̃t e blø sali/","zh":"红色蒙羞，蓝色染污。","en":"its red shamed and its blue soiled.","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-27-013","lineIndex":13,"speaker":"Gavroche","original":"Moi, j'ai bondi blanc de colère","ipa":"/mwa ʒe bɔ̃di blɑ̃ də kolɛʁ/","zh":"我气得脸色苍白","en":"I jumped up, white with anger","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-27-014","lineIndex":14,"speaker":"Gavroche","original":"Allons, enfants de la patrie","ipa":"/alɔ̃ ɑ̃fɑ̃ də la patʁi/","zh":"加油，祖国的孩子们","en":"Come on, children of the homeland","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-27-015","lineIndex":15,"speaker":"Gavroche","original":"Un mec m'a vu, qui m'a crié: \"Qu'il vive!\"","ipa":"/œ̃ mɛk ma vy ki ma kʁie kil viv/","zh":"有人看见我，冲我喊：“愿他活着！”","en":"Some fellow saw me and shouted, “May he live!”","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-27-016","lineIndex":16,"speaker":"Gavroche","original":"J'ai dit: \"Révolution française\"","ipa":"/ʒe di ʁevolysjɔ̃ fʁɑ̃sɛz/","zh":"我回他：“法国大革命！”","en":"I answered, “French Revolution!”","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-27-017","lineIndex":17,"speaker":"Gavroche","original":"Ça lui a pas plu ma franchise","ipa":"/sa lɥi a pa ply ma fʁɑ̃ʃiz/","zh":"他不喜欢我的直率","en":"He did not like my frankness","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-27-018","lineIndex":18,"speaker":"Gavroche","original":"M'a mis un pruneau dans la fraise","ipa":"/ma mi œ̃ pʁyno dɑ̃ la fʁɛz/","zh":"就往我脸上赏了一颗子弹。","en":"so he put a bullet in my face.","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-27-019","lineIndex":19,"speaker":"Gavroche","original":"C'est comme ça, on gagne pas à chaque fois","ipa":"/sɛ kɔm sa ɔ̃ ɡaɲ paz a ʃak fwa/","zh":"就是这样，我们不是每次都赢","en":"That's how it is, we don't win every time","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-27-020","lineIndex":20,"speaker":"Gavroche","original":"Donnez, donnez, ma casquette aux copains","ipa":"/dɔne dɔne ma kaskɛt o kopɛ̃/","zh":"把我的帽子交给伙伴们。","en":"Give my cap to my friends.","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-27-021","lineIndex":21,"speaker":"Gavroche","original":"C'est tout ce que j'ai et j'en n'ai plus besoin","ipa":"/sɛ tu sə kə ʒe e ʒɑ̃ ne ply bəzwɛ̃/","zh":"这是我所拥有的一切，我不再需要它","en":"It's all I have and I don't need it anymore","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-27-022","lineIndex":22,"speaker":"Gavroche","original":"Je suis tombé par terre","ipa":"/ʒə sɥi tɔ̃be paʁ tɛʁ/","zh":"我摔倒在地","en":"I fell to the ground","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-27-023","lineIndex":23,"speaker":"Gavroche","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"这是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-27-024","lineIndex":24,"speaker":"Gavroche","original":"Le nez dans le ruisseau","ipa":"/lə ne dɑ̃ lə ʁyiso/","zh":"鼻子在溪流中","en":"Nose in the stream","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-27-025","lineIndex":25,"speaker":"Gavroche","original":"C'est la faute à...","ipa":"/sɛ la fot a/","zh":"这是...的错","en":"It's the fault of...","note":"","sourceLineIndex":25}],"sourceOrder":27,"displayOrder":27},{"order":28,"id":"28-marius-et-monsieur-gillenormand","title":"Marius et Monsieur Gillenormand","titleZh":"马吕斯和吉诺曼先生","lines":[{"id":"les-miserables-1980-28-001","lineIndex":1,"speaker":"Marius","original":"Grand-père, vous m'avez pardonné","ipa":"/ɡʁɑ̃pɛʁ vu mave paʁdɔne/","zh":"祖父，你原谅了我","en":"Grandpa, you have forgiven me","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-28-002","lineIndex":2,"speaker":"Marius","original":"Ma fugue et mes idées","ipa":"/ma fyɡ e mez ide/","zh":"我的逃跑和我的想法","en":"My escape and my ideas","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-28-003","lineIndex":3,"speaker":"Marius","original":"En moi, pourtant rien n'a changé","ipa":"/ɑ̃ mwa puʁtɑ̃ ʁjɛ̃ na ʃɑ̃ʒe/","zh":"在我身上，什么都没有改变","en":"In me, however, nothing has changed","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-28-004","lineIndex":4,"speaker":"Marius","original":"Sinon que vous m'aimez","ipa":"/sinɔ̃ kə vu mɛme/","zh":"否则你爱我","en":"Except that you love me","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-28-005","lineIndex":5,"speaker":"Monsieur Gillenormand","original":"C'est toi qui dois me pardonner","ipa":"/sɛ twa ki dwa mə paʁdɔne/","zh":"你必须原谅我","en":"It is you who must forgive me","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-28-006","lineIndex":6,"speaker":"Monsieur Gillenormand","original":"Le mal que je t'ai fait","ipa":"/lə mal kə ʒə te fɛ/","zh":"我对你造成的伤害","en":"The harm that I have done to you","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-28-007","lineIndex":7,"speaker":"Monsieur Gillenormand","original":"Trop vieux pour vivre un idéal","ipa":"/tʁo vjø puʁ vivʁ œ̃n ideal/","zh":"太老了，无法实现理想","en":"Too old to live an ideal","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-28-008","lineIndex":8,"speaker":"Monsieur Gillenormand","original":"Mais j'aime comme tu en parles","ipa":"/mɛ ʒɛm kɔm ty ɑ̃ paʁl/","zh":"但我喜欢你谈论它的方式","en":"But I love the way you talk about it","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-28-009","lineIndex":9,"speaker":"Monsieur Gillenormand et Marius","original":"Comme un seul cœur dans deux poitrines","ipa":"/kɔm œ̃ sœl kœʁ dɑ̃ dø pwatʁin/","zh":"就像两个胸膛里唯一的一颗心","en":"Like one heart in two chests","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-28-010","lineIndex":10,"speaker":"Monsieur Gillenormand et Marius","original":"Que notre amour serve d'idéal","ipa":"/kə notʁ amuʁ sɛʁv dideal/","zh":"愿我们的爱成为理想","en":"May our love serve as an ideal","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-28-011","lineIndex":11,"speaker":"Monsieur Gillenormand et Marius","original":"Et notre seule politique","ipa":"/e notʁ sœl politik/","zh":"我们唯一的政策","en":"And our only policy","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-28-012","lineIndex":12,"speaker":"Monsieur Gillenormand et Marius","original":"Sera désormais familiale","ipa":"/səʁa dezɔʁmɛ familjal/","zh":"从此成为一家人","en":"Will henceforth be family","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-28-013","lineIndex":13,"speaker":"Monsieur Gillenormand et Marius","original":"Et nous la garderons du mal","ipa":"/e nu la ɡaʁdəʁɔ̃ dy mal/","zh":"我们会让她远离邪恶","en":"And we will guard it from harm","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-28-014","lineIndex":14,"speaker":"Monsieur Gillenormand et Marius","original":"Nous lutterons tous deux pour elle","ipa":"/nu lytʁɔ̃ tus dø puʁ ɛl/","zh":"我们都会为她而战","en":"We will both fight for her","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-28-015","lineIndex":15,"speaker":"Monsieur Gillenormand et Marius","original":"Et sa vie toujours comme au bal","ipa":"/e sa vi tuʒuʁ kɔm o bal/","zh":"她的一生都会如同舞会一般","en":"and her life, ever like a ball","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-28-016","lineIndex":16,"speaker":"Monsieur Gillenormand et Marius","original":"Tournoiera parmi des dentelles","ipa":"/tuʁnwaʁa paʁmi de dɑ̃tɛl/","zh":"在蕾丝间轻盈旋转","en":"will whirl among lace","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-28-017","lineIndex":17,"speaker":"Monsieur Gillenormand et Marius","original":"Qu'un violon brode dans le ciel","ipa":"/kœ̃ vjolɔ̃ bʁɔd dɑ̃ lə sjɛl/","zh":"小提琴在天空织出旋律。","en":"that a violin embroiders in the sky.","note":"","sourceLineIndex":17}],"sourceOrder":28,"displayOrder":28},{"order":29,"id":"29-le-mariage-soyez-heureux","title":"Le Mariage, “soyez heureux”","titleZh":"婚姻，“幸福”","lines":[{"id":"les-miserables-1980-29-001","lineIndex":1,"speaker":"Les Invités","original":"A-t-on jamais vu mariée si jolie?","ipa":"/atɔ̃ ʒamɛ vy maʁje si ʒoli/","zh":"我们见过这么漂亮的新娘吗？","en":"Has anyone ever seen a bride so pretty?","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-29-002","lineIndex":2,"speaker":"Les Invités","original":"A-t-on jamais vu noce plus réussie?","ipa":"/atɔ̃ ʒamɛ vy nɔs ply ʁeysi/","zh":"我们见过比这更成功的婚礼吗？","en":"Have we ever seen a more successful wedding?","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-29-003","lineIndex":3,"speaker":"La Famille","original":"C'est bon d'avoir ses amis près de soi","ipa":"/sɛ bɔ̃ davwaʁ sez ami pʁɛ də swa/","zh":"有朋友在身边真好","en":"It's good to have your friends close to you","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-29-004","lineIndex":4,"speaker":"Les Invités","original":"Soyez heureux, chérissez-vous toujours","ipa":"/swajez øʁø ʃeʁisevu tuʒuʁ/","zh":"要快乐，永远珍惜彼此","en":"Be happy, always cherish each other","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-29-005","lineIndex":5,"speaker":"Les Invités","original":"Et faites-nous des enfants de l'amour","ipa":"/e fɛtnu dez ɑ̃fɑ̃ də lamuʁ/","zh":"也给我们添些爱的孩子吧。","en":"And give us children born of love.","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-29-006","lineIndex":6,"speaker":"Les Mariés","original":"Comme c'est gentil à vous d'être tous là","ipa":"/kɔm sɛ ʒɑ̃ti a vu dɛtʁ tus la/","zh":"你们在这里真好","en":"How nice of you all to be here","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-29-007","lineIndex":7,"speaker":"Les Invités","original":"Soyez heureux, chérissez-vous toujours","ipa":"/swajez øʁø ʃeʁisevu tuʒuʁ/","zh":"要快乐，永远珍惜彼此","en":"Be happy, always cherish each other","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-29-008","lineIndex":8,"speaker":"Les Invités","original":"Et faites-nous des enfants de l'amour","ipa":"/e fɛtnu dez ɑ̃fɑ̃ də lamuʁ/","zh":"也给我们添些爱的孩子吧。","en":"And give us children born of love.","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-29-009","lineIndex":9,"speaker":"Les Invités","original":"Soyez heureux, chérissez-vous toujours","ipa":"/swajez øʁø ʃeʁisevu tuʒuʁ/","zh":"要快乐，永远珍惜彼此","en":"Be happy, always cherish each other","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-29-010","lineIndex":10,"speaker":"Les Invités","original":"Et faites-nous des enfants de l'amour","ipa":"/e fɛtnu dez ɑ̃fɑ̃ də lamuʁ/","zh":"也给我们添些爱的孩子吧。","en":"And give us children born of love.","note":"","sourceLineIndex":10}],"sourceOrder":29,"displayOrder":29},{"order":30,"id":"30-l-aveu-de-jean-valjean","title":"L'Aveu de Jean Valjean","titleZh":"冉阿让的自白","lines":[{"id":"les-miserables-1980-30-001","lineIndex":1,"speaker":"Marius","original":"Mon père, comme je vous aime d'aimer autant Cosette","ipa":"/mɔ̃ pɛʁ kɔm ʒə vuz ɛm dɛme otɑ̃ kozɛt/","zh":"我的父亲，我多么爱你，因为你如此爱着珂赛特","en":"My father, how I love you for loving Cosette so much","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-30-002","lineIndex":2,"speaker":"Marius","original":"Vous ne la perdez pas et vous gagnez un fils","ipa":"/vu nə la pɛʁde paz e vu ɡanjez œ̃ fis/","zh":"你不要失去她，你会得到一个儿子","en":"You don't lose her and you gain a son","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-30-003","lineIndex":3,"speaker":"Marius","original":"Car dans cette maison, votre chambre est toute prête","ipa":"/kaʁ dɑ̃ sɛt mɛzɔ̃ votʁ ʃɑ̃bʁ ɛ tut pʁɛt/","zh":"因为在这个房子里，你的房间已经准备好了","en":"Because in this house, your room is ready","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-30-004","lineIndex":4,"speaker":"Marius","original":"Et dès demain matin, chez nous sera chez vous","ipa":"/e dɛ dəmɛ̃ matɛ̃ ʃe nu səʁa ʃe vu/","zh":"从明天早晨起，我们的家就是您的家。","en":"From tomorrow morning, our home will be your home.","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-30-005","lineIndex":5,"speaker":"Valjean","original":"Si je me tais, je me damne","ipa":"/si ʒə mə tɛ ʒə mə dan/","zh":"如果我沉默，我便会自我堕入地狱。","en":"If I keep silent, I'll damn myself","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-30-006","lineIndex":6,"speaker":"Valjean","original":"Si je parle, c'est moi qui me condamne","ipa":"/si ʒə paʁl sɛ mwa ki mə kɔ̃dan/","zh":"如果我开口，便是亲手定自己的罪。","en":"If I speak, it's me who condemns myself","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-30-007","lineIndex":7,"speaker":"Valjean","original":"Monsieur, je ne veux pas usurper votre toit","ipa":"/məsjø ʒə nə vø paz yzyʁpe votʁ twa/","zh":"先生，我不愿冒充有资格留在您家的人。","en":"Sir, I do not want to usurp a place under your roof.","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-30-008","lineIndex":8,"speaker":"Valjean","original":"Je suis ancien forçat, mais la dot de Cosette","ipa":"/ʒə sɥiz ɑ̃sjɛ̃ fɔʁsa mɛ la dɔt də kozɛt/","zh":"我是一名前罪犯，但珂赛特的嫁妆","en":"I am a former convict, but Cosette's dowry","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-30-009","lineIndex":9,"speaker":"Valjean","original":"Est un argent honnête","ipa":"/ɛt œ̃n aʁʒɑ̃ ɔnɛt/","zh":"是诚实的钱","en":"Is honest money","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-30-010","lineIndex":10,"speaker":"Valjean","original":"Cosette n'est pas ma fille, mais je l'ai recueillie","ipa":"/kozɛt nɛ pa ma fij mɛ ʒə le ʁəkœji/","zh":"珂赛特不是我的女儿，但我收留了她","en":"Cosette is not my daughter, but I took her in","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-30-011","lineIndex":11,"speaker":"Valjean","original":"Comme j'en ai fait serment à sa mère, dans le temps","ipa":"/kɔm ʒɑ̃n e fɛ sɛʁmɑ̃ a sa mɛʁ dɑ̃ lə tɑ̃/","zh":"多年前我曾向她母亲发过誓","en":"as I once swore to her mother.","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-30-012","lineIndex":12,"speaker":"Valjean","original":"Et je vous la rends","ipa":"/e ʒə vu la ʁɑ̃/","zh":"如今我把她交还给您。","en":"And I give her to you.","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-30-013","lineIndex":13,"speaker":"Valjean","original":"Si je me tais, je me damne","ipa":"/si ʒə mə tɛ ʒə mə dan/","zh":"如果我沉默，我便会自我堕入地狱。","en":"If I keep silent, I'll damn myself","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-30-014","lineIndex":14,"speaker":"Valjean","original":"Si je parle, c'est moi qui me condamne","ipa":"/si ʒə paʁl sɛ mwa ki mə kɔ̃dan/","zh":"如果我开口，便是亲手定自己的罪。","en":"If I speak, it's me who condemns myself","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-30-015","lineIndex":15,"speaker":"Marius","original":"Qu'est-ce que cela veut dire?","ipa":"/kɛskə səla vø diʁ/","zh":"这是什么意思？","en":"What does that mean?","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-30-016","lineIndex":16,"speaker":"Marius","original":"Mais vous me rendez fou!","ipa":"/mɛ vu mə ʁɑ̃de fu/","zh":"但你快把我逼疯了！","en":"But you're driving me crazy!","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-30-017","lineIndex":17,"speaker":"Marius","original":"Dites-moi que je rêve et que ce n'est pas vous","ipa":"/ditmwa kə ʒə ʁɛv e kə sə nɛ pa vu/","zh":"告诉我我在做梦，而且不是你","en":"Tell me I'm dreaming and it's not you","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-30-018","lineIndex":18,"speaker":"Marius","original":"Si tout ceci est vrai, pourquoi me l'avouer","ipa":"/si tu səsi ɛ vʁɛ puʁkwa mə lavwe/","zh":"如果这一切都是真的，为什么要告诉我","en":"If all this is true, why tell me","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-30-019","lineIndex":19,"speaker":"Marius","original":"Et n'avoir pas gardé pour vous votre secret?","ipa":"/e navwaʁ pa ɡaʁde puʁ vu votʁ səkʁɛ/","zh":"并且不保守秘密？","en":"And not keep your secret to yourself?","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-30-020","lineIndex":20,"speaker":"Marius","original":"Qu'est-ce qui vous a forcé à parler?","ipa":"/kɛs ki vuz a fɔʁse a paʁle/","zh":"是什么迫使你开口说话？","en":"What forced you to speak?","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-30-021","lineIndex":21,"speaker":"Valjean","original":"Je ne suis plus dénoncé, poursuivi, ni mis en quarantaine","ipa":"/ʒə nə sɥi ply denɔ̃se puʁsɥivi ni mi ɑ̃ kaʁɑ̃tɛn/","zh":"我早已不再遭人告发、追捕或隔绝。","en":"I am no longer denounced, pursued, or quarantined","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-30-022","lineIndex":22,"speaker":"Valjean","original":"Sinon que par ma mémoire qui me barre le passage à moi-même","ipa":"/sinɔ̃ kə paʁ ma memwaʁ ki mə baʁ lə pasaʒ a mwamɛm/","zh":"只有记忆仍横在我面前，使我无法面对自己。","en":"Except by my memory which blocks the passage to myself","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-30-023","lineIndex":23,"speaker":"Valjean","original":"Si je me tais, je me damne","ipa":"/si ʒə mə tɛ ʒə mə dan/","zh":"如果我沉默，我便会自我堕入地狱。","en":"If I keep silent, I'll damn myself","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-30-024","lineIndex":24,"speaker":"Valjean","original":"Si je parle, il faut que je me condamne","ipa":"/si ʒə paʁl il fo kə ʒə mə kɔ̃dan/","zh":"如果我开口，就必须亲手定自己的罪。","en":"If I speak, I must condemn myself","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-30-025","lineIndex":25,"speaker":"Marius","original":"Vous, un forçat qui avez combattu près de moi","ipa":"/vu œ̃ fɔʁsa ki ave kɔ̃baty pʁɛ də mwa/","zh":"你，一个与我并肩作战的囚犯","en":"You, a convict who fought alongside me","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-30-026","lineIndex":26,"speaker":"Marius","original":"Pauvre Cosette, comment lui expliquer tout cela","ipa":"/povʁ kozɛt kɔmɑ̃ lɥi ɛksplike tu səla/","zh":"可怜的珂赛特，我该如何向她解释这一切","en":"Poor Cosette, how can I explain all this to her","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-30-027","lineIndex":27,"speaker":"Valjean","original":"Non jurez-moi de ne jamais trahir mon secret","ipa":"/nɔ̃ ʒyʁemwa də nə ʒamɛ tʁaiʁ mɔ̃ səkʁɛ/","zh":"不，向我发誓永远不会泄露我的秘密","en":"No, swear to me never to betray my secret","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-30-028","lineIndex":28,"speaker":"Marius","original":"C'est bien juré","ipa":"/sɛ bjɛ̃ ʒyʁe/","zh":"我已经发誓了","en":"It's well sworn","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-30-029","lineIndex":29,"speaker":"Valjean","original":"À présent, croyez-vous que je n'doive plus la voir?","ipa":"/a pʁezɑ̃ kʁwajevu kə ʒə ndwav ply la vwaʁ/","zh":"现在，你认为我不应该再见到她吗？","en":"Now, do you think I should no longer see her?","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-30-030","lineIndex":30,"speaker":"Marius","original":"Oui Monsieur, je crois que ce s'rait mieux","ipa":"/wi məsjø ʒə kʁwa kə sə sʁɛ mjø/","zh":"是的，先生，我想这样会更好","en":"Yes Sir, I think it would be better","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-30-031","lineIndex":31,"speaker":"Valjean","original":"Adieu!","ipa":"/adjø/","zh":"再见！","en":"Farewell!","note":"","sourceLineIndex":31}],"sourceOrder":30,"displayOrder":30},{"order":31,"id":"31-marchandage-et-revelation","title":"Marchandage et révélation","titleZh":"讨价还价和启示","lines":[{"id":"les-miserables-1980-31-001","lineIndex":1,"speaker":"Madame Thénardier","original":"Oui, monsieur, c'est ainsi","ipa":"/wi məsjø sɛt ɛ̃si/","zh":"是的，先生，就是这样","en":"Yes, sir, that's how","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-31-002","lineIndex":2,"speaker":"Madame Thénardier","original":"La misère nous tient à sa merci","ipa":"/la mizɛʁ nu tjɛ̃t a sa mɛʁsi/","zh":"苦难把我们攥在掌心，任意摆布。","en":"Poverty has us at its mercy","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-31-003","lineIndex":3,"speaker":"Thénardier","original":"Et d'ailleurs vot'bon cœur","ipa":"/e dajœʁ vɔ bɔ̃ kœʁ/","zh":"而且，你的好心","en":"And besides, your good heart","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-31-004","lineIndex":4,"speaker":"Thénardier","original":"Va pouvoir s'exercer tout à l'heure","ipa":"/va puvwaʁ sɛɡzɛʁse tut a lœʁ/","zh":"很快就有机会发挥了。","en":"will soon have a chance to show itself.","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-31-005","lineIndex":5,"speaker":"Thénardier","original":"En sachant qu'un forçat","ipa":"/ɑ̃ saʃɑ̃ kœ̃ fɔʁsa/","zh":"知道一个罪犯","en":"Knowing that a convict","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-31-006","lineIndex":6,"speaker":"Thénardier","original":"Vit à votre insu sous votre toit","ipa":"/vi a votʁ ɛ̃sy su votʁ twa/","zh":"在你不知情的情况下生活在你的屋檐下","en":"Lives without your knowledge under your roof","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-31-007","lineIndex":7,"speaker":"Marius","original":"Oui, je sais, mon beau-père","ipa":"/wi ʒə sɛ mɔ̃ bopɛʁ/","zh":"是的，我知道，我的岳父","en":"Yes, I know, my father-in-law","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-31-008","lineIndex":8,"speaker":"Marius","original":"A tué Madeleine et Javert","ipa":"/a tye madlɛn e ʒavɛʁ/","zh":"杀死了马德兰和沙威。","en":"Killed Madeleine and Javert","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-31-009","lineIndex":9,"speaker":"Thénardier","original":"Non, monsieur, pas Javert","ipa":"/nɔ̃ məsjø pa ʒavɛʁ/","zh":"不，先生，不是沙威。","en":"No, sir, not Javert","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-31-010","lineIndex":10,"speaker":"Thénardier","original":"Ce journal vous prouv'ra le contraire","ipa":"/sə ʒuʁnal vu pʁuvʁa lə kɔ̃tʁɛʁ/","zh":"这份报纸会证明恰恰相反。","en":"This newspaper will prove the contrary.","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-31-011","lineIndex":11,"speaker":"Thénardier","original":"Et surtout pas Madeleine","ipa":"/e syʁtu pa madlɛn/","zh":"尤其是玛德琳","en":"And especially not Madeleine","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-31-012","lineIndex":12,"speaker":"Marius","original":"Mon enquête m'a conduit jusqu'à Montreuil-sur-Mer","ipa":"/mɔ̃n ɑ̃kɛt ma kɔ̃dɥi ʒyska mɔ̃tʁœjsyʁmɛʁ/","zh":"我的调查把我带到了滨海蒙特勒伊","en":"My investigation took me to Montreuil-sur-Mer","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-31-013","lineIndex":13,"speaker":"Marius","original":"Et je sais bien ce que j'ai découvert","ipa":"/e ʒə sɛ bjɛ̃ sə kə ʒe dekuvɛʁ/","zh":"我很清楚我发现了什么","en":"And I know very well what I discovered","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-31-014","lineIndex":14,"speaker":"Thénardier","original":"Vous vous trompez mais pour me faire parler","ipa":"/vu vu tʁɔ̃pe mɛ puʁ mə fɛʁ paʁle/","zh":"你错了，但要让我说话","en":"You are wrong but to make me talk","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-31-015","lineIndex":15,"speaker":"Thénardier","original":"Il faut payer","ipa":"/il fo pɛje/","zh":"得付钱。","en":"You have to pay.","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-31-016","lineIndex":16,"speaker":"Madame Thénardier","original":"Cinq cent francs, beau billet","ipa":"/sɛ̃ sɑ̃ fʁɑ̃ bo bijɛ/","zh":"五百法郎，好大一张钞票。","en":"Five hundred francs, beautiful note","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-31-017","lineIndex":17,"speaker":"Madame Thénardier","original":"J'savais pas qu'on en f'sait d'aussi grand","ipa":"/ʒsavɛ pa kɔ̃n ɑ̃ fəzɛ dosi ɡʁɑ̃/","zh":"我还不知道，钞票能印得这么大。","en":"I did not know they made them this big","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-31-018","lineIndex":18,"speaker":"Thénardier","original":"Jean Valjean, c'est Madeleine","ipa":"/ʒɑ̃ valʒɑ̃ sɛ madlɛn/","zh":"冉阿让，就是马德兰。","en":"Jean Valjean is Madeleine.","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-31-019","lineIndex":19,"speaker":"Thénardier","original":"Comme ce journal vous l'explique sans peine","ipa":"/kɔm sə ʒuʁnal vu lɛksplik sɑ̃ pɛn/","zh":"正如这份报纸说得明明白白。","en":"As this newspaper easily explains to you","note":"","sourceLineIndex":19},{"id":"les-miserables-1980-31-020","lineIndex":20,"speaker":"Thénardier","original":"Mais pourtant ce coquin","ipa":"/mɛ puʁtɑ̃ sə kokɛ̃/","zh":"可这个无赖","en":"But nevertheless this rascal","note":"","sourceLineIndex":20},{"id":"les-miserables-1980-31-021","lineIndex":21,"speaker":"Thénardier","original":"Est un voleur et un assassin","ipa":"/ɛt œ̃ volœʁ e œ̃n asasɛ̃/","zh":"终究是个小偷和杀人犯。","en":"Is a thief and a murderer","note":"","sourceLineIndex":21},{"id":"les-miserables-1980-31-022","lineIndex":22,"speaker":"Les Thénardier","original":"Le 6 juin, les malins","ipa":"/lə si ʒyɛ̃ le malɛ̃/","zh":"6 月 6 日，那些机灵人","en":"June 6, the smart ones","note":"","sourceLineIndex":22},{"id":"les-miserables-1980-31-023","lineIndex":23,"speaker":"Les Thénardier","original":"S'étaient tous réfugiés aux égouts","ipa":"/setɛ tus ʁefyʒjez oz eɡu/","zh":"都躲到了下水道里","en":"They all took refuge in the sewers","note":"","sourceLineIndex":23},{"id":"les-miserables-1980-31-024","lineIndex":24,"speaker":"Les Thénardier","original":"Un cadavre sur le dos","ipa":"/œ̃ kadavʁ syʁ lə do/","zh":"背上有一具尸体","en":"A corpse on his back","note":"","sourceLineIndex":24},{"id":"les-miserables-1980-31-025","lineIndex":25,"speaker":"Thénardier","original":"Je l'ai vu qui cherchait la sortie","ipa":"/ʒə le vy ki ʃɛʁʃɛ la sɔʁti/","zh":"我看见他在寻找出口","en":"I saw him looking for the exit","note":"","sourceLineIndex":25},{"id":"les-miserables-1980-31-026","lineIndex":26,"speaker":"Thénardier","original":"Part à deux, m'a-t-il dit","ipa":"/paʁ a dø matil di/","zh":"“对半分。”他对我说","en":"“Half and half, ” he told me","note":"","sourceLineIndex":26},{"id":"les-miserables-1980-31-027","lineIndex":27,"speaker":"Thénardier","original":"De l'argent qu'a sur elle ma victime","ipa":"/də laʁʒɑ̃ ka syʁ ɛl ma viktim/","zh":"是我受害者身上带的钱。","en":"“of the money my victim has on him.”","note":"","sourceLineIndex":27},{"id":"les-miserables-1980-31-028","lineIndex":28,"speaker":"Thénardier","original":"Et cette bague en prime","ipa":"/e sɛt baɡ ɑ̃ pʁim/","zh":"再加上这枚戒指。","en":"And this ring as a bonus","note":"","sourceLineIndex":28},{"id":"les-miserables-1980-31-029","lineIndex":29,"speaker":"Madame Thénardier","original":"Pauv'monsieur comme vous voilà surpris","ipa":"/pov məsjø kɔm vu vwala syʁpʁi/","zh":"可怜的先生，瞧您多吃惊。","en":"Poor sir, how surprised you are","note":"","sourceLineIndex":29},{"id":"les-miserables-1980-31-030","lineIndex":30,"speaker":"Madame Thénardier","original":"Ah Monsieur c'est affreux","ipa":"/a məsjø sɛt afʁø/","zh":"哎呀，先生，真是太可怕了。","en":"Ah sir, it's awful","note":"","sourceLineIndex":30},{"id":"les-miserables-1980-31-031","lineIndex":31,"speaker":"Madame Thénardier","original":"Quand c'est la famille qui vous trahit","ipa":"/kɑ̃ sɛ la famij ki vu tʁai/","zh":"当家人背叛了你","en":"When it's the family that betrays you","note":"","sourceLineIndex":31},{"id":"les-miserables-1980-31-032","lineIndex":32,"speaker":"Marius","original":"C'était lui, suis-je bête","ipa":"/setɛ lɥi sɥiʒ bɛt/","zh":"原来是他，我真傻。","en":"It was him, am I stupid","note":"","sourceLineIndex":32},{"id":"les-miserables-1980-31-033","lineIndex":33,"speaker":"Marius","original":"C'est un saint que j'ai cru malhonnête","ipa":"/sɛt œ̃ sɛ̃ kə ʒe kʁy malɔnɛt/","zh":"他是圣人，我却曾以为他不诚实。","en":"He is a saint whom I believed dishonest.","note":"","sourceLineIndex":33},{"id":"les-miserables-1980-31-034","lineIndex":34,"speaker":"Marius","original":"Viens Cosette, c'est la fête","ipa":"/vjɛ̃ kozɛt sɛ la fɛt/","zh":"来吧，珂赛特，今天真是大喜日子。","en":"Come Cosette, it's a party","note":"","sourceLineIndex":34},{"id":"les-miserables-1980-31-035","lineIndex":35,"speaker":"Marius","original":"Ton père est de retour à Paris","ipa":"/tɔ̃ pɛʁ ɛ də ʁətuʁ a paʁi/","zh":"你父亲回到巴黎了。","en":"Your father is back in Paris.","note":"","sourceLineIndex":35}],"sourceOrder":31,"displayOrder":31},{"order":32,"id":"32-epilogue-la-lumiere","title":"Épilogue: La lumière","titleZh":"尾声：光","lines":[{"id":"les-miserables-1980-32-001","lineIndex":1,"speaker":"JEAN VALJEAN","original":"Je ne pars plus seul","ipa":"/ʒə nə paʁ ply sœl/","zh":"我不再一个人去","en":"I'm not going alone anymore","note":"","sourceLineIndex":1},{"id":"les-miserables-1980-32-002","lineIndex":2,"speaker":"JEAN VALJEAN","original":"Je suis heureux","ipa":"/ʒə sɥiz øʁø/","zh":"我很高兴","en":"I'm happy","note":"","sourceLineIndex":2},{"id":"les-miserables-1980-32-003","lineIndex":3,"speaker":"JEAN VALJEAN","original":"J'ai revu ton sourire","ipa":"/ʒe ʁəvy tɔ̃ suʁiʁ/","zh":"我再次看到了你的微笑","en":"I saw your smile again","note":"","sourceLineIndex":3},{"id":"les-miserables-1980-32-004","lineIndex":4,"speaker":"JEAN VALJEAN","original":"Juste avant de mourir","ipa":"/ʒyst avɑ̃ də muʁiʁ/","zh":"就在我死之前","en":"Just before I die","note":"","sourceLineIndex":4},{"id":"les-miserables-1980-32-005","lineIndex":5,"speaker":"COSETTE","original":"Vous vivrez, mon père, vous allez vivre","ipa":"/vu vivʁe mɔ̃ pɛʁ vuz ale vivʁ/","zh":"你活下去，我的父亲，你会活下去","en":"You will live, my father, you will live","note":"","sourceLineIndex":5},{"id":"les-miserables-1980-32-006","lineIndex":6,"speaker":"COSETTE","original":"Moi, je veux que vous viviez, entendez-vous!","ipa":"/mwa ʒə vø kə vu vivje ɑ̃tɑ̃devu/","zh":"我希望你活下去，你听到了吗！","en":"I want you to live, you hear!","note":"","sourceLineIndex":6},{"id":"les-miserables-1980-32-007","lineIndex":7,"speaker":"JEAN VALJEAN","original":"Oui, Cosette, défends-moi de mourir","ipa":"/wi kozɛt defɑ̃mwa də muʁiʁ/","zh":"是的，珂赛特，别让我死","en":"Yes, Cosette, forbid me from dying","note":"","sourceLineIndex":7},{"id":"les-miserables-1980-32-008","lineIndex":8,"speaker":"JEAN VALJEAN","original":"J'aimerais t'obéir","ipa":"/ʒɛmʁɛ tobeiʁ/","zh":"我愿意服从你","en":"I would like to obey you","note":"","sourceLineIndex":8},{"id":"les-miserables-1980-32-009","lineIndex":9,"speaker":"JEAN VALJEAN","original":"La lumière est dans le cœur des hommes","ipa":"/la lymjɛʁ ɛ dɑ̃ lə kœʁ dez ɔm/","zh":"光明在人心","en":"The light is in the hearts of men","note":"","sourceLineIndex":9},{"id":"les-miserables-1980-32-010","lineIndex":10,"speaker":"JEAN VALJEAN","original":"Mais s'épuise de brûler pour personne","ipa":"/mɛ sepɥiz də bʁyle puʁ pɛʁsɔn/","zh":"但若只为一个人燃烧，它终会耗尽。","en":"but it is exhausted by burning for one person.","note":"","sourceLineIndex":10},{"id":"les-miserables-1980-32-011","lineIndex":11,"speaker":"JEAN VALJEAN","original":"Aimez-vous pour vaincre les ténèbres","ipa":"/ɛmevu puʁ vɛ̃kʁ le tenɛbʁ/","zh":"要彼此相爱，才能战胜黑暗。","en":"Love one another to conquer darkness.","note":"","sourceLineIndex":11},{"id":"les-miserables-1980-32-012","lineIndex":12,"speaker":"JEAN VALJEAN","original":"Tant qu'il y aura partout orgueil, ignorance et misère","ipa":"/tɑ̃ kil i oʁa paʁtu ɔʁɡœj injoʁɑ̃s e mizɛʁ/","zh":"只要骄傲、无知和痛苦无处不在","en":"As long as there is pride, ignorance and misery everywhere","note":"","sourceLineIndex":12},{"id":"les-miserables-1980-32-013","lineIndex":13,"speaker":"JEAN VALJEAN","original":"La lumière, au matin de justice","ipa":"/la lymjɛʁ o matɛ̃ də ʒystis/","zh":"正义之晨的光明","en":"The light, on the morning of justice","note":"","sourceLineIndex":13},{"id":"les-miserables-1980-32-014","lineIndex":14,"speaker":"JEAN VALJEAN","original":"Puisse enfin décapiter nos vices","ipa":"/pɥis ɑ̃fɛ̃ dekapite no vis/","zh":"愿它终于斩断我们的恶习。","en":"may it finally behead our vices.","note":"","sourceLineIndex":14},{"id":"les-miserables-1980-32-015","lineIndex":15,"speaker":"JEAN VALJEAN","original":"Dans un monde où Dieu pourrait se plaire","ipa":"/dɑ̃z œ̃ mɔ̃d u djø puʁɛ sə plɛʁ/","zh":"在一个上帝所喜悦的世界","en":"In a world where God could please","note":"","sourceLineIndex":15},{"id":"les-miserables-1980-32-016","lineIndex":16,"speaker":"JEAN VALJEAN","original":"S'il décidait un jour de redescendre sur la terre","ipa":"/sil desidɛt œ̃ ʒuʁ də ʁədɛsɑ̃dʁ syʁ la tɛʁ/","zh":"若有一天，他决定重返人世。","en":"If one day he decides to come back down on earth","note":"","sourceLineIndex":16},{"id":"les-miserables-1980-32-017","lineIndex":17,"speaker":"JEAN VALJEAN","original":"Cosette, aime-le","ipa":"/kozɛt ɛmlə/","zh":"珂赛特，爱他","en":"Cosette, love him","note":"","sourceLineIndex":17},{"id":"les-miserables-1980-32-018","lineIndex":18,"speaker":"JEAN VALJEAN","original":"Marius, aimez-la","ipa":"/maʁjys ɛmela/","zh":"马吕斯，爱她","en":"Marius, love her","note":"","sourceLineIndex":18},{"id":"les-miserables-1980-32-019","lineIndex":19,"speaker":"JEAN VALJEAN","original":"Qui aime sa femme, sans le savoir, aime Dieu","ipa":"/ki ɛm sa fam sɑ̃ lə savwaʁ ɛm djø/","zh":"爱自己的妻子的人，不知不觉也在爱上帝。","en":"Whoever loves his wife, without knowing it, loves God.","note":"","sourceLineIndex":19}],"sourceOrder":32,"displayOrder":32}];
